(function(){
  if (typeof LESSONS === "undefined") return;
  if (typeof STAGES !== "undefined") STAGES[23] = "Tin học 11 — Tin học ứng dụng";
  if (typeof QUESTION_BANK !== "undefined") QUESTION_BANK.push.apply(QUESTION_BANK, [{"id":"UB-mc-101","type":"mc","topic":"C","grade":11,"level":"easy","question":"Trong một hệ quản trị cơ sở dữ liệu, đối tượng nào thật sự chứa dữ liệu?","options":["Bảng","Biểu mẫu","Truy vấn","Báo cáo"],"answer":0,"explain":"Bảng là nơi lưu dữ liệu thật theo hàng và cột. Biểu mẫu chỉ là màn hình nhập/xem, truy vấn chỉ lọc tìm, báo cáo chỉ trình bày để in; ba loại này đều lấy dữ liệu từ bảng chứ không tự chứa."},{"id":"UB-mc-102","type":"mc","topic":"C","grade":11,"level":"easy","question":"Muốn tạo một màn hình để người dùng nhập từng bản ghi cho dễ nhìn, ít nhầm ô, ta dùng đối tượng nào?","options":["Truy vấn","Báo cáo","Biểu mẫu","Bảng"],"answer":2,"explain":"Biểu mẫu (form) là màn hình nhập và xem từng bản ghi cho thân thiện. Truy vấn dùng để lọc tìm, báo cáo dùng để in, còn nhập thẳng vào bảng thì dễ nhầm ô vì bảng thường dày đặc."},{"id":"UB-mc-103","type":"mc","topic":"C","grade":11,"level":"medium","question":"Vì sao một tệp cơ sở dữ liệu không giống một tệp bảng tính thông thường, dù cả hai đều có hàng và cột?","options":["Vì tệp CSDL không thể chứa số, chỉ chứa được chữ","Vì tệp CSDL có thể chứa nhiều đối tượng (bảng, biểu mẫu, truy vấn, báo cáo) và mỗi cột bị ràng buộc kiểu dữ liệu","Vì bảng tính có thể liên kết nhiều bảng còn CSDL thì không","Vì tệp CSDL không cần lưu vào thư mục nào trên máy"],"answer":1,"explain":"Tệp CSDL là một hệ thống gồm nhiều đối tượng và ràng buộc mỗi cột một kiểu dữ liệu cố định để giữ dữ liệu sạch. CSDL vẫn chứa số; chính CSDL (không phải bảng tính) mới liên kết nhiều bảng; và tệp CSDL vẫn phải lưu trên máy."},{"id":"UB-mc-104","type":"mc","topic":"C","grade":11,"level":"medium","question":"Khi bắt đầu xây một CSDL mới cho câu lạc bộ sách, bước hợp lí đầu tiên là gì?","options":["Nhập ngay danh sách thành viên rồi tính sau","Tạo một truy vấn tìm người mượn quá hạn","Tạo tệp CSDL rỗng, đặt tên và chọn nơi lưu","Thiết kế mẫu báo cáo để in danh sách"],"answer":2,"explain":"Phải có tệp CSDL rỗng làm chỗ chứa trước, rồi mới tạo bảng, nhập dữ liệu và khai thác. Chưa có bảng thì không thể nhập dữ liệu, cũng chưa có gì để truy vấn hay đưa vào báo cáo."},{"id":"UB-mc-105","type":"mc","topic":"C","grade":11,"level":"hard","question":"Bạn thủ quỹ lỡ tay xoá đối tượng truy vấn \"Muon_QuaHan\". Điều gì xảy ra với dữ liệu?","options":["Mất toàn bộ dữ liệu về việc mượn sách vì truy vấn lưu dữ liệu đó","Mất các bản ghi quá hạn nhưng giữ lại bản ghi đúng hạn","Toàn bộ tệp CSDL bị xoá theo","Không mất bản ghi nào, vì truy vấn chỉ lọc dữ liệu đang nằm trong bảng"],"answer":3,"explain":"Truy vấn không chứa dữ liệu, nó chỉ là câu hỏi lọc trên dữ liệu đang nằm trong bảng, nên xoá nó không làm mất bản ghi nào. Muốn dùng lại chỉ cần tạo truy vấn khác. Chỉ khi xoá bảng mới thật sự mất dữ liệu."},{"id":"UB-tf-101","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Hệ QTCSDL là phần mềm cho phép tạo, nhập và khai thác cơ sở dữ liệu ngay trên máy.","correct":true},{"text":"Trong hệ QTCSDL, cả bảng, biểu mẫu và truy vấn đều là nơi lưu trữ dữ liệu riêng của mình.","correct":false},{"text":"Báo cáo là đối tượng dùng để trình bày dữ liệu cho việc in ấn hoặc xuất file.","correct":true},{"text":"Biểu mẫu chủ yếu dùng để nhập và xem từng bản ghi một cách dễ nhìn.","correct":true}],"explain":"(a) Đúng — đó là chức năng cốt lõi của hệ QTCSDL. (b) Sai — chỉ bảng chứa dữ liệu thật, biểu mẫu và truy vấn chỉ làm việc trên dữ liệu của bảng. (c) Đúng — báo cáo phục vụ trình bày, in ấn. (d) Đúng — biểu mẫu là màn hình nhập/xem thân thiện."},{"id":"UB-tf-102","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Một tệp CSDL có thể chứa nhiều bảng liên quan cùng với các biểu mẫu, truy vấn và báo cáo.","correct":true},{"text":"Trong bảng của hệ QTCSDL, mỗi cột được ràng buộc một kiểu dữ liệu cố định.","correct":true},{"text":"Có thể nhập dữ liệu vào bảng ngay cả khi chưa tạo bảng nào trong CSDL.","correct":false},{"text":"Mở một tệp CSDL chỉ là mở một trang tính đơn giản như bảng tính.","correct":false}],"explain":"(a) Đúng — tệp CSDL là một hệ thống nhiều đối tượng. (b) Đúng — ràng buộc kiểu giúp chặn dữ liệu sai. (c) Sai — phải có bảng làm chỗ chứa thì mới nhập được. (d) Sai — tệp CSDL chứa cả hệ thống quản lí chứ không phải một trang tính."},{"id":"UB-tf-103","type":"tf","topic":"C","grade":11,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Xoá một truy vấn sẽ làm mất các bản ghi mà truy vấn đó từng hiển thị.","correct":false},{"text":"Quy trình chung là tạo tệp CSDL rỗng, rồi tạo bảng, nhập dữ liệu, cuối cùng khai thác.","correct":true},{"text":"Truy vấn giúp lọc và trả về đúng những bản ghi thoả điều kiện đặt ra.","correct":true},{"text":"Vì đều có hàng và cột nên bảng tính và hệ QTCSDL giống hệt nhau về cách quản lí dữ liệu.","correct":false}],"explain":"(a) Sai — truy vấn không chứa dữ liệu nên xoá nó không mất bản ghi nào. (b) Đúng — đó là trình tự khởi đầu chuẩn. (c) Đúng — đó chính là vai trò của truy vấn. (d) Sai — hệ QTCSDL ràng buộc kiểu dữ liệu, tổ chức nhiều đối tượng và giữ dữ liệu có cấu trúc, khác với bảng tính."},{"id":"UB-mc-201","type":"mc","topic":"C","grade":11,"level":"easy","question":"Trong một bảng của cơ sở dữ liệu, mỗi cột được gọi là gì?","options":["Một bản ghi","Một trường","Một khoá chính","Một biểu mẫu"],"answer":1,"explain":"Mỗi cột là một trường (mô tả một loại thông tin). Bản ghi là một hàng, không phải cột. Khoá chính là một trường đặc biệt được chỉ định, không phải khái niệm chỉ mọi cột. Biểu mẫu là một đối tượng khác dùng để nhập/xem dữ liệu, không phải cột."},{"id":"UB-mc-202","type":"mc","topic":"C","grade":11,"level":"easy","question":"Để trường `NgayBan` có thể sắp xếp và lọc đúng theo trục thời gian, nên chọn kiểu dữ liệu nào?","options":["Kiểu văn bản","Kiểu số","Kiểu ngày/giờ","Kiểu lôgic"],"answer":2,"explain":"Kiểu ngày/giờ giúp phần mềm hiểu giá trị là mốc thời gian nên sắp xếp và lọc chính xác. Kiểu văn bản sẽ sắp theo mặt chữ (\"12/9\" trước \"2/9\"), sai thứ tự thời gian. Kiểu số không biểu diễn được ngày tháng đầy đủ. Kiểu lôgic chỉ nhận đúng/sai nên không chứa được ngày."},{"id":"UB-mc-203","type":"mc","topic":"C","grade":11,"level":"medium","question":"Vì sao không nên chọn trường `HoTen` làm khoá chính cho bảng theo dõi bán hàng?","options":["Vì họ tên là kiểu văn bản mà khoá chính bắt buộc phải là kiểu số","Vì họ tên quá dài khiến phần mềm không lưu được","Vì khoá chính chỉ được đặt sau khi đã nhập hết dữ liệu","Vì hai người có thể trùng họ tên nên giá trị không chắc chắn duy nhất"],"answer":3,"explain":"Khoá chính phải duy nhất, nhưng hai người có thể trùng họ tên nên `HoTen` không bảo đảm điều đó. Khoá chính không bắt buộc phải là kiểu số. Độ dài họ tên không phải lí do kĩ thuật khiến không lưu được. Khoá chính được đặt khi thiết kế cấu trúc, trước khi nhập dữ liệu."},{"id":"UB-mc-204","type":"mc","topic":"C","grade":11,"level":"medium","question":"Bạn muốn thêm một trường mới và đổi kiểu dữ liệu của trường `SoLy` từ văn bản sang số. Bạn nên làm việc này ở đâu?","options":["Ở chế độ thiết kế của bảng","Ở chế độ nhập dữ liệu (bảng lưới)","Trong cửa sổ tạo báo cáo","Không sửa được, phải xoá bảng và tạo lại"],"answer":0,"explain":"Việc thêm/bớt trường và đổi kiểu dữ liệu thuộc về cấu trúc bảng, nên thực hiện ở chế độ thiết kế. Chế độ nhập dữ liệu chỉ để gõ và xem bản ghi. Cửa sổ báo cáo dùng để trình bày dữ liệu, không sửa cấu trúc. Không cần xoá bảng vì chế độ thiết kế cho phép sửa cấu trúc trực tiếp."},{"id":"UB-mc-205","type":"mc","topic":"C","grade":11,"level":"hard","question":"Trong bảng `BanNuoc`, trường `DaTra` cho biết một lần bán đã thu tiền hay chưa. Cách thiết kế nào giúp về sau đếm nhanh số lần chưa thu tiền và tránh dữ liệu lộn xộn nhất?","options":["Để `DaTra` kiểu văn bản để người nhập tự gõ \"đã trả\" hoặc \"chưa\"","Để `DaTra` kiểu lôgic chỉ nhận Đúng/Sai","Gộp thông tin trả tiền vào trường `HoTen` cho gọn","Để `DaTra` kiểu số và quy ước nhập số điện thoại người trả"],"answer":1,"explain":"Trạng thái đã/chưa trả chỉ có hai khả năng nên kiểu lôgic (Đúng/Sai) là phù hợp nhất, giúp lọc và đếm chính xác. Kiểu văn bản tự gõ dễ sinh ra \"đã trả\", \"da tra\", \"rồi\"… lộn xộn khó đếm. Gộp vào `HoTen` vi phạm nguyên tắc mỗi trường một loại thông tin. Nhập số điện thoại vào trường trạng thái là sai mục đích và không cho biết đã trả hay chưa."},{"id":"UB-tf-201","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Trong một bảng, mỗi bản ghi tương ứng với một hàng dữ liệu.","correct":true},{"text":"Mỗi trường nên gộp nhiều loại thông tin để tiết kiệm số cột.","correct":false},{"text":"Kiểu dữ liệu của một trường quyết định loại giá trị mà trường đó được phép chứa.","correct":true},{"text":"Tên trường bắt buộc phải trùng với nội dung của bản ghi đầu tiên.","correct":false}],"explain":"(a) Đúng — một hàng là một bản ghi. (b) Sai — nguyên tắc là mỗi trường chỉ chứa một loại thông tin; gộp nhiều loại gây khó lọc, khó tìm. (c) Đúng — kiểu dữ liệu xác định giá trị hợp lệ cho trường. (d) Sai — tên trường mô tả loại thông tin của cột, độc lập với nội dung từng bản ghi."},{"id":"UB-tf-202","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai về khoá chính:","statements":[{"text":"Giá trị của trường khoá chính không được trùng nhau giữa các bản ghi.","correct":true},{"text":"Trường khoá chính có thể để trống ở một vài bản ghi cũng không sao.","correct":false},{"text":"Dùng một trường mã định danh riêng thường là cách chọn khoá chính tốt.","correct":true},{"text":"Khoá chính chỉ có thể là trường thuộc kiểu số, không thể là kiểu văn bản.","correct":false}],"explain":"(a) Đúng — khoá chính phải duy nhất. (b) Sai — khoá chính không được để trống ở bất kì bản ghi nào. (c) Đúng — trường mã riêng gọn, ổn định và chắc chắn duy nhất nên hợp làm khoá chính. (d) Sai — khoá chính có thể là kiểu văn bản (ví dụ mã dạng chữ), miễn là duy nhất và không trống."},{"id":"UB-tf-203","type":"tf","topic":"C","grade":11,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai về kiểu dữ liệu và hai chế độ làm việc với bảng:","statements":[{"text":"Nếu để trường `SoLy` là kiểu văn bản thì phần mềm vẫn cộng được tổng số ly như với kiểu số.","correct":false},{"text":"Chọn đúng kiểu dữ liệu giúp phần mềm canh khuôn dữ liệu và hỗ trợ tính toán, lọc về sau.","correct":true},{"text":"Chế độ thiết kế dùng để dựng và sửa cấu trúc bảng, còn chế độ nhập dữ liệu để gõ các bản ghi.","correct":true},{"text":"Chế độ thiết kế và chế độ nhập dữ liệu là hai bảng hoàn toàn khác nhau, không liên quan tới nhau.","correct":false}],"explain":"(a) Sai — với kiểu văn bản, các số bị coi là xâu chữ nên không cộng lại thành tổng được. (b) Đúng — kiểu dữ liệu đúng giữ dữ liệu sạch và mở đường cho tính toán, lọc, sắp xếp. (c) Đúng — đó là vai trò của hai chế độ. (d) Sai — hai chế độ chỉ là hai cách nhìn cùng một bảng, không phải hai bảng khác nhau."},{"id":"UB-mc-301","type":"mc","topic":"C","grade":11,"level":"easy","question":"Khi bắt đầu tạo lập trên phần mềm, thứ tự đúng của ba việc là gì?","options":["Nhập bản ghi, rồi tạo bảng, rồi tạo cơ sở dữ liệu","Tạo cơ sở dữ liệu, rồi tạo bảng, rồi nhập bản ghi","Tạo bảng, rồi tạo cơ sở dữ liệu, rồi nhập bản ghi","Tạo cơ sở dữ liệu, rồi nhập bản ghi, rồi tạo bảng"],"answer":1,"explain":"Phải có kho tổng (CSDL) trước, rồi mới dựng bảng bên trong, cuối cùng mới xếp dữ liệu vào. Các phương án kia đảo thứ tự nên vô lí: chưa có bảng thì không có chỗ nhập bản ghi, và bảng luôn nằm trong một CSDL nên không thể tạo bảng trước CSDL."},{"id":"UB-mc-302","type":"mc","topic":"C","grade":11,"level":"easy","question":"Để khai báo cấu trúc bảng (thêm trường, chọn kiểu dữ liệu, đặt khoá chính), em nên mở bảng ở chế độ nào?","options":["Chế độ thiết kế","Chế độ nhập liệu (lưới dòng - cột)","Chế độ xem báo cáo","Chế độ sao lưu"],"answer":0,"explain":"Chế độ thiết kế là nơi khai báo và chỉnh sửa cấu trúc bảng. Chế độ nhập liệu chỉ để gõ dữ liệu vào các dòng; xem báo cáo và sao lưu là chức năng khác, không dùng để sửa cấu trúc trường."},{"id":"UB-mc-303","type":"mc","topic":"C","grade":11,"level":"medium","question":"Vì sao ngay sau khi tạo bảng nên nhập thử vài bản ghi mẫu?","options":["Để CSDL không bị rỗng, nếu không phần mềm sẽ tự xoá bảng","Vì bắt buộc phải có ít nhất 100 bản ghi mới lưu được bảng","Để phần mềm tự động sinh thêm các trường còn thiếu","Để kiểm tra cấu trúc có đúng không và phát hiện sớm lỗi kiểu dữ liệu, khoá chính"],"answer":3,"explain":"Nhập vài dòng thử giúp kiểm tra ngay: kiểu dữ liệu nhận đúng chưa, khoá chính có chặn trùng không. Bảng rỗng vẫn tồn tại bình thường nên không có chuyện tự xoá; không có yêu cầu số lượng bản ghi tối thiểu; phần mềm cũng không tự sinh trường thay em."},{"id":"UB-mc-304","type":"mc","topic":"C","grade":11,"level":"medium","question":"Cách đặt tên trường nào sau đây là hợp lí nhất khi tạo bảng?","options":["`Ngày mượn sách` để đọc cho rõ nghĩa","`Field1` cho nhanh, khỏi nghĩ tên","`NgayMuon` viết liền, không dấu","`123` cho ngắn gọn"],"answer":2,"explain":"Tên trường nên viết liền, không dấu, gợi đúng nội dung như `NgayMuon` để về sau viết truy vấn gọn và tránh lỗi. Tên có khoảng trắng và dấu dễ gây rắc rối; `Field1` không gợi nghĩa; tên chỉ gồm chữ số vừa khó hiểu vừa dễ bị coi là không hợp lệ."},{"id":"UB-mc-305","type":"mc","topic":"C","grade":11,"level":"hard","question":"Bạn An tạo bảng `SACH` nhưng quên đặt khoá chính cho `MaSach`. Hậu quả dễ gặp nhất là gì?","options":["Không thể nhập được bất kì bản ghi nào vào bảng","Có thể vô tình nhập hai sách khác nhau cùng mã mà phần mềm không báo lỗi","Phần mềm tự động xoá toàn bộ bảng khi lưu","Trường `NamXB` sẽ tự chuyển thành kiểu chữ"],"answer":1,"explain":"Khoá chính có nhiệm vụ chặn trùng ở trường định danh. Thiếu nó, hai bản ghi có thể cùng `MaSach` mà không bị cảnh báo, gây nhầm lẫn khi tra cứu. Bảng vẫn nhập được dữ liệu bình thường, không bị tự xoá, và việc quên khoá chính không làm đổi kiểu của trường khác."},{"id":"UB-tf-301","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Có thể tạo một bảng mà không cần có cơ sở dữ liệu nào chứa nó.","correct":false},{"text":"Một cơ sở dữ liệu có thể chứa nhiều bảng khác nhau.","correct":true},{"text":"Khi tạo cơ sở dữ liệu mới, nên đặt tên gợi nội dung thay vì để tên mặc định.","correct":true},{"text":"Bảng vừa tạo xong bắt buộc phải có sẵn dữ liệu thì mới lưu được.","correct":false}],"explain":"(a) Sai — bảng luôn nằm bên trong một CSDL, không thể đứng độc lập. (b) Đúng — một CSDL như kho tổng, chứa nhiều bảng như `SACH`, `MUON`. (c) Đúng — tên gợi nội dung như `QuanLySach` giúp quản lí dễ, tránh nhầm. (d) Sai — bảng rỗng vẫn lưu được bình thường, dữ liệu nhập sau."},{"id":"UB-tf-302","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Chế độ thiết kế dùng để khai báo và chỉnh sửa cấu trúc của bảng.","correct":true},{"text":"Muốn gõ dữ liệu vào các dòng, ta mở bảng ở chế độ nhập liệu.","correct":true},{"text":"Sau khi lưu bảng thì không bao giờ còn sửa được cấu trúc nữa.","correct":false},{"text":"Đặt khoá chính là một thao tác thực hiện trong chế độ thiết kế.","correct":true}],"explain":"(a) Đúng — chế độ thiết kế là nơi khai báo trường, kiểu dữ liệu, khoá chính. (b) Đúng — chế độ nhập liệu cho gõ dữ liệu theo lưới dòng - cột. (c) Sai — mở lại bảng ở chế độ thiết kế là sửa được cấu trúc bất cứ lúc nào. (d) Đúng — đặt khoá chính thuộc phần khai báo cấu trúc, làm trong chế độ thiết kế."},{"id":"UB-tf-303","type":"tf","topic":"C","grade":11,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Đặt kiểu dữ liệu số cho trường `NamXB` giúp về sau có thể so sánh, tính toán theo năm.","correct":true},{"text":"Tên trường có khoảng trắng và dấu tiếng Việt luôn là lựa chọn tốt nhất vì dễ đọc.","correct":false},{"text":"Nhập vài bản ghi mẫu có thể giúp phát hiện sớm lỗi đặt sai kiểu dữ liệu.","correct":true},{"text":"Nếu quên lưu bảng rồi đóng phần mềm, cấu trúc vừa tạo có thể bị mất.","correct":true}],"explain":"(a) Đúng — để `NamXB` kiểu số mới so sánh, tính toán được; để kiểu chữ thì không. (b) Sai — tên có khoảng trắng và dấu gây rắc rối khi truy vấn, nên viết liền không dấu. (c) Đúng — gõ thử vài dòng lộ ngay lỗi như năm không nhận đúng, mã bị trùng. (d) Đúng — chưa lưu mà đóng phần mềm thì cấu trúc chưa ghi ra có thể mất, nên phải lưu ngay."},{"id":"UB-mc-401","type":"mc","topic":"C","grade":11,"level":"easy","question":"Lí do chính khiến ta tách dữ liệu thành nhiều bảng thay vì gộp hết vào một bảng lớn là gì?","options":["Để cơ sở dữ liệu trông có nhiều bảng hơn cho đẹp","Để tránh trùng lặp dữ liệu và giữ cho dữ liệu nhất quán","Để mỗi bảng chỉ được phép có đúng một bản ghi","Để không cần dùng khoá chính nữa"],"answer":1,"explain":"Gộp mọi thứ vào một bảng khiến thông tin của cùng một đối tượng lặp lại nhiều dòng, tốn chỗ và dễ sai khi cập nhật. Tách bảng giúp mỗi thông tin ghi một chỗ nên tránh trùng lặp và giữ nhất quán. Phương án A chỉ là hình thức, không phải lí do. C sai vì bảng vẫn chứa nhiều bản ghi. D sai vì tách bảng càng cần khoá chính để tham chiếu."},{"id":"UB-mc-402","type":"mc","topic":"C","grade":11,"level":"easy","question":"Khoá ngoài là gì?","options":["Một trường trong bảng này tham chiếu tới khoá chính của bảng khác","Một trường luôn có giá trị duy nhất trong bảng chứa nó","Một bảng phụ dùng để sao lưu dữ liệu","Một mật khẩu bảo vệ bảng khỏi bị sửa"],"answer":0,"explain":"Khoá ngoài là trường ở một bảng dùng để trỏ tới khoá chính của bảng khác, tạo liên kết giữa hai bảng. Phương án về tính duy nhất mô tả khoá chính, không phải khoá ngoài (khoá ngoài được phép lặp). Hai phương án còn lại (bảng sao lưu, mật khẩu) hoàn toàn không liên quan đến khái niệm khoá ngoài."},{"id":"UB-mc-403","type":"mc","topic":"C","grade":11,"level":"medium","question":"Trong hai bảng LOP(MaLop, TenLop) và HOCSINH(MaHS, HoTen, MaLop), trường nào là khoá ngoài và nó trỏ tới đâu?","options":["MaHS trong HOCSINH, trỏ tới TenLop của LOP","TenLop trong LOP, trỏ tới MaHS của HOCSINH","MaLop trong LOP, trỏ tới MaHS của HOCSINH","MaLop trong HOCSINH, trỏ tới MaLop (khoá chính) của LOP"],"answer":3,"explain":"HOCSINH là bảng con (phía nhiều), chứa trường MaLop dùng để cho biết mỗi học sinh thuộc lớp nào; nó trỏ tới khoá chính MaLop của bảng LOP nên là khoá ngoài. MaHS là khoá chính của HOCSINH, không phải khoá ngoài. Các phương án còn lại đảo ngược sai vai trò bảng cha - bảng con."},{"id":"UB-mc-404","type":"mc","topic":"C","grade":11,"level":"medium","question":"Trong liên kết một-nhiều giữa LOP và HOCSINH, phát biểu nào đúng?","options":["Mỗi lớp chỉ được có đúng một học sinh","Một lớp có thể có nhiều học sinh, nên nhiều bản ghi HOCSINH cùng một giá trị MaLop","Mỗi học sinh phải thuộc về nhiều lớp cùng lúc","Giá trị MaLop trong bảng HOCSINH bắt buộc phải khác nhau ở mọi dòng"],"answer":1,"explain":"Một-nhiều nghĩa là một lớp (phía một) ứng với nhiều học sinh (phía nhiều), nên trường khoá ngoài MaLop ở bảng HOCSINH được lặp lại cho các bạn cùng lớp. A và C hiểu sai chiều liên kết. D sai vì khoá ngoài được phép lặp, chỉ khoá chính mới bắt buộc duy nhất."},{"id":"UB-mc-405","type":"mc","topic":"C","grade":11,"level":"hard","question":"Bảng MUON(MaMuon, MaHS, MaSach, NgayMuon) ghi các lượt mượn sách, với MaHS trỏ sang HOCSINH và MaSach trỏ sang SACH. Thao tác nào sau đây sẽ vi phạm nguyên tắc của khoá ngoài?","options":["Thêm một lượt mượn với MaHS là mã của một học sinh đã có trong bảng HOCSINH","Hai lượt mượn khác nhau cùng có MaHS giống nhau vì cùng một bạn mượn","Thêm một lượt mượn với MaHS là một mã không hề tồn tại trong bảng HOCSINH","Một bạn xuất hiện ở nhiều dòng khác nhau trong bảng MUON"],"answer":2,"explain":"Giá trị khoá ngoài phải là giá trị đã tồn tại thật ở khoá chính bảng cha; ghi MaHS không có trong HOCSINH là trỏ vào chỗ trống nên vi phạm. Thêm lượt mượn với mã học sinh đã tồn tại là hợp lệ. Hai lượt mượn cùng một MaHS, hoặc một bạn xuất hiện nhiều dòng, đều hợp lệ vì khoá ngoài được phép lặp — một bạn mượn nhiều lần là bình thường."},{"id":"UB-tf-401","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Tách dữ liệu ra nhiều bảng giúp giảm việc lặp lại thông tin của cùng một đối tượng.","correct":true},{"text":"Khi gộp tất cả vào một bảng, việc cập nhật một thông tin bị đổi trở nên an toàn hơn.","correct":false},{"text":"Nếu mỗi thông tin gốc chỉ ghi ở một chỗ thì dễ giữ dữ liệu nhất quán hơn.","correct":true},{"text":"Trùng lặp dữ liệu không bao giờ gây ra mâu thuẫn trong cơ sở dữ liệu.","correct":false}],"explain":"(a) Đúng — tách bảng để mỗi đối tượng ghi một chỗ, bớt lặp. (b) Sai — gộp một bảng khiến phải sửa nhiều dòng, dễ sót và kém an toàn. (c) Đúng — ghi một chỗ thì cập nhật một lần là đủ, giữ được nhất quán. (d) Sai — trùng lặp chính là nguồn gốc của mâu thuẫn khi sửa sót."},{"id":"UB-tf-402","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Khoá ngoài của bảng con tham chiếu tới khoá chính của bảng cha.","correct":true},{"text":"Giá trị của khoá ngoài bắt buộc phải là duy nhất trong bảng con.","correct":false},{"text":"Nhiều bản ghi con có thể cùng trỏ tới một bản ghi cha qua khoá ngoài.","correct":true},{"text":"Khoá ngoài luôn phải trùng tên với khoá chính mà nó tham chiếu.","correct":false}],"explain":"(a) Đúng — đó là định nghĩa khoá ngoài. (b) Sai — khoá ngoài được phép lặp; chỉ khoá chính mới bắt buộc duy nhất. (c) Đúng — đây chính là bản chất liên kết một-nhiều. (d) Sai — tên trường có thể khác nhau, quan trọng là kiểu dữ liệu và ý nghĩa khớp nhau."},{"id":"UB-tf-403","type":"tf","topic":"C","grade":11,"level":"hard","question":"Cho các bảng LOP(MaLop khoá chính) và HOCSINH(MaHS khoá chính, MaLop khoá ngoài). Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Trong liên kết một-nhiều này, bảng LOP nằm ở phía một và bảng HOCSINH nằm ở phía nhiều.","correct":true},{"text":"Có thể thêm một học sinh với MaLop là một mã lớp chưa hề có trong bảng LOP mà vẫn hợp lệ.","correct":false},{"text":"Đổi tên một lớp chỉ cần sửa một dòng trong bảng LOP, mọi học sinh thuộc lớp đó vẫn hiểu đúng.","correct":true},{"text":"Vì MaLop là khoá ngoài nên trong bảng HOCSINH mỗi giá trị MaLop chỉ được xuất hiện một lần.","correct":false}],"explain":"(a) Đúng — phía \"một\" giữ khoá chính (LOP), phía \"nhiều\" giữ khoá ngoài (HOCSINH). (b) Sai — giá trị khoá ngoài phải tồn tại ở bảng cha, mã lớp chưa có là trỏ vào chỗ trống. (c) Đúng — nhờ tham chiếu qua mã, sửa ở bảng cha một lần là đủ. (d) Sai — khoá ngoài được phép lặp; nhiều học sinh cùng lớp thì MaLop trùng nhau là bình thường."},{"id":"UB-mc-501","type":"mc","topic":"C","grade":11,"level":"easy","question":"Trong một bảng dữ liệu, mỗi dòng biểu diễn điều gì?","options":["Một trường","Một bản ghi","Một khoá chính","Một biểu mẫu"],"answer":1,"explain":"Mỗi dòng của bảng là một bản ghi, mỗi cột là một trường. 'Trường' là cột nên sai. 'Khoá chính' chỉ là một trường đặc biệt dùng để phân biệt các bản ghi. 'Biểu mẫu' là giao diện nhập liệu, không phải một dòng trong bảng."},{"id":"UB-mc-502","type":"mc","topic":"C","grade":11,"level":"easy","question":"Để sửa lại một ngày bị gõ nhầm trong một bản ghi, cách làm đúng là gì?","options":["Xoá cả bản ghi rồi nhập lại toàn bộ","Đổi kiểu dữ liệu của trường ngày","Tạo thêm một bản ghi mới có ngày đúng","Nhấp vào đúng ô cần sửa, thay giá trị rồi lưu"],"answer":3,"explain":"Sửa chỉ cần nhấp vào đúng ô, thay giá trị và lưu; các ô khác giữ nguyên. Xoá cả bản ghi rồi nhập lại vừa mất công vừa rủi ro. Đổi kiểu dữ liệu là thay cấu trúc bảng, không liên quan. Tạo bản ghi mới sẽ gây trùng lặp thông tin."},{"id":"UB-mc-503","type":"mc","topic":"C","grade":11,"level":"medium","question":"Vì sao dùng biểu mẫu (form) thường giúp nhập liệu ít nhầm hơn nhập thẳng trên bảng nhiều cột?","options":["Vì biểu mẫu lưu dữ liệu vào một bảng khác an toàn hơn","Vì biểu mẫu tự động sửa mọi lỗi của người nhập","Vì biểu mẫu chỉ hiện một bản ghi mỗi lần với các ô có nhãn rõ ràng","Vì biểu mẫu không cho phép xoá bản ghi"],"answer":2,"explain":"Biểu mẫu hiển thị một bản ghi mỗi lần, mỗi trường là một ô có nhãn, nên khó gõ lạc sang trường khác. Dữ liệu vẫn ghi vào cùng một bảng chứ không phải bảng khác. Biểu mẫu không tự sửa lỗi thay người dùng. Việc xoá được hay không không phải lí do giảm nhầm khi nhập."},{"id":"UB-mc-504","type":"mc","topic":"C","grade":11,"level":"medium","question":"Khi thêm một bản ghi mới mà phần mềm báo lỗi không cho lưu, nguyên nhân hợp lí nhất là gì?","options":["Giá trị khoá chính vừa nhập trùng với một bản ghi đã có","Bảng đang được sắp xếp theo ngày","Biểu mẫu đang hiển thị bản ghi cũ","Có quá nhiều cột trong bảng"],"answer":0,"explain":"Khi thêm, phần mềm kiểm tra khoá chính phải khác mọi bản ghi đã có; trùng khoá sẽ bị chặn lưu. Việc bảng đang sắp xếp hay có nhiều cột không ngăn việc lưu. Biểu mẫu hiển thị bản ghi nào cũng không gây lỗi khi giá trị hợp lệ."},{"id":"UB-mc-505","type":"mc","topic":"C","grade":11,"level":"hard","question":"Bạn cần xoá đúng bản ghi mượn sách của một bạn trong bảng có hàng trăm dòng. Quy trình an toàn nhất là gì?","options":["Xoá ngay dòng đầu tiên trông giống, vì có thể nhập lại sau","Sao lưu dữ liệu, lọc theo tên để còn đúng dòng cần xoá, kiểm tra rồi mới xoá","Đổi kiểu dữ liệu của trường tên rồi xoá cho nhanh","Xoá lần lượt vài dòng gần đó cho chắc chắn"],"answer":1,"explain":"Xoá thường không hoàn tác được nên phải sao lưu trước, lọc để khoanh đúng bản ghi, nhìn kỹ rồi mới xoá. Xoá dòng 'trông giống' dễ mất nhầm dữ liệu bạn khác. Đổi kiểu dữ liệu là thao tác cấu trúc không liên quan và có thể hỏng bảng. Xoá vài dòng gần đó chắc chắn làm mất thêm dữ liệu đúng."},{"id":"UB-tf-501","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Thêm một bản ghi nghĩa là thêm một dòng dữ liệu mới vào bảng.","correct":true},{"text":"Khi thêm bản ghi, có thể đặt khoá chính trùng với một bản ghi đã có.","correct":false},{"text":"Sửa một ô chỉ thay đổi giá trị của ô đó, các ô khác trong bản ghi giữ nguyên.","correct":true},{"text":"Muốn sửa một giá trị nhập sai thì bắt buộc phải xoá cả bản ghi rồi nhập lại.","correct":false}],"explain":"(a) Đúng — mỗi bản ghi là một dòng, thêm bản ghi là thêm dòng mới. (b) Sai — khoá chính phải khác nhau, trùng khoá sẽ bị chặn lưu. (c) Đúng — sửa chỉ tác động đến ô được chọn. (d) Sai — chỉ cần nhấp vào ô cần sửa và thay giá trị, không phải xoá cả bản ghi."},{"id":"UB-tf-502","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Biểu mẫu (form) giúp nhập liệu bằng cách hiển thị một bản ghi mỗi lần với các ô có nhãn.","correct":true},{"text":"Dữ liệu nhập qua biểu mẫu được lưu vào một bảng khác với dữ liệu nhập thẳng.","correct":false},{"text":"Lọc bản ghi giúp chỉ hiển thị những bản ghi thoả điều kiện đã chọn.","correct":true},{"text":"Sắp xếp bảng theo một trường sẽ xoá bớt các bản ghi không cần thiết.","correct":false}],"explain":"(a) Đúng — biểu mẫu là giao diện hiển thị từng bản ghi, giúp nhập gọn và ít nhầm. (b) Sai — biểu mẫu chỉ là lớp giao diện, dữ liệu vẫn ghi vào cùng một bảng. (c) Đúng — lọc chỉ hiện các bản ghi thoả điều kiện. (d) Sai — sắp xếp chỉ đổi thứ tự hiển thị, không xoá bản ghi nào."},{"id":"UB-tf-503","type":"tf","topic":"C","grade":11,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Xoá một bản ghi thường không có nút hoàn tác nên cần cẩn trọng và sao lưu trước.","correct":true},{"text":"Có thể thay việc xoá bằng cách đánh dấu bản ghi là đã xử lí để vẫn giữ lịch sử.","correct":true},{"text":"Sửa nhầm ô của bản ghi khác luôn bị phần mềm chặn lại vì đó là lỗi kiểu dữ liệu.","correct":false},{"text":"Lọc để còn đúng dòng cần xoá làm cho thao tác xoá an toàn hơn.","correct":true}],"explain":"(a) Đúng — xoá thường không hoàn tác được, sao lưu trước là nguyên tắc an toàn. (b) Đúng — đánh dấu đã xử lí thay cho xoá giúp giữ được lịch sử dữ liệu. (c) Sai — nếu giá trị mới vẫn hợp lệ về kiểu, phần mềm không cảnh báo dù bạn sửa nhầm dòng khác. (d) Đúng — lọc khoanh đúng bản ghi giúp giảm rủi ro xoá nhầm."},{"id":"UB-mc-601","type":"mc","topic":"C","grade":11,"level":"easy","question":"Ràng buộc toàn vẹn trong một CSDL có nhiều bảng có vai trò chính là gì?","options":["Đặt ra quy tắc để phần mềm tự kiểm tra, giữ dữ liệu luôn hợp lệ khi thêm, sửa, xoá","Làm cho bảng hiển thị đẹp và dễ đọc hơn","Tăng tốc độ mở tệp CSDL","Tự động dịch dữ liệu sang ngôn ngữ khác"],"answer":0,"explain":"Ràng buộc toàn vẹn là các quy tắc để hệ QTCSDL tự kiểm tra tính hợp lệ của dữ liệu. Phương án về hiển thị đẹp chỉ nói hình thức, không liên quan tính hợp lệ. Phương án tăng tốc độ nói về tốc độ, không phải mục đích của ràng buộc. Phương án dịch dữ liệu là chức năng dịch thuật, không có trong CSDL."},{"id":"UB-mc-602","type":"mc","topic":"C","grade":11,"level":"easy","question":"Theo ràng buộc toàn vẹn tham chiếu, một giá trị khoá ngoài ở bảng con phải như thế nào?","options":["Phải là một số lớn hơn 0","Phải khác với mọi khoá ngoài khác trong cùng bảng","Phải khớp với một khoá chính đang tồn tại ở bảng cha","Phải được nhập cuối cùng sau tất cả các trường khác"],"answer":2,"explain":"Toàn vẹn tham chiếu yêu cầu khoá ngoài trỏ tới một bản ghi có thật ở bảng cha, tức khớp với một khoá chính đang tồn tại. A đặt điều kiện về giá trị số không đúng bản chất. B nhầm với tính duy nhất của khoá chính; khoá ngoài hoàn toàn có thể lặp lại. D nói về thứ tự nhập, không liên quan."},{"id":"UB-mc-603","type":"mc","topic":"C","grade":11,"level":"medium","question":"Bảng DIEMDANH (con) có khoá ngoài trỏ tới bảng THANHVIEN (cha). Nếu ràng buộc tham chiếu đang bật, thao tác nào sau đây sẽ bị phần mềm từ chối?","options":["Thêm một dòng điểm danh với mã thành viên đã có trong bảng THANHVIEN","Thêm một dòng điểm danh với mã thành viên chưa hề có trong bảng THANHVIEN","Thêm một thành viên mới hoàn toàn vào bảng THANHVIEN","Sửa lại buổi sinh hoạt của một dòng điểm danh đã hợp lệ"],"answer":1,"explain":"Ràng buộc tham chiếu chặn khoá ngoài trỏ tới bản ghi không tồn tại, nên thêm dòng con với mã chưa có ở bảng cha sẽ bị từ chối. A hợp lệ vì mã đã có ở bảng cha. C chỉ thêm vào bảng cha, không vi phạm gì. D chỉ đổi trường buổi, không đụng tới khoá ngoài nên vẫn hợp lệ."},{"id":"UB-mc-604","type":"mc","topic":"C","grade":11,"level":"medium","question":"Bạn muốn xoá một thành viên ở bảng cha trong khi bảng con vẫn còn nhiều dòng trỏ tới thành viên đó. Cách xử lí nào giúp giữ lại các dòng con nhưng không để chúng trỏ tới người đã bị xoá?","options":["Xoá lan truyền: xoá luôn mọi dòng con liên quan","Hạn chế: từ chối xoá cho tới khi xử lí xong bảng con","Đặt khoá ngoài của các dòng con về giá trị rỗng","Nhân đôi bản ghi cha trước khi xoá"],"answer":2,"explain":"Đặt khoá ngoài về rỗng giữ lại dòng con nhưng gỡ liên kết, nên chúng không còn trỏ tới bản ghi đã xoá. A giữ được tính toàn vẹn nhưng xoá mất các dòng con, không phải \"giữ lại\". B lại không cho xoá bản ghi cha nên chưa đạt mục tiêu xoá. D không phải cách xử lí tham chiếu và chỉ gây trùng lặp."},{"id":"UB-mc-605","type":"mc","topic":"C","grade":11,"level":"hard","question":"Một CSDL quản lí mượn sách: bảng PHIEUMUON (con) trỏ tới bảng DOCGIA (cha) qua mã độc giả. Người quản lí bật xoá lan truyền và lỡ tay xoá nhầm một độc giả vẫn đang mượn sách. Hậu quả nghiêm trọng nhất là gì?","options":["Phần mềm báo lỗi và không cho xoá độc giả đó","Mã độc giả bị đổi thành một số ngẫu nhiên","Các độc giả khác cũng bị xoá cùng lúc","Toàn bộ phiếu mượn của độc giả đó cũng bị xoá theo, mất lịch sử mượn sách"],"answer":3,"explain":"Với xoá lan truyền, xoá bản ghi cha kéo theo mọi bản ghi con liên quan, nên các phiếu mượn của độc giả đó biến mất cùng lịch sử mượn. Phương án báo lỗi và không cho xoá là hành vi của cách \"hạn chế\", không phải xoá lan truyền. Phương án đổi mã ngẫu nhiên không xảy ra vì xoá không tự đổi giá trị khoá. Phương án xoá các độc giả khác sai vì lan truyền chỉ ảnh hưởng các dòng con trỏ tới đúng bản ghi bị xoá."},{"id":"UB-tf-601","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Ràng buộc toàn vẹn được hệ QTCSDL tự kiểm tra mỗi khi có thao tác thêm, sửa hoặc xoá dữ liệu.","correct":true},{"text":"Đã bật ràng buộc thì người dùng vẫn phải tự dò lại từng dòng để bảo đảm dữ liệu hợp lệ.","correct":false},{"text":"Ràng buộc khoá chính không cho phép hai bản ghi mang cùng một giá trị khoá chính.","correct":true},{"text":"Ràng buộc miền giá trị cho phép nhập điểm là 15 vào trường điểm giới hạn từ 0 đến 10.","correct":false}],"explain":"(a) Đúng — đó chính là vai trò của ràng buộc, kiểm tra tự động khi cập nhật. (b) Sai — phần mềm đã canh giữ nên không cần dò tay từng dòng. (c) Đúng — khoá chính phải duy nhất. (d) Sai — ràng buộc miền giá trị sẽ từ chối giá trị 15 vì vượt khoảng 0 đến 10."},{"id":"UB-tf-602","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Bản ghi mồ côi là bản ghi con có khoá ngoài trỏ tới một bản ghi cha không còn tồn tại.","correct":true},{"text":"Trong một liên kết, bảng chứa khoá ngoài được gọi là bảng cha.","correct":false},{"text":"Nhiều bản ghi con khác nhau có thể cùng trỏ tới một bản ghi cha.","correct":true},{"text":"Toàn vẹn tham chiếu cho phép nhập khoá ngoài trỏ tới bản ghi chưa có ở bảng cha.","correct":false}],"explain":"(a) Đúng — đó đúng là định nghĩa bản ghi mồ côi. (b) Sai — bảng chứa khoá ngoài là bảng con, bảng chứa khoá chính được trỏ tới là bảng cha. (c) Đúng — khoá ngoài không cần duy nhất nên nhiều dòng con có thể trỏ tới cùng một dòng cha. (d) Sai — toàn vẹn tham chiếu chặn đúng trường hợp trỏ tới bản ghi chưa tồn tại."},{"id":"UB-tf-603","type":"tf","topic":"C","grade":11,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Cách xử lí hạn chế sẽ từ chối xoá bản ghi cha chừng nào còn bản ghi con trỏ tới nó.","correct":true},{"text":"Xoá lan truyền luôn là lựa chọn an toàn nhất cho dữ liệu quan trọng như điểm hay giao dịch.","correct":false},{"text":"Nhờ ràng buộc toàn vẹn, sai sót bị chặn ngay lúc nhập thay vì tích tụ rồi mới đi dò.","correct":true},{"text":"Việc khai báo ràng buộc chỉ nên làm khi CSDL đã có rất nhiều dữ liệu rác cần dọn.","correct":false}],"explain":"(a) Đúng — hạn chế buộc xử lí bảng con trước khi cho xoá bản ghi cha. (b) Sai — xoá lan truyền dễ kéo theo mất hàng loạt dữ liệu; với dữ liệu quan trọng, cách hạn chế thường an toàn hơn. (c) Đúng — ràng buộc chặn lỗi tại thời điểm nhập nên tránh tích tụ dữ liệu rác. (d) Sai — nên khai báo ràng buộc ngay từ khi thiết kế bảng để phòng lỗi, không đợi dữ liệu hỏng rồi mới làm."},{"id":"UB-mc-701","type":"mc","topic":"C","grade":11,"level":"easy","question":"Mục đích chính của một truy vấn trong hệ QTCSDL là gì?","options":["Lấy ra đúng dữ liệu cần thiết theo yêu cầu từ một hoặc nhiều bảng","Tạo mới cấu trúc của các bảng trong cơ sở dữ liệu","Sao lưu toàn bộ cơ sở dữ liệu ra tệp dự phòng","Đặt mật khẩu bảo vệ cho từng bảng dữ liệu"],"answer":0,"explain":"Truy vấn dùng để rút trích dữ liệu theo yêu cầu. Tạo cấu trúc bảng là việc thiết kế bảng; sao lưu là chức năng backup; đặt mật khẩu là phần bảo mật — cả ba đều không phải mục đích của truy vấn."},{"id":"UB-mc-702","type":"mc","topic":"C","grade":11,"level":"easy","question":"Để nối bảng `HOC_SINH` với bảng `LOP` nhằm hiển thị tên lớp cho mỗi học sinh, phần mềm dựa vào điều gì?","options":["Số thứ tự dòng trong mỗi bảng","Cặp trường chung: khoá ngoài `ma_lop` ở HOC_SINH khớp khoá chính `ma_lop` ở LOP","Màu sắc tô cho các ô dữ liệu","Việc hai bảng có cùng số lượng bản ghi"],"answer":1,"explain":"Liên kết dựa trên cặp khoá chung có giá trị khớp nhau. Số thứ tự dòng, màu ô hay số lượng bản ghi không liên quan đến cách ghép đúng học sinh với lớp của em."},{"id":"UB-mc-703","type":"mc","topic":"C","grade":11,"level":"medium","question":"Trong cửa sổ thiết kế truy vấn trực quan, thao tác nào tạo ra đường liên kết giữa hai bảng?","options":["Bấm nút chạy truy vấn","Nhập điều kiện vào ô tiêu chí","Kéo trường khoá ngoài của bảng này thả lên trường khoá chính của bảng kia","Bỏ tích cột không muốn hiển thị"],"answer":2,"explain":"Đường nối được tạo bằng cách kéo thả một trường lên trường tương ứng ở bảng kia. Bấm chạy chỉ thực thi; nhập ô tiêu chí là lọc; bỏ tích cột là chọn trường hiển thị — không cái nào tạo liên kết."},{"id":"UB-mc-704","type":"mc","topic":"C","grade":11,"level":"medium","question":"Cô giáo cần danh sách chỉ gồm học sinh sinh năm 2008, sắp theo họ tên. Trong thiết kế truy vấn cần làm gì?","options":["Đặt điều kiện năm sinh 2008 ở ô tiêu chí và chọn sắp xếp tăng dần cho trường họ tên","Xoá bớt các bản ghi không phải năm 2008 khỏi bảng gốc","Đổi kiểu dữ liệu của trường ngày sinh","Thêm một bảng mới chứa riêng học sinh năm 2008"],"answer":0,"explain":"Truy vấn cho phép lọc bằng ô tiêu chí và đặt sắp xếp mà không đụng dữ liệu gốc. Xoá bản ghi gốc là làm mất dữ liệu; đổi kiểu dữ liệu hay tạo bảng mới đều không cần thiết và sai mục đích."},{"id":"UB-mc-705","type":"mc","topic":"C","grade":11,"level":"hard","question":"Một bạn thêm hai bảng vào truy vấn nhưng quên kéo tạo đường nối, rồi bấm chạy. Kết quả có gì bất thường?","options":["Truy vấn báo lỗi và không chạy được","Kết quả chỉ hiện đúng một bảng, bảng kia bị bỏ qua","Mỗi dòng của bảng này bị ghép với mọi dòng của bảng kia, số dòng phình to và sai lệch","Dữ liệu gốc trong hai bảng bị trộn lẫn vĩnh viễn"],"answer":2,"explain":"Thiếu điều kiện nối, phần mềm ghép chéo mọi dòng với mọi dòng nên kết quả phình to, không có ý nghĩa quản lí. Truy vấn vẫn chạy chứ không báo lỗi; và vì truy vấn chỉ đọc nên dữ liệu gốc không hề bị trộn hay hỏng."},{"id":"UB-tf-701","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Truy vấn chỉ nhìn vào dữ liệu gốc, khi bảng gốc thay đổi thì chạy lại sẽ cho kết quả cập nhật.","correct":true},{"text":"Chạy một truy vấn sẽ tạo ra bản sao dữ liệu độc lập, không còn liên quan đến bảng gốc.","correct":false},{"text":"Có thể lưu truy vấn lại để dùng đi dùng lại nhiều lần.","correct":true},{"text":"Muốn xem kết quả mới thì bắt buộc phải nhập lại toàn bộ thiết kế truy vấn từ đầu.","correct":false}],"explain":"(a) Đúng — truy vấn phản ánh dữ liệu gốc theo thời gian thực khi chạy lại. (b) Sai — nó không sao chép mà chỉ là ống kính nhìn vào dữ liệu gốc. (c) Đúng — truy vấn lưu được và tái sử dụng. (d) Sai — chỉ cần mở truy vấn đã lưu và chạy lại, không phải thiết kế lại."},{"id":"UB-tf-702","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Việc chọn trường hiển thị giúp kết quả chỉ hiện đúng cột cần thiết, ẩn cột không liên quan.","correct":true},{"text":"Điều kiện lọc ở ô tiêu chí quyết định những dòng nào được lấy vào kết quả.","correct":true},{"text":"Muốn danh sách xếp theo tên lớp thì phải sửa lại thứ tự các bản ghi trong bảng gốc.","correct":false},{"text":"Không thể vừa lọc điều kiện vừa sắp xếp trong cùng một truy vấn.","correct":false}],"explain":"(a) Đúng — chọn trường làm kết quả gọn và đúng trọng tâm. (b) Đúng — ô tiêu chí là nơi đặt điều kiện lọc dòng. (c) Sai — sắp xếp là thao tác của truy vấn, không cần và không nên sửa thứ tự bảng gốc. (d) Sai — nối bảng, lọc và sắp xếp có thể làm đồng thời trong một truy vấn."},{"id":"UB-tf-703","type":"tf","topic":"C","grade":11,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Nếu quên tạo đường nối giữa hai bảng, kết quả có thể phình to và sai lệch do ghép chéo mọi dòng.","correct":true},{"text":"Đường nối nên tạo giữa khoá ngoài của bảng này và khoá chính tương ứng của bảng kia.","correct":true},{"text":"Đặt điều kiện lọc nhầm sang một cột khác vẫn luôn cho ra đúng kết quả mong muốn.","correct":false},{"text":"Nối hai bảng nhất thiết đòi hỏi hai bảng phải có cùng số lượng bản ghi.","correct":false}],"explain":"(a) Đúng — thiếu điều kiện nối gây ghép chéo toàn bộ. (b) Đúng — đó chính là cặp khoá chung để ghép đúng dòng. (c) Sai — đặt điều kiện nhầm cột sẽ cho kết quả sai lệch. (d) Sai — việc nối dựa trên giá trị khoá khớp nhau, không liên quan đến số lượng bản ghi hai bảng bằng nhau hay không."},{"id":"UB-mc-801","type":"mc","topic":"C","grade":11,"level":"easy","question":"Sao lưu (backup) một cơ sở dữ liệu nghĩa là gì?","options":["Xoá bớt các bản ghi cũ để tệp nhẹ hơn","Tạo thêm bản sao của tệp và cất ở nơi an toàn để dùng lại khi có sự cố","Sắp xếp lại các bảng cho gọn gàng","Đổi mật khẩu mở tệp cơ sở dữ liệu"],"answer":1,"explain":"Sao lưu là tạo thêm bản sao của tệp CSDL, giữ ở nơi an toàn để phục hồi khi bản chính hỏng hoặc mất. Xoá bản ghi, sắp xếp bảng hay đổi mật khẩu là những việc khác, không tạo ra bản dự phòng nào."},{"id":"UB-mc-802","type":"mc","topic":"C","grade":11,"level":"easy","question":"Vì sao nên đặt tên bản sao lưu kèm theo ngày, ví dụ `thuvien_2026-07-24.db`?","options":["Để tệp chạy nhanh hơn","Để phần mềm tự động mở tệp đó","Để dễ biết bản nào mới, bản nào cũ và chọn đúng bản khi cần phục hồi","Để bản sao không bao giờ bị hỏng"],"answer":2,"explain":"Tên kèm ngày cho biết bản sao chụp lại dữ liệu ở thời điểm nào, giúp chọn đúng bản khi phục hồi. Đặt tên không làm tệp chạy nhanh hơn, không khiến phần mềm tự mở, và cũng không bảo vệ bản sao khỏi hỏng."},{"id":"UB-mc-803","type":"mc","topic":"C","grade":11,"level":"medium","question":"Trước khi chép tệp cơ sở dữ liệu ra để sao lưu, vì sao nên đóng tệp trong phần mềm lại?","options":["Vì khi đang mở, một phần dữ liệu còn trong bộ nhớ chưa ghi hết xuống ổ, chép lúc đó dễ được bản dở dang","Vì phần mềm không cho phép chép tệp bao giờ","Vì đóng tệp sẽ tự động tạo bản sao lưu giúp em","Vì tệp đang mở luôn có dung lượng lớn gấp đôi"],"answer":0,"explain":"Khi tệp đang mở, dữ liệu có thể còn nằm trong bộ nhớ chưa ghi hết xuống đĩa, nên bản chép ra dễ bị dở dang, hỏng. Phần mềm không cấm chép, việc đóng tệp không tự tạo bản sao lưu, và dung lượng tệp không tự nhân đôi khi mở."},{"id":"UB-mc-804","type":"mc","topic":"C","grade":11,"level":"medium","question":"Nhóm sao lưu lần gần nhất vào thứ Hai, rồi nhập thêm dữ liệu suốt tuần. Đến thứ Sáu tệp gốc hỏng và phải phục hồi từ bản thứ Hai. Điều gì xảy ra với dữ liệu?","options":["Lấy lại được toàn bộ, kể cả phần nhập từ thứ Ba đến thứ Sáu","Chỉ lấy lại được dữ liệu tới thứ Hai, phần nhập sau đó bị mất","Mất toàn bộ dữ liệu vì đã có sự cố","Phần mềm tự động ghép bản thứ Hai với dữ liệu mới nhất"],"answer":1,"explain":"Phục hồi chỉ đưa dữ liệu về đúng thời điểm của bản sao lưu, nên phần nhập từ thứ Ba đến thứ Sáu không có trong bản thứ Hai và bị mất. Không lấy lại được phần mới, cũng không mất sạch, và phần mềm không tự ghép dữ liệu chưa từng được sao lưu. Đây là lí do phải sao lưu thường xuyên."},{"id":"UB-mc-805","type":"mc","topic":"C","grade":11,"level":"hard","question":"Cách làm nào sau đây bám sát tinh thần nguyên tắc 3-2-1 nhất?","options":["Giữ ba bản sao lưu, cả ba đều nằm trong cùng một ổ cứng máy tính","Chỉ giữ đúng tệp đang dùng, không tạo bản sao nào","Giữ bản đang dùng trên máy, một bản trên USB và một bản trên thư mục lưu trữ mạng đặt ở nơi khác","Chép bản sao lưu đè thẳng lên tệp gốc mỗi ngày"],"answer":2,"explain":"3-2-1 nghĩa là 3 bản dữ liệu, 2 loại phương tiện, 1 bản để ở nơi khác — đúng như phương án có máy, USB và lưu trữ mạng. Ba bản trong cùng một ổ vi phạm ý '2 phương tiện' và '1 nơi khác'; không sao lưu là không có dự phòng; còn chép đè lên tệp gốc thì không tạo ra bản dự phòng nào cả."},{"id":"UB-tf-801","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Sao lưu cần được thực hiện định kỳ, đều đặn chứ không đợi đến khi mất dữ liệu mới làm.","correct":true},{"text":"Khi tệp gốc đã hỏng, luôn có nút hoàn tác để lấy lại dữ liệu mà không cần bản sao lưu.","correct":false},{"text":"Bản sao lưu nên được cất ở nơi an toàn, tách khỏi bản chính.","correct":true},{"text":"Chỉ cần sao lưu một lần duy nhất là đủ dùng cho mãi về sau.","correct":false}],"explain":"(a) Đúng — sự cố đến bất ngờ nên phải sao lưu đều đặn từ trước. (b) Sai — khi tệp gốc hỏng thường không thể hoàn tác, chỉ bản sao lưu mới cứu được. (c) Đúng — cất tách khỏi bản chính để một sự cố không cuốn đi cả hai. (d) Sai — dữ liệu thay đổi liên tục nên phải sao lưu nhiều lần."},{"id":"UB-tf-802","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Phục hồi dữ liệu là dùng một bản sao lưu để thay cho tệp gốc đã hỏng hoặc mất.","correct":true},{"text":"Phục hồi lấy lại được cả phần dữ liệu nhập thêm sau thời điểm tạo bản sao lưu.","correct":false},{"text":"Đặt tên bản sao kèm ngày giúp chọn đúng bản gần nhất còn tốt khi phục hồi.","correct":true},{"text":"Nên chép bản sao lưu đè thẳng lên tệp gốc ngay mà không kiểm tra bản sao trước.","correct":false}],"explain":"(a) Đúng — đó chính là ý nghĩa của phục hồi. (b) Sai — phục hồi chỉ đưa về đúng thời điểm của bản sao, phần nhập sau đó không có trong bản sao. (c) Đúng — tên kèm ngày giúp nhận ra bản mới nhất. (d) Sai — nếu bản sao lỗi mà đã đè lên gốc thì mất luôn cả hai, nên phải kiểm tra trước."},{"id":"UB-tf-803","type":"tf","topic":"C","grade":11,"level":"hard","question":"Cho biết mỗi phát biểu sau về nguyên tắc 3-2-1 đúng hay sai:","statements":[{"text":"Số 2 trong 3-2-1 nhắc em nên đặt các bản trên hai loại phương tiện khác nhau, ví dụ ổ máy tính và USB.","correct":true},{"text":"Số 1 trong 3-2-1 nghĩa là nên có một bản đặt ở nơi khác so với máy tính đang dùng.","correct":true},{"text":"Giữ cả ba bản trong cùng một chiếc USB vẫn thoả mãn đầy đủ nguyên tắc 3-2-1.","correct":false},{"text":"Khoảng cách giữa hai lần sao lưu càng ngắn thì phần dữ liệu có nguy cơ mất càng ít.","correct":true}],"explain":"(a) Đúng — số 2 chỉ hai loại phương tiện khác nhau. (b) Đúng — số 1 là một bản để ở nơi khác, phòng khi cả chỗ chính gặp sự cố. (c) Sai — ba bản cùng một USB chỉ có một phương tiện, một nơi, nếu USB hỏng là mất hết, vi phạm cả '2' lẫn '1'. (d) Đúng — sao lưu càng dày thì phần dữ liệu chưa kịp sao lưu càng ít."},{"id":"UB-mc-901","type":"mc","topic":"E","grade":11,"level":"easy","question":"Trong một tấm ảnh số, đơn vị nhỏ nhất mang một màu và tạo nên toàn bộ hình được gọi là gì?","options":["Điểm ảnh (pixel)","Lớp (layer)","Vùng chọn (selection)","Hộp công cụ"],"answer":0,"explain":"Ảnh số là lưới các điểm ảnh, mỗi điểm mang một màu nên đáp án đúng là điểm ảnh. Lớp là tầng nội dung xếp chồng, không phải đơn vị nhỏ nhất. Vùng chọn là phần ảnh được khoanh để giới hạn thao tác. Hộp công cụ là khu vực chứa các công cụ trên giao diện, không phải thành phần của ảnh."},{"id":"UB-mc-902","type":"mc","topic":"E","grade":11,"level":"easy","question":"Vì sao nên đặt dòng chữ và ảnh gốc trên hai lớp khác nhau thay vì gõ chữ trực tiếp lên ảnh?","options":["Để ảnh có độ phân giải cao hơn","Để có thể sửa hoặc xoá dòng chữ mà không làm hỏng ảnh gốc","Để tệp ảnh nhẹ hơn khi lưu","Để phần mềm chạy nhanh hơn"],"answer":1,"explain":"Đặt mỗi nội dung trên một lớp riêng cho phép chỉnh sửa không phá huỷ: sửa hay xoá lớp chữ mà ảnh gốc ở lớp khác vẫn nguyên. Số lớp không làm thay đổi độ phân giải của ảnh. Thêm lớp thường khiến tệp nặng hơn chứ không nhẹ hơn. Việc tách lớp là để dễ chỉnh sửa, không nhằm tăng tốc phần mềm."},{"id":"UB-mc-903","type":"mc","topic":"E","grade":11,"level":"medium","question":"Đang mở một ảnh có nhiều lớp, em muốn làm sáng riêng khuôn mặt các bạn mà không ảnh hưởng tới bầu trời. Cách làm đúng là gì?","options":["Tăng độ phân giải của cả ảnh","Ẩn tất cả các lớp rồi chỉnh độ sáng","Tạo vùng chọn quanh khuôn mặt rồi mới chỉnh độ sáng","Đổi tên lớp ảnh gốc cho dễ nhớ"],"answer":2,"explain":"Vùng chọn giới hạn thao tác vào phần được khoanh, nên khoanh vùng quanh khuôn mặt rồi chỉnh sáng sẽ không đụng tới bầu trời. Tăng độ phân giải không liên quan tới việc khống chế phạm vi chỉnh sáng. Ẩn hết các lớp thì chẳng còn gì để chỉnh. Đổi tên lớp chỉ giúp quản lí, không giới hạn được vùng tác động của thao tác."},{"id":"UB-mc-904","type":"mc","topic":"E","grade":11,"level":"medium","question":"Khu vực nào trên giao diện phần mềm chỉnh sửa ảnh cho phép em ẩn/hiện, đổi tên và sắp xếp lại thứ tự trên dưới của các tầng nội dung?","options":["Bảng màu","Bảng lớp","Thanh tuỳ chọn công cụ","Vùng làm việc"],"answer":1,"explain":"Bảng lớp liệt kê các lớp theo thứ tự trên dưới và cho phép ẩn/hiện, đổi tên, sắp xếp lại. Bảng màu chỉ dùng để chọn màu vẽ và màu nền. Thanh tuỳ chọn hiển thị thiết lập của công cụ đang dùng như cỡ cọ. Vùng làm việc là khung hiển thị ảnh, không phải nơi quản lí danh sách lớp."},{"id":"UB-mc-905","type":"mc","topic":"E","grade":11,"level":"hard","question":"Một tấm áp phích có ba lớp xếp từ trên xuống: 'chu-chuc-mung', 'bong-hoa', 'anh-ca-lop'. Nếu em kéo lớp 'bong-hoa' lên trên cùng, điều gì xảy ra khi nhìn ảnh?","options":["Bông hoa có thể che một phần dòng chữ vì nó nằm trên chữ","Dòng chữ biến mất hoàn toàn khỏi ảnh","Ảnh cả lớp bị xoá khỏi tệp","Ba lớp tự động nhập thành một lớp duy nhất"],"answer":0,"explain":"Lớp ở trên hiển thị đè lên lớp ở dưới, nên đưa 'bong-hoa' lên trên cùng thì bông hoa sẽ che phần nào đó của dòng chữ nằm bên dưới nó. Dòng chữ không biến mất, chỉ có thể bị che một phần. Đổi thứ tự lớp không xoá lớp ảnh gốc. Việc kéo lớp chỉ đổi vị trí trong danh sách, không tự động gộp các lớp lại."},{"id":"UB-tf-901","type":"tf","topic":"E","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Ảnh số là một lưới gồm nhiều điểm ảnh, mỗi điểm ảnh mang một màu.","correct":true},{"text":"Phóng to một tấm ảnh nhỏ quá mức có thể làm hình bị 'vỡ' thành các ô vuông màu.","correct":true},{"text":"Ảnh có càng ít điểm ảnh thì càng rõ nét và in được khổ càng lớn.","correct":false},{"text":"Độ phân giải của ảnh được tính bằng số điểm ảnh theo chiều ngang nhân chiều dọc.","correct":true}],"explain":"(a) Đúng — ảnh số chính là lưới các điểm ảnh, mỗi điểm một màu. (b) Đúng — phóng quá mức làm lộ từng ô điểm ảnh nên hình bị vỡ. (c) Sai — ngược lại, càng nhiều điểm ảnh mới càng rõ nét và in được khổ lớn. (d) Đúng — độ phân giải là số điểm ảnh ngang nhân dọc, ví dụ 1920 x 1080."},{"id":"UB-tf-902","type":"tf","topic":"E","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Trên một lớp, chỗ nào không có nội dung thì trong suốt, để lộ lớp bên dưới.","correct":true},{"text":"Chỉnh sửa không phá huỷ nghĩa là mọi thay đổi làm hỏng vĩnh viễn ảnh gốc.","correct":false},{"text":"Có thể tạm ẩn một lớp để so sánh ảnh trước và sau khi chỉnh.","correct":true},{"text":"Giảm độ mờ của một lớp sẽ tự động xoá lớp đó khỏi ảnh.","correct":false}],"explain":"(a) Đúng — phần trống của lớp là trong suốt nên nhìn thấy lớp dưới. (b) Sai — không phá huỷ nghĩa là ảnh gốc được giữ nguyên, thay đổi nằm ở các lớp khác. (c) Đúng — ẩn/hiện lớp là cách so sánh trước và sau rất tiện. (d) Sai — giảm độ mờ chỉ làm lớp nhạt đi, lớp vẫn còn chứ không bị xoá."},{"id":"UB-tf-903","type":"tf","topic":"E","grade":11,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Khi một vùng chọn đang bật, thao tác tô màu chỉ ảnh hưởng bên trong vùng đó.","correct":true},{"text":"Ranh giới vùng chọn thường hiện bằng đường nét đứt nhấp nháy quanh phần được chọn.","correct":true},{"text":"Nếu quên bỏ vùng chọn, thao tác tiếp theo vẫn tự do tác động lên toàn bộ lớp.","correct":false},{"text":"Vùng chọn dùng để đổi thứ tự trên dưới của các lớp trong bảng lớp.","correct":false}],"explain":"(a) Đúng — vùng chọn giới hạn thao tác vào bên trong ranh giới của nó. (b) Đúng — ranh giới hiện bằng nét đứt nhấp nháy, hay gọi vui là 'đàn kiến bò'. (c) Sai — nếu quên bỏ chọn, thao tác sau vẫn chỉ tác động trong vùng cũ chứ không tự do trên cả lớp. (d) Sai — đổi thứ tự lớp là việc của bảng lớp, không phải chức năng của vùng chọn."},{"id":"UB-mc-1001","type":"mc","topic":"E","grade":11,"level":"easy","question":"Tấm ảnh chụp trong hội trường bị tối đều cả khung hình. Thao tác chỉnh phù hợp đầu tiên là gì?","options":["Tăng độ sáng","Giảm độ bão hoà về 0","Giảm độ tương phản","Xoay ảnh"],"answer":0,"explain":"Ảnh tối đều nghĩa là thiếu ánh sáng chung, nên tăng độ sáng làm mọi điểm ảnh sáng lên. Giảm bão hoà về 0 chỉ biến ảnh thành đen trắng, không giải quyết độ tối. Giảm tương phản khiến ảnh càng xám đục. Xoay ảnh không liên quan gì đến độ sáng."},{"id":"UB-mc-1002","type":"mc","topic":"E","grade":11,"level":"easy","question":"Trên biểu đồ histogram, trục ngang biểu diễn điều gì?","options":["Kích thước tính bằng pixel của ảnh","Mức sáng, từ tối nhất bên trái đến sáng nhất bên phải","Số lớp ảnh đang có trong tệp","Thời gian chụp của bức ảnh"],"answer":1,"explain":"Trục ngang của histogram chạy từ tối nhất (trái) đến sáng nhất (phải), còn chiều cao cột cho biết số điểm ảnh ở mức sáng đó. Nó không biểu diễn kích thước pixel, số lớp ảnh hay thời gian chụp — đó là các thông tin khác của tệp ảnh."},{"id":"UB-mc-1003","type":"mc","topic":"E","grade":11,"level":"medium","question":"Ảnh chân dung chụp dưới đèn vàng trong nhà bị ám vàng, khuôn mặt trông không thật. Nên xử lí thế nào?","options":["Tăng độ bão hoà để màu vàng rực hơn","Dùng cân bằng màu, thêm chút tông xanh lam để trung hoà ám vàng","Giảm độ sáng cho ảnh tối lại","Tăng tương phản lên mức tối đa"],"answer":1,"explain":"Ám vàng được khử bằng cách thêm tông lạnh (xanh lam) qua công cụ cân bằng màu, đưa tông về tự nhiên. Tăng bão hoà chỉ làm màu vàng đậm thêm, càng ám. Giảm sáng không khử màu. Tăng tương phản tối đa dễ làm ảnh bệt và vẫn còn ám vàng."},{"id":"UB-mc-1004","type":"mc","topic":"E","grade":11,"level":"medium","question":"Một tấm ảnh không tối nhưng nhìn xám đục, các vật thể thiếu chiều sâu, trên histogram các cột chụm hẹp ở giữa. Ảnh đang thiếu gì?","options":["Thiếu độ sáng","Thiếu độ bão hoà","Thiếu độ tương phản","Thừa sáng"],"answer":2,"explain":"Cột histogram chụm hẹp ở giữa nghĩa là khoảng cách sáng - tối quá nhỏ, tức thiếu tương phản, khiến ảnh xám đục và thiếu khối. Ảnh không tối nên không phải thiếu sáng hay thừa sáng. Thiếu bão hoà chỉ làm màu nhạt, không giải thích được việc ảnh thiếu chiều sâu về sáng - tối."},{"id":"UB-mc-1005","type":"mc","topic":"E","grade":11,"level":"hard","question":"Khi kéo tăng độ sáng của ảnh sân trường chụp nắng gắt, em thấy cột histogram bắt đầu dồn lại và dựng thành vạch cao sát mép phải. Kết luận đúng nhất là gì?","options":["Ảnh đã cân bằng màu hoàn hảo, nên dừng chỉnh màu","Vùng sáng đang bị cháy sáng và mất chi tiết, cần lùi thanh trượt lại","Ảnh đang thiếu sáng nghiêm trọng, cần tăng thêm nữa","Độ bão hoà đang quá thấp, cần tăng bão hoà"],"answer":1,"explain":"Cột dồn dựng đứng sát mép phải là dấu hiệu nhiều điểm ảnh đã bị đẩy tới mức trắng tối đa, tức cháy sáng và mất chi tiết không lấy lại được, nên phải lùi độ sáng lại. Vạch sát mép phải không nói gì về cân bằng màu hay bão hoà, và chắc chắn không phải ảnh thiếu sáng — đó là thừa sáng."},{"id":"UB-tf-1001","type":"tf","topic":"E","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Tăng độ tương phản làm vùng sáng sáng hơn và vùng tối tối hơn.","correct":true},{"text":"Giảm độ bão hoà về 0 sẽ biến ảnh thành đen trắng.","correct":true},{"text":"Độ sáng chỉ tác động lên một vùng nhỏ do em chọn trước.","correct":false},{"text":"Tăng độ bão hoà quá mức có thể làm màu da trông đỏ cam giả tạo.","correct":true}],"explain":"(a) Đúng — đó chính là bản chất của tương phản: nới rộng chênh lệch sáng - tối. (b) Đúng — bão hoà bằng 0 nghĩa là không còn màu, ảnh thành đen trắng. (c) Sai — độ sáng tác động lên toàn bộ ảnh, không phải một vùng chọn riêng. (d) Đúng — đẩy bão hoà quá tay làm màu da rực lên thiếu tự nhiên."},{"id":"UB-tf-1002","type":"tf","topic":"E","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Trên histogram, cột dồn hết về bên trái cho thấy ảnh đang thiếu sáng.","correct":true},{"text":"Cột histogram dồn hết về bên phải là dấu hiệu ảnh bị thừa sáng.","correct":true},{"text":"Histogram cho biết ảnh được chụp bằng loại máy nào.","correct":false},{"text":"Chiều cao mỗi cột cho biết số điểm ảnh có ở mức sáng tương ứng.","correct":true}],"explain":"(a) Đúng — dồn trái nghĩa là phần lớn điểm ảnh ở mức tối. (b) Đúng — dồn phải nghĩa là phần lớn điểm ảnh ở mức sáng, tức thừa sáng. (c) Sai — histogram chỉ mô tả phân bố sáng - tối, không cho biết loại máy chụp. (d) Đúng — chiều cao cột chính là số điểm ảnh ở mức sáng đó."},{"id":"UB-tf-1003","type":"tf","topic":"E","grade":11,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Vùng đã bị cháy sáng trắng xoá vẫn có thể kéo giảm sáng để lấy lại đầy đủ chi tiết ban đầu.","correct":false},{"text":"Nên chỉnh trên bản sao và giữ lại ảnh gốc để còn đường quay lại khi hỏng.","correct":true},{"text":"Ảnh tối đều thì tăng độ sáng, còn ảnh xám đục thiếu khối thì tăng độ tương phản.","correct":true},{"text":"Kéo mọi thanh trượt lên mức tối đa luôn cho ra tấm ảnh đẹp nhất.","correct":false}],"explain":"(a) Sai — chi tiết đã cháy sáng thành trắng thì mất hẳn, giảm sáng chỉ cho ra vùng xám chứ không phục hồi chi tiết. (b) Đúng — làm trên bản sao và giữ ảnh gốc là thói quen an toàn. (c) Đúng — đây là cách phân biệt đúng loại lỗi để chọn đúng công cụ. (d) Sai — kéo tối đa thường gây cháy sáng, bệt và màu giả tạo; chỉnh phải vừa đủ."},{"id":"UB-mc-1101","type":"mc","topic":"E","grade":11,"level":"easy","question":"Trong phần mềm chỉnh sửa ảnh, \"vùng chọn\" dùng để làm gì?","options":["Khoanh một phần ảnh để mọi thao tác chỉ tác động lên đúng phần đó","Tăng độ sáng cho toàn bộ ảnh","Lưu ảnh sang định dạng khác","Đổi kích thước của cả tấm ảnh"],"answer":0,"explain":"Vùng chọn khoanh lại phần ảnh cần xử lí, nhờ đó sao chép, di chuyển hay xoá chỉ ảnh hưởng đến phần bên trong, chừa phần ngoài. Tăng sáng toàn ảnh, đổi định dạng khi lưu hay đổi kích thước ảnh là các chức năng khác, không phải mục đích của vùng chọn."},{"id":"UB-mc-1102","type":"mc","topic":"E","grade":11,"level":"easy","question":"Cần lấy riêng một bạn ra khỏi tấm ảnh chân dung chụp trước phông nền xanh trơn một màu. Công cụ nào nhanh và hợp lí nhất?","options":["Chọn hình chữ nhật quanh cả người","Chọn theo màu, bấm vào nền rồi đảo vùng chọn","Chọn hình ellip bao lấy khuôn mặt","Tăng độ tương phản của ảnh"],"answer":1,"explain":"Nền một màu đồng nhất là điều kiện lí tưởng cho công cụ chọn theo màu: bấm vào nền là chọn được cả nền, rồi đảo vùng chọn để lấy đúng chủ thể. Khung chữ nhật hay ellip không bám theo hình người nên sẽ dính nền hoặc cắt cụt. Tăng tương phản không tạo ra vùng chọn để tách."},{"id":"UB-mc-1103","type":"mc","topic":"E","grade":11,"level":"medium","question":"Công cụ chọn theo màu có thông số \"dung sai\". Tăng dung sai lên cao sẽ có tác dụng gì?","options":["Chỉ chọn đúng một điểm ảnh được bấm","Gộp thêm cả những điểm ảnh có màu chênh lệch nhiều hơn vào vùng chọn","Làm mềm mép vùng chọn đã có","Xoá vùng chọn hiện tại đi"],"answer":1,"explain":"Dung sai quyết định mức chênh màu được coi là \"gần giống\": dung sai lớn thì phần mềm gộp cả những sắc màu chênh nhiều hơn, vùng chọn rộng ra. Dung sai nhỏ mới chọn màu sát nhau. Làm mềm mép và xoá vùng chọn là các thao tác khác, không do dung sai điều khiển."},{"id":"UB-mc-1104","type":"mc","topic":"E","grade":11,"level":"medium","question":"Vì sao ảnh thẻ luôn được yêu cầu chụp trên phông nền trơn một màu?","options":["Để ảnh có dung lượng tệp nhỏ hơn","Để nền một màu giúp việc chọn theo màu và tách nền sau này dễ và sạch","Để tự động tăng độ bão hoà cho khuôn mặt","Vì phông một màu bắt buộc phải có thì mới chụp được ảnh"],"answer":1,"explain":"Phông trơn một màu là điều kiện lí tưởng để công cụ chọn theo màu khoanh gọn cả nền, nhờ đó tách chủ thể ra sạch sẽ khi cần đổi nền. Dung lượng tệp không phải lí do chính, phông nền không tự tăng bão hoà da, và ảnh vẫn chụp được trên nền bất kì — chỉ là khó tách hơn."},{"id":"UB-mc-1105","type":"mc","topic":"E","grade":11,"level":"hard","question":"Sau khi tách một bạn khỏi nền cũ và dán sang phông bầu trời, Nam thấy viền quanh người cứng như cắt bằng kéo và trông rõ là ảnh ghép. Cách xử lí đúng nhất là gì?","options":["Làm mềm mép vùng chọn ở mức vừa phải để tạo dải chuyển tiếp","Tăng dung sai của công cụ chọn theo màu lên tối đa","Đẩy mức làm mềm mép lên thật cao cho chắc","Tăng độ sáng của phông bầu trời mới"],"answer":0,"explain":"Viền cứng lộ ghép được khắc phục bằng cách làm mềm mép ở mức vừa phải, tạo dải chuyển tiếp giúp chủ thể hoà vào nền. Tăng dung sai chỉ đổi phạm vi chọn màu, không sửa mép đã cắt. Làm mềm quá cao sẽ mờ nhoè cả viền, nhất là tóc. Tăng sáng phông không liên quan đến độ cứng của mép ghép."},{"id":"UB-tf-1101","type":"tf","topic":"E","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Công cụ chọn hình chữ nhật phù hợp để cắt ảnh thành khung vuông vắn.","correct":true},{"text":"Chọn theo màu hoạt động tốt nhất khi nền là một màu đồng nhất.","correct":true},{"text":"Công cụ chọn hình ellip có thể bám sát mọi đường viền phức tạp của thân người.","correct":false},{"text":"Đã tạo vùng chọn thì không thể cộng thêm hay bớt đi phần nào nữa.","correct":false}],"explain":"(a) Đúng — khung chữ nhật cho vùng chọn cạnh thẳng, hợp với hình vuông vắn. (b) Đúng — nền một màu giúp công cụ chọn theo màu khoanh gọn cả nền. (c) Sai — ellip chỉ tạo vùng bầu dục trơn, không bám được viền phức tạp; việc đó cần công cụ chọn tự do. (d) Sai — mọi công cụ đều cho phép cộng thêm hoặc bớt đi khỏi vùng chọn để sửa cho khớp."},{"id":"UB-tf-1102","type":"tf","topic":"E","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Làm mềm mép giúp ảnh ghép trông tự nhiên hơn, tránh viền cứng lộ ghép.","correct":true},{"text":"Làm mềm mép ở mức quá cao có thể khiến viền tóc bị mờ nhoè.","correct":true},{"text":"Cách đúng để tách chủ thể là xoá trực tiếp từng phần nền quanh người.","correct":false},{"text":"Có thể phối hợp nhiều công cụ chọn khác nhau trên cùng một ảnh.","correct":true}],"explain":"(a) Đúng — làm mềm mép tạo dải chuyển tiếp giúp chủ thể hoà vào nền. (b) Đúng — làm mềm quá tay khiến viền, nhất là tóc, bị mờ. (c) Sai — nên khoanh vùng chọn rồi tách, xoá trực tiếp vừa chậm vừa dễ ăn lẹm và không lấy lại được. (d) Đúng — phối hợp chọn theo màu với chọn tự do để dặm lại là cách làm khôn ngoan."},{"id":"UB-tf-1103","type":"tf","topic":"E","grade":11,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Với chủ thể trên nền lộn xộn nhiều màu, chọn tự do bám viền thường phù hợp hơn chọn theo màu.","correct":true},{"text":"Dung sai càng nhỏ thì công cụ chọn theo màu chỉ lấy những màu càng sát nhau.","correct":true},{"text":"Sau khi chọn cả nền bằng công cụ chọn theo màu, đảo vùng chọn sẽ cho ta đúng chủ thể.","correct":true},{"text":"Vùng chọn có mép sắc lẹm luôn cho ảnh ghép đẹp hơn vùng chọn được làm mềm mép.","correct":false}],"explain":"(a) Đúng — nền nhiều màu khiến chọn theo màu khó gom gọn, nên chọn tự do bám viền hợp hơn. (b) Đúng — dung sai nhỏ chỉ gộp các màu thật gần nhau. (c) Đúng — chọn nền rồi đảo vùng chọn là mẹo lấy chủ thể trên nền một màu. (d) Sai — mép sắc lẹm thường lộ rõ ghép; làm mềm mép vừa phải mới cho ghép tự nhiên hơn."},{"id":"UB-mc-1201","type":"mc","topic":"E","grade":11,"level":"easy","question":"Công cụ nào giúp em lấy lại đúng một màu đã có sẵn trên ảnh để dùng làm màu vẽ?","options":["Công cụ hút màu (ống hút)","Công cụ tô màu (thùng sơn)","Công cụ gôm tẩy","Công cụ văn bản"],"answer":0,"explain":"Công cụ hút màu cho phép nhấp vào một điểm trên ảnh và lấy chính màu đó làm màu vẽ. Thùng sơn dùng để đổ màu kín một vùng, gôm tẩy để xoá, còn công cụ văn bản để gõ chữ — không cái nào lấy màu từ ảnh."},{"id":"UB-mc-1202","type":"mc","topic":"E","grade":11,"level":"easy","question":"Khi em dùng công cụ văn bản để gõ một dòng chữ lên ảnh, điều gì thường xảy ra?","options":["Chữ được ghi trực tiếp vào ảnh gốc và không sửa được nữa","Phần mềm tạo ra một lớp chữ riêng, tách khỏi ảnh","Ảnh gốc bị xoá và thay bằng dòng chữ","Chữ chỉ hiện ra khi xuất file, lúc chỉnh sửa không thấy"],"answer":1,"explain":"Công cụ văn bản sinh ra một lớp chữ riêng nên em có thể sửa nội dung, đổi phông, màu, di chuyển mà không đụng đến ảnh. Chữ không ghi thẳng vào ảnh gốc, không xoá ảnh, và hiện ngay trong lúc chỉnh sửa chứ không đợi đến khi xuất."},{"id":"UB-mc-1203","type":"mc","topic":"E","grade":11,"level":"medium","question":"Nhóm của Minh muốn tô một mảng màu nhấn ở góc thiệp nhưng vẫn nhìn thấy được ảnh phía dưới. Em nên chỉnh thông số nào?","options":["Tăng cỡ nét lên tối đa","Đổi sang công cụ gôm tẩy","Giảm độ mờ (opacity) của nét vẽ xuống","Tăng cỡ chữ của lớp văn bản"],"answer":2,"explain":"Độ mờ quyết định nét vẽ đè lên ảnh đậm đặc hay chỉ phủ nhẹ; giảm độ mờ sẽ cho một lớp màu trong, vẫn thấy ảnh dưới. Tăng cỡ nét chỉ làm nét dày hơn chứ không trong hơn, gôm tẩy để xoá, còn cỡ chữ không liên quan đến mảng màu vẽ."},{"id":"UB-mc-1204","type":"mc","topic":"E","grade":11,"level":"medium","question":"Sau khi làm xong thiệp gồm ảnh, nét vẽ và chữ, em muốn giữ khả năng sửa từng phần về sau. Em nên làm gì?","options":["Chỉ lưu một bản JPG rồi xoá mọi thứ khác","Lưu một bản ở định dạng gốc của phần mềm giữ nguyên các lớp","Gộp phẳng tất cả lớp rồi lưu, cho gọn","Chụp lại màn hình rồi lưu ảnh chụp màn hình"],"answer":1,"explain":"Định dạng gốc của phần mềm giữ nguyên các lớp riêng biệt nên mở lại vẫn sửa từng lớp được. JPG và bản gộp phẳng đã trộn mọi thứ thành một ảnh, không tách lớp được; ảnh chụp màn hình còn tệ hơn vì mất chất lượng và cũng phẳng."},{"id":"UB-mc-1205","type":"mc","topic":"E","grade":11,"level":"hard","question":"Thiệp của lớp có phần nền đã được tách trong suốt và có dòng chữ tiêu đề sắc nét. Khi xuất file để đăng lên trang lớp, định dạng nào phù hợp nhất và vì sao?","options":["JPG, vì luôn giữ được vùng trong suốt và chữ không bao giờ bị rạn","JPG, vì đây là định dạng duy nhất đăng lên mạng được","Định dạng gốc của phần mềm, vì ai cũng mở xem trực tiếp được","PNG, vì giữ được vùng trong suốt và chữ, nét vẫn sắc"],"answer":3,"explain":"PNG giữ được vùng trong suốt và cho nét, chữ sắc nên hợp với thiệp đã tách nền. JPG không giữ được trong suốt và khi nén mạnh có thể làm chữ rạn; không phải JPG là định dạng duy nhất đăng mạng được; còn bản gốc có lớp thường chỉ mở được bằng đúng phần mềm đó, không tiện để mọi người xem."},{"id":"UB-tf-1201","type":"tf","topic":"E","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Màu vẽ là màu của nét bút và của chữ, còn màu nền dùng khi xoá hoặc tô vùng trống.","correct":true},{"text":"Nhập mã màu dạng sáu kí tự như #E53935 giúp lấy đúng một màu đã quy định.","correct":true},{"text":"Công cụ tô màu (thùng sơn) vạch nét theo tay giống như bút vẽ.","correct":false},{"text":"Cỡ nét càng lớn thì nét vẽ càng mảnh.","correct":false}],"explain":"(a) Đúng — phần mềm thường có hai ô: màu vẽ cho nét và chữ, màu nền dùng khi xoá hoặc tô vùng trống. (b) Đúng — mã màu sáu kí tự xác định chính xác một màu. (c) Sai — thùng sơn đổ màu kín cả một vùng cùng màu chỉ với một lần nhấp, không vạch nét theo tay; vạch nét theo tay là việc của bút vẽ. (d) Sai — cỡ nét càng lớn thì nét càng dày, không phải càng mảnh."},{"id":"UB-tf-1202","type":"tf","topic":"E","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Vẽ trên một lớp mới giúp giữ nguyên ảnh gốc, nếu nét chưa ưng chỉ cần xoá lớp đó.","correct":true},{"text":"Với công cụ văn bản, em có thể đổi phông, cỡ và màu chữ nhiều lần mà không đụng đến ảnh.","correct":true},{"text":"Chọn màu chữ gần giống màu nền phía sau sẽ làm chữ nổi bật, dễ đọc hơn.","correct":false},{"text":"Lớp chữ tạo ra sẽ tự động ghi thẳng vào ảnh gốc và không thể sửa nội dung.","correct":false}],"explain":"(a) Đúng — vẽ trên lớp mới thì xoá lớp là ảnh gốc vẫn nguyên. (b) Đúng — chữ nằm trên lớp riêng nên chỉnh phông, cỡ, màu thoải mái không ảnh hưởng ảnh. (c) Sai — màu chữ gần giống màu nền khiến chữ chìm mất, khó đọc; muốn nổi phải tương phản với nền. (d) Sai — lớp chữ tách khỏi ảnh và sửa nội dung được, không ghi thẳng vào ảnh gốc."},{"id":"UB-tf-1203","type":"tf","topic":"E","grade":11,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Bản lưu ở định dạng gốc của phần mềm giữ nguyên các lớp nên mở lại vẫn sửa từng lớp được.","correct":true},{"text":"Khi xuất ra PNG hoặc JPG, các lớp được gộp phẳng thành một ảnh duy nhất.","correct":true},{"text":"Định dạng JPG giữ được vùng trong suốt tốt hơn PNG.","correct":false},{"text":"Nếu chỉ lưu bản JPG và xoá bản gốc có lớp thì hôm sau vẫn tách riêng dòng chữ ra để sửa được.","correct":false}],"explain":"(a) Đúng — định dạng gốc giữ các lớp riêng biệt, mở lại sửa từng lớp được. (b) Đúng — khi xuất PNG/JPG mọi lớp bị gộp phẳng thành một ảnh, không sửa từng lớp nữa. (c) Sai — JPG không giữ được vùng trong suốt, PNG mới giữ được. (d) Sai — bản JPG đã gộp phẳng nên không tách riêng chữ ra sửa được; muốn sửa phải còn bản gốc có lớp."},{"id":"UB-mc-1301","type":"mc","topic":"E","grade":11,"level":"easy","question":"Ảnh động thực chất được tạo nên từ điều gì?","options":["Một chuỗi khung hình chiếu nối tiếp thật nhanh","Một điểm ảnh duy nhất đổi màu liên tục","Một vùng chọn di chuyển trên ảnh gốc","Một tệp âm thanh gắn vào ảnh tĩnh"],"answer":0,"explain":"Ảnh động là nhiều khung hình tĩnh xếp theo thứ tự và chiếu nối tiếp thật nhanh nên mắt thấy như chuyển động. Một điểm ảnh đổi màu không tạo được cử động của cả hình. Vùng chọn chỉ để giới hạn thao tác chỉnh sửa, không phải cơ chế tạo ảnh động. Âm thanh không liên quan tới việc hình chuyển động."},{"id":"UB-mc-1302","type":"mc","topic":"E","grade":11,"level":"easy","question":"Trong phần mềm chỉnh sửa ảnh, cách làm quen thuộc để dựng ảnh động là gì?","options":["Gộp tất cả hình vào chung một lớp duy nhất","Đặt mỗi khung hình trên một lớp riêng theo thứ tự","Tăng độ phân giải của ảnh gốc lên gấp đôi","Xoá bớt màu để tệp nhẹ hơn"],"answer":1,"explain":"Cách quen thuộc là để mỗi khung hình trên một lớp riêng, phần mềm sẽ chiếu lần lượt từng lớp. Gộp mọi hình vào một lớp thì không tách được từng khung để chiếu nối tiếp. Tăng độ phân giải chỉ làm ảnh nét hơn chứ không tạo chuyển động. Xoá màu là chuyện dung lượng, không liên quan tới việc dựng khung hình."},{"id":"UB-mc-1303","type":"mc","topic":"E","grade":11,"level":"medium","question":"Lan muốn dòng chữ sáng lâu hơn lúc mờ trong ảnh nhấp nháy hai khung. Cách chỉnh đúng là gì?","options":["Đặt cả hai khung cùng một thời gian hiển thị","Cho khung 'chữ sáng' thời gian hiển thị dài hơn khung 'chữ mờ'","Tăng số khung mỗi giây của cả ảnh lên thật cao","Xoá khung 'chữ mờ' đi"],"answer":1,"explain":"Thời gian hiển thị của từng khung có thể khác nhau, nên để khung sáng lâu hơn thì cho nó thời gian hiển thị dài hơn khung mờ. Đặt hai khung cùng thời gian thì sáng và mờ đều nhau, không đạt yêu cầu. Tăng số khung mỗi giây chỉ làm cả chuỗi chạy nhanh chứ không riêng khung sáng. Xoá khung mờ thì chữ hết nhấp nháy."},{"id":"UB-mc-1304","type":"mc","topic":"E","grade":11,"level":"medium","question":"Phát biểu nào đúng về số khung mỗi giây (fps) của một ảnh động?","options":["Số khung mỗi giây càng nhỏ thì chuyển động càng mượt","Số khung mỗi giây không ảnh hưởng gì tới dung lượng tệp","Số khung mỗi giây càng lớn thì thường càng mượt nhưng tệp càng nặng","Số khung mỗi giây chỉ đổi màu sắc chứ không đổi độ mượt"],"answer":2,"explain":"Nhiều khung mỗi giây thì mỗi bước nhích nhỏ hơn nên mượt hơn, đổi lại phải vẽ nhiều tấm nên tệp nặng hơn. Số khung nhỏ làm chuyển động giật chứ không mượt. Nhiều khung hơn rõ ràng làm tệp nặng thêm nên nói không ảnh hưởng là sai. Số khung mỗi giây tác động tới độ mượt, không phải tới màu sắc."},{"id":"UB-mc-1305","type":"mc","topic":"E","grade":11,"level":"hard","question":"Một ảnh động quả bóng nảy chạy xong một vòng rồi đứng im, không lặp lại. Nguyên nhân hợp lí nhất là gì?","options":["Các khung được đặt trên các lớp khác nhau","Chưa bật chế độ lặp khi xuất ảnh động","Số khung mỗi giây đặt quá cao","Thời gian hiển thị các khung không bằng nhau"],"answer":1,"explain":"Ảnh động lặp mãi là nhờ bật chế độ lặp; nếu quên bật, chuỗi khung chỉ chạy một lần rồi dừng ở khung cuối. Đặt mỗi khung một lớp là cách dựng bình thường, không làm mất tính lặp. Số khung mỗi giây cao chỉ khiến chạy nhanh hơn chứ vẫn lặp nếu đã bật lặp. Thời gian hiển thị khác nhau giữa các khung không ngăn ảnh lặp lại."},{"id":"UB-tf-1301","type":"tf","topic":"E","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Mỗi hình tĩnh trong chuỗi tạo nên ảnh động được gọi là một khung hình.","correct":true},{"text":"Các khung hình khác nhau một chút và thay nhau đủ nhanh khiến mắt thấy cử động liền mạch.","correct":true},{"text":"Ảnh động chỉ có thể chứa đúng hai khung hình.","correct":false},{"text":"Thứ tự các khung hình không hề ảnh hưởng tới chiều của chuyển động.","correct":false}],"explain":"(a) Đúng — mỗi hình tĩnh trong chuỗi chính là một khung hình. (b) Đúng — các khung nhích dần và đổi đủ nhanh tạo cảm giác chuyển động liền mạch. (c) Sai — ảnh động có thể gồm nhiều khung tuỳ cử động, không giới hạn ở hai. (d) Sai — đảo thứ tự khung sẽ làm chuyển động chạy sai chiều, nên thứ tự rất quan trọng."},{"id":"UB-tf-1302","type":"tf","topic":"E","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Thời gian hiển thị cho biết một khung nằm trên màn hình bao lâu trước khi nhường chỗ cho khung sau.","correct":true},{"text":"Các khung trong một ảnh động bắt buộc phải có thời gian hiển thị bằng nhau.","correct":false},{"text":"Cho một khung thời gian hiển thị dài hơn khiến khung đó như dừng lâu hơn một nhịp.","correct":true},{"text":"Thời gian hiển thị thường được tính bằng đơn vị như mili giây.","correct":true}],"explain":"(a) Đúng — thời gian hiển thị chính là khoảng một khung nằm trên màn hình. (b) Sai — các khung có thể đặt thời gian khác nhau để chỉnh nhịp nhanh chậm. (c) Đúng — khung để lâu hơn tạo cảm giác dừng một nhịp, như bóng chạm đất. (d) Đúng — thời gian hiển thị thường tính bằng mili giây hoặc phần trăm giây."},{"id":"UB-tf-1303","type":"tf","topic":"E","grade":11,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Tăng số khung mỗi giây thường làm chuyển động mượt hơn.","correct":true},{"text":"Nhồi thật nhiều khung cho một cử động ngắn luôn làm tệp nhẹ đi.","correct":false},{"text":"Với ảnh động vui trên web, khoảng 10 đến 15 khung mỗi giây thường đã đủ đẹp.","correct":true},{"text":"Số khung mỗi giây càng cao thì dung lượng tệp càng nhỏ.","correct":false}],"explain":"(a) Đúng — nhiều khung mỗi giây thì mỗi bước nhích nhỏ hơn nên mượt hơn. (b) Sai — càng nhiều khung càng phải vẽ nhiều tấm nên tệp nặng thêm chứ không nhẹ đi. (c) Đúng — ảnh động đơn giản trên web dùng khoảng 10 đến 15 khung mỗi giây là vừa đẹp. (d) Sai — số khung càng cao thì tệp càng nặng, không phải càng nhỏ."},{"id":"UB-mc-1401","type":"mc","topic":"E","grade":11,"level":"easy","question":"Trong phần mềm làm phim, khu vực nằm ngang dùng để sắp xếp các đoạn tư liệu theo thời gian được gọi là gì?","options":["Dòng thời gian (timeline)","Bảng màu","Vùng chọn","Lớp ảnh"],"answer":0,"explain":"Dòng thời gian (timeline) là dải ngang biểu diễn thời gian phim và là nơi sắp xếp các clip. Bảng màu và lớp ảnh thuộc phần mềm chỉnh ảnh, còn vùng chọn là công cụ chọn vùng ảnh, không phải nơi dựng phim."},{"id":"UB-mc-1402","type":"mc","topic":"E","grade":11,"level":"easy","question":"Một 'clip' trên dòng thời gian là gì?","options":["Một hiệu ứng lọc màu áp lên toàn phim","Một mẩu tư liệu (video, ảnh hoặc âm thanh) đã đặt lên dòng thời gian","Tên của cửa sổ xem trước","Đơn vị đo độ phân giải video"],"answer":1,"explain":"Clip là một mẩu tư liệu được đặt lên dòng thời gian, có thể là đoạn video, ảnh hoặc âm thanh. Nó không phải hiệu ứng, không phải tên cửa sổ xem trước, cũng không phải đơn vị đo độ phân giải."},{"id":"UB-mc-1403","type":"mc","topic":"E","grade":11,"level":"medium","question":"Vì sao dòng thời gian thường được chia thành nhiều rãnh (track) xếp chồng?","options":["Để tăng độ phân giải của phim","Để giảm dung lượng tệp gốc","Để nhiều loại tư liệu như hình và nhạc cùng phát tại một thời điểm","Để tự động tăng số khung hình mỗi giây"],"answer":2,"explain":"Nhiều rãnh cho phép các tư liệu khác nhau (ví dụ hình ở rãnh trên và nhạc nền ở rãnh dưới) cùng phát tại một mốc thời gian. Số rãnh không quyết định độ phân giải, không làm giảm tệp gốc và không thay đổi fps."},{"id":"UB-mc-1404","type":"mc","topic":"E","grade":11,"level":"medium","question":"Phát biểu nào đúng về khung hình mỗi giây (fps) và độ phân giải?","options":["fps càng cao thì chuyển động càng mượt nhưng tệp phim càng nặng","Độ phân giải càng cao thì hình càng mờ","fps và độ phân giải không ảnh hưởng gì đến dung lượng tệp","Độ phân giải 1280x720 nét hơn 1920x1080"],"answer":0,"explain":"fps càng cao thì càng nhiều ảnh phát mỗi giây nên mượt hơn, nhưng tệp nặng hơn. Độ phân giải cao làm hình nét hơn chứ không mờ; cả fps lẫn độ phân giải đều làm tăng dung lượng; và 1920x1080 có nhiều điểm ảnh hơn nên nét hơn 1280x720."},{"id":"UB-mc-1405","type":"mc","topic":"E","grade":11,"level":"hard","question":"Em nhập một đoạn quay dài 40 giây vào phần mềm rồi cắt clip trên dòng thời gian chỉ còn giữ lại 10 giây. Điều gì xảy ra với tệp quay gốc trong máy?","options":["Tệp gốc bị rút ngắn xuống còn 10 giây","Tệp gốc bị xoá khỏi máy","Tệp gốc vẫn nguyên 40 giây, chỉ có clip trên dòng thời gian là ngắn lại","Tệp gốc tự động tăng độ phân giải để bù phần bị cắt"],"answer":2,"explain":"Thao tác cắt chỉ tác động lên clip trên dòng thời gian, còn tệp quay gốc vẫn nguyên vẹn 40 giây. Vì thế không được xoá tệp gốc giữa chừng, nhưng cũng không lo cắt clip làm hỏng dữ liệu gốc; cắt clip không liên quan đến độ phân giải."},{"id":"UB-tf-1401","type":"tf","topic":"E","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Trên dòng thời gian, clip càng dài thì phần đó phát trong phim càng lâu.","correct":true},{"text":"Dòng thời gian chỉ chứa được đúng một clip duy nhất.","correct":false},{"text":"Vị trí về phía bên phải trên dòng thời gian ứng với thời điểm muộn hơn trong phim.","correct":true},{"text":"Ảnh tĩnh không thể đưa vào phần mềm làm phim.","correct":false}],"explain":"(a) Đúng — chiều dài clip phản ánh thời lượng phát. (b) Sai — dòng thời gian chứa nhiều clip nối tiếp và nhiều rãnh. (c) Đúng — dòng thời gian chạy từ trái sang phải theo thời gian. (d) Sai — ảnh tĩnh là một loại tư liệu hợp lệ, hiện ra như một clip ảnh."},{"id":"UB-tf-1402","type":"tf","topic":"E","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Nhập tư liệu (import) là đưa video, ảnh, âm thanh vào phần mềm để chuẩn bị dựng.","correct":true},{"text":"Cửa sổ xem trước (preview) giúp kiểm tra kết quả mà chưa cần kết xuất phim.","correct":true},{"text":"Sau khi nhập tư liệu, có thể tuỳ ý xoá tệp gốc vì phần mềm đã giữ toàn bộ bản sao.","correct":false},{"text":"Nhạc nền và hình ảnh bắt buộc phải nằm chung trên một rãnh duy nhất.","correct":false}],"explain":"(a) Đúng — import là bước đưa tư liệu vào phần mềm. (b) Đúng — preview cho phép xem thử ngay trên dòng thời gian. (c) Sai — nhập tư liệu thường chỉ liên kết tới tệp gốc, nên xoá tệp gốc sẽ làm mất tư liệu. (d) Sai — hình và nhạc thường đặt trên các rãnh khác nhau để phát song song."},{"id":"UB-tf-1403","type":"tf","topic":"E","grade":11,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Tăng độ phân giải video từ 1280x720 lên 1920x1080 thường làm tệp phim nặng hơn.","correct":true},{"text":"Với cùng nội dung, quay ở 60 fps luôn cho tệp nhẹ hơn quay ở 30 fps.","correct":false},{"text":"Phim là nhiều khung hình tĩnh phát nhanh liên tiếp nên mắt thấy chuyển động.","correct":true},{"text":"fps là đơn vị đo độ phân giải theo chiều ngang của khung hình.","correct":false}],"explain":"(a) Đúng — nhiều điểm ảnh hơn nên dữ liệu nhiều hơn, tệp nặng hơn. (b) Sai — 60 fps có nhiều khung hình hơn nên thường nặng hơn 30 fps. (c) Đúng — đó chính là nguyên lí tạo chuyển động của phim. (d) Sai — fps là số khung hình mỗi giây, còn độ phân giải mới đo số điểm ảnh theo chiều ngang và dọc."},{"id":"UB-mc-1501","type":"mc","topic":"E","grade":11,"level":"easy","question":"Trong phần mềm làm phim, khu vực nằm ngang xếp các clip từ trái sang phải theo thời gian chiếu được gọi là gì?","options":["Dòng thời gian (timeline)","Rãnh âm thanh (audio track)","Chuyển cảnh (transition)","Con trỏ thời gian (playhead)"],"answer":0,"explain":"Dòng thời gian là dải nằm ngang xếp các clip theo thời gian từ trái sang phải nên đây là đáp án đúng. Rãnh âm thanh chỉ chứa các lớp tiếng, không phải toàn bộ khu vực dựng phim. Chuyển cảnh là hiệu ứng đặt ở mối nối giữa hai clip. Con trỏ thời gian chỉ là vạch đánh dấu đang xem tới giây nào, không phải cả khu vực dựng."},{"id":"UB-mc-1502","type":"mc","topic":"E","grade":11,"level":"easy","question":"Thao tác 'cắt' (trim) một clip trong khi biên tập phim có nghĩa là gì?","options":["Xoá vĩnh viễn tệp video gốc trong máy","Bỏ bớt phần đầu hoặc phần cuối thừa của clip trên dòng thời gian","Tăng độ phân giải cho clip","Thêm nhạc nền vào clip"],"answer":1,"explain":"Cắt là bỏ bớt phần đầu hoặc phần cuối thừa của clip trên dòng thời gian nên đáp án này đúng. Cắt không xoá tệp quay gốc trong máy, tệp đó vẫn nguyên vẹn. Cắt không làm thay đổi độ phân giải của hình. Thêm nhạc nền là thao tác về âm thanh, hoàn toàn khác với cắt clip."},{"id":"UB-mc-1503","type":"mc","topic":"E","grade":11,"level":"medium","question":"Hà thấy phim nhảy 'cụp' rất gắt khi chuyển từ cảnh con đường sang cảnh bữa trưa. Cách xử lí phù hợp là gì?","options":["Tăng âm lượng nhạc nền cho hai cảnh","Xoá bớt một trong hai clip","Thêm một chuyển cảnh mờ dần vào chỗ giáp ranh hai clip","Xuất phim ở độ phân giải cao hơn"],"answer":2,"explain":"Chuyển cảnh đặt ở chỗ giáp ranh hai clip làm mối nối mềm hơn nên thêm hiệu ứng mờ dần là cách đúng. Tăng âm lượng nhạc nền không xử lí được cú nhảy hình giật cục. Xoá một clip thì mất luôn nội dung cảnh đó chứ không làm mượt mối nối. Tăng độ phân giải khi xuất chỉ làm hình nét hơn, không liên quan tới độ mượt khi chuyển cảnh."},{"id":"UB-mc-1504","type":"mc","topic":"E","grade":11,"level":"medium","question":"Khi ghép phim, nhạc nền đang át hết lời các bạn nói trong clip. Việc cần làm trước tiên là gì?","options":["Hạ nhỏ âm lượng của rãnh nhạc nền lại","Xoá toàn bộ tiếng thu trong clip","Kéo dài thời lượng mỗi chuyển cảnh","Đổi định dạng tệp khi xuất phim"],"answer":0,"explain":"Chỉnh âm lượng để các lớp tiếng không lấn nhau là mấu chốt, nên hạ nhỏ nhạc nền để nghe rõ lời nói là việc cần làm. Xoá hết tiếng thu trong clip sẽ mất luôn lời các bạn cần giữ. Kéo dài chuyển cảnh chỉ ảnh hưởng tới hình, không giải quyết việc nhạc át tiếng. Đổi định dạng tệp là chuyện của bước xuất phim, không liên quan tới cân bằng âm lượng."},{"id":"UB-mc-1505","type":"mc","topic":"E","grade":11,"level":"hard","question":"Xem thử trên dòng thời gian thấy phim đã ưng ý, nhưng vì sao vẫn chưa thể gửi cho bạn qua mạng và cần bước xuất phim (export)?","options":["Vì dòng thời gian tự động là một tệp .mp4 sẵn rồi","Vì phải xoá hết các rãnh âm thanh trước khi gửi","Vì bản dựng trên dòng thời gian chỉ tồn tại trong phần mềm, phải xuất mới thành một tệp video hoàn chỉnh","Vì cần tăng số lượng clip lên cho đủ dài"],"answer":2,"explain":"Bản dựng trên dòng thời gian chỉ là cách sắp xếp bên trong phần mềm, phải xuất phim mới gộp mọi thứ thành một tệp video mở được ở máy khác, nên đây là đáp án đúng. Dòng thời gian không tự nó là tệp .mp4. Không cần xoá rãnh âm thanh vì xuất phim sẽ gộp cả tiếng vào tệp. Số lượng clip không quyết định việc phim đã thành tệp hay chưa."},{"id":"UB-tf-1501","type":"tf","topic":"E","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Trên dòng thời gian, thứ tự các clip từ trái sang phải chính là thứ tự các cảnh được chiếu.","correct":true},{"text":"Cắt clip trên dòng thời gian sẽ xoá luôn tệp video gốc trong máy.","correct":false},{"text":"Sau khi cắt, kéo các clip sát lại để phim chạy liền mạch, không bị đứng hình.","correct":true},{"text":"Kéo đổi vị trí hai khối clip sẽ làm đổi thứ tự cảnh trong phim.","correct":true}],"explain":"(a) Đúng — clip xếp từ trái sang phải và chiếu đúng theo thứ tự đó. (b) Sai — cắt chỉ tác động trên clip của dòng thời gian, tệp quay gốc vẫn nguyên vẹn. (c) Đúng — kéo các clip sát lại giúp bỏ khoảng trống để phim chạy liền mạch. (d) Đúng — đổi vị trí khối clip chính là đổi thứ tự cảnh trong mạch kể chuyện."},{"id":"UB-tf-1502","type":"tf","topic":"E","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Chuyển cảnh được đặt vào chỗ giáp ranh giữa hai clip để mối nối mềm hơn.","correct":true},{"text":"Đặt chuyển cảnh quá dài luôn làm phim hay hơn nên cần dùng cho mọi mối nối.","correct":false},{"text":"Fade in giúp tiếng to dần lên ở đầu, fade out giúp tiếng nhỏ dần đi ở cuối.","correct":true},{"text":"Nhạc nền nên để to hơn hẳn lời nói để lấn át tiếng thu trong clip.","correct":false}],"explain":"(a) Đúng — chuyển cảnh nằm ở mối nối giữa hai clip để làm mượt cú chuyển. (b) Sai — chuyển cảnh quá dài làm phim lê thê và mất nội dung ở hai đầu, nên dùng có chừng mực. (c) Đúng — fade in và fade out làm tiếng vào ra êm chứ không đột ngột. (d) Sai — nhạc nền phải hạ nhỏ để không át lời nói, chứ không để lấn át tiếng thu."},{"id":"UB-tf-1503","type":"tf","topic":"E","grade":11,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Xuất phim gộp các clip, chuyển cảnh và rãnh âm thanh thành một tệp video duy nhất.","correct":true},{"text":"Khi xuất phim, chất lượng càng cao thì tệp càng nặng và thời gian xuất càng lâu.","correct":true},{"text":"Bản dựng trên dòng thời gian đã là một tệp video hoàn chỉnh, không cần xuất.","correct":false},{"text":"Nên xem lại tệp thành phẩm sau khi xuất để phòng khi có đoạn bị lỗi.","correct":true}],"explain":"(a) Đúng — xuất phim gộp mọi rãnh hình và tiếng cùng hiệu ứng thành một tệp video. (b) Đúng — chất lượng cao đổi lấy tệp nặng và thời gian xuất lâu hơn. (c) Sai — bản dựng chỉ tồn tại trong phần mềm, phải xuất mới thành tệp video hoàn chỉnh. (d) Đúng — xem lại thành phẩm giúp phát hiện đoạn lỗi trước khi nộp hay gửi đi."}]);
  LESSONS.push(
    {"id":"U11-01","stage":23,"order":1,"topic":"C","grade":11,"minutes":12,"title":"Làm quen hệ quản trị cơ sở dữ liệu trên máy","intro":"Bạn đã biết cơ sở dữ liệu là gì. Giờ chúng ta mở một **phần mềm hệ quản trị cơ sở dữ liệu** ra và làm quen với màn hình làm việc thật của nó: các nút, các đối tượng và quy trình để bắt đầu tạo một CSDL cho riêng mình.","sections":[{"t":"story","text":"Lớp 11A5 nhận nhiệm vụ quản lí câu lạc bộ sách của trường. Lúc đầu, bạn thủ quỹ dùng một bảng tính để ghi tên thành viên, sách đang mượn và hạn trả. Được vài tuần thì mọi thứ rối tung: một bạn tên bị gõ hai kiểu khác nhau, có dòng ghi ngày trả vào ô ghi tên sách, và mỗi lần muốn tìm \"ai đang mượn quá hạn\" thì phải kéo chuột dò từng dòng.\n\nCô giáo gợi ý: thay vì một bảng tính lộn xộn, cả nhóm hãy thử một loại phần mềm khác, được sinh ra chính để quản lí dữ liệu có tổ chức. Khi mở phần mềm đó lên, các bạn thấy nó không chỉ có ô để gõ số như bảng tính, mà còn có những khu vực tên lạ: nơi để tạo bảng, nơi để làm màn hình nhập liệu, nơi để tìm kiếm và nơi để in ra danh sách đẹp đẽ.\n\nCả nhóm tò mò: mỗi khu vực đó dùng để làm gì, và bắt đầu từ đâu? Bài học này sẽ dẫn bạn đi một vòng làm quen với chính phần mềm đó."},{"t":"h","text":"1) Hệ quản trị cơ sở dữ liệu nhìn từ màn hình làm việc"},{"t":"text","text":"**Hệ quản trị cơ sở dữ liệu** (viết tắt là **hệ QTCSDL**) là một phần mềm cài trên máy, cho phép bạn tạo ra một cơ sở dữ liệu, nhập dữ liệu vào và khai thác dữ liệu đó ngay trên giao diện của nó. Khác với việc chỉ hình dung CSDL trên lí thuyết, ở đây bạn thật sự bấm nút, gõ tên bảng, chọn kiểu dữ liệu và thấy kết quả hiện ra.\n\nKhi mở phần mềm, bạn thường thấy một **cửa sổ chính** với một vùng danh sách bên trái liệt kê tất cả những gì mình đã tạo, và một vùng lớn bên phải để hiển thị hoặc chỉnh sửa đối tượng đang chọn. Trên cùng là thanh công cụ với các nút quen thuộc như tạo mới, lưu, mở, xoá. Toàn bộ công việc quản lí dữ liệu của bạn sẽ diễn ra trong cửa sổ này."},{"t":"h","text":"2) Bốn loại đối tượng chính và việc của từng loại"},{"t":"list","text":"Điều làm hệ QTCSDL khác hẳn phần mềm bảng tính là nó chia công việc thành nhiều **đối tượng**, mỗi loại lo một việc. Bốn loại thường gặp:","items":["**Bảng** (`table`): nơi thật sự chứa dữ liệu, xếp thành hàng và cột. Đây là kho gốc, các đối tượng khác đều lấy dữ liệu từ bảng.","**Biểu mẫu** (`form`): màn hình nhập và xem từng bản ghi cho dễ nhìn, thay vì gõ thẳng vào bảng dày đặc; giúp người nhập ít nhầm ô.","**Truy vấn** (`query`): công cụ đặt câu hỏi cho dữ liệu, ví dụ \"ai đang mượn quá hạn\", rồi lọc và trả về đúng những dòng thoả điều kiện.","**Báo cáo** (`report`): mẫu trình bày dữ liệu để in ra hoặc xuất file, ví dụ danh sách thành viên có tiêu đề, cột đẹp và tổng số."]},{"t":"note","text":"Bẫy hay gặp: nghĩ rằng \"biểu mẫu\" hay \"truy vấn\" cũng chứa dữ liệu riêng. Không phải. **Chỉ có bảng chứa dữ liệu thật**; biểu mẫu, truy vấn và báo cáo chỉ là các cách nhìn và làm việc với dữ liệu đang nằm trong bảng. Xoá một truy vấn không làm mất dữ liệu; xoá một bảng thì mất."},{"t":"h","text":"3) Tệp cơ sở dữ liệu khác gì một bảng tính?"},{"t":"text","text":"Nhiều bạn quen dùng bảng tính nên tưởng hai thứ giống nhau vì đều có hàng và cột. Nhưng một **tệp CSDL** không chỉ là một bảng. Nó là một túi chứa đựng nhiều đối tượng cùng lúc: có thể có vài bảng liên quan tới nhau, kèm các biểu mẫu, truy vấn và báo cáo đi cùng. Mở một tệp CSDL ra là mở cả một hệ thống quản lí, không phải mở một trang tính.\n\nMột khác biệt quan trọng nữa: trong bảng của hệ QTCSDL, **mỗi cột bị ràng buộc một kiểu dữ liệu cố định**. Cột \"ngày trả\" chỉ nhận ngày, cột \"số điện thoại\" chỉ nhận đúng dạng đã đặt. Nhờ vậy phần mềm tự chặn những dòng ghi sai kiểu, thứ mà bảng tính thường để lọt. Bảng tính rất linh hoạt để tính toán nhanh, còn hệ QTCSDL mạnh ở việc giữ dữ liệu sạch, có cấu trúc và dễ tra cứu khi dữ liệu lớn dần."},{"t":"h","text":"4) Quy trình chung khi bắt đầu một CSDL"},{"t":"text","text":"Dù dùng phần mềm hệ QTCSDL nào, các bước khởi đầu gần như giống nhau. Điểm cần nhớ là **phải tạo tệp CSDL rỗng trước**, đặt tên và chọn nơi lưu, rồi mới lần lượt tạo bảng bên trong. Nhiều bạn mới học hay quýnh lên đòi nhập dữ liệu ngay khi chưa có bảng nào để chứa; nắm được trình tự dưới đây, bạn sẽ không bị rối khi ngồi trước màn hình lần đầu."},{"t":"list","text":"Trình tự chung để dựng một CSDL mới:","items":["Tạo một **tệp CSDL rỗng**, đặt tên rõ nghĩa và chọn thư mục lưu trên máy.","Tạo **bảng** đầu tiên: khai báo các cột và kiểu dữ liệu cho từng cột.","**Nhập dữ liệu** vào bảng, có thể gõ trực tiếp hoặc qua một biểu mẫu.","**Khai thác** dữ liệu bằng truy vấn để lọc, tìm kiếm và báo cáo để in ấn."]},{"t":"example","text":"Hình dung vùng danh sách đối tượng bên trái cửa sổ khi câu lạc bộ sách vừa dựng xong CSDL của mình:","code":"Tệp CSDL: CLB_Sach\n  Bảng     : THANHVIEN, SACH, PHIEUMUON\n  Biểu mẫu : Nhap_ThanhVien\n  Truy vấn : Muon_QuaHan\n  Báo cáo  : DS_ThanhVien","output":"Một tệp CSDL duy nhất chứa 3 bảng dữ liệu và 3 đối tượng khai thác đi kèm. Bấm vào \"Muon_QuaHan\" sẽ chạy truy vấn và hiện ra danh sách bạn đang mượn sách quá hạn, lấy dữ liệu từ các bảng chứ không lưu riêng."}],"keypoints":["**Hệ QTCSDL** là phần mềm để tạo, nhập và khai thác cơ sở dữ liệu ngay trên máy.","Bốn đối tượng chính: **bảng** chứa dữ liệu, **biểu mẫu** để nhập, **truy vấn** để lọc tìm, **báo cáo** để in.","Chỉ có **bảng** chứa dữ liệu thật; các đối tượng khác chỉ là cách nhìn và làm việc với dữ liệu trong bảng.","Quy trình chung: tạo **tệp CSDL rỗng** trước, rồi tạo bảng, nhập dữ liệu, cuối cùng mới khai thác."],"quiz":["UB-mc-101","UB-mc-102","UB-mc-103","UB-mc-104","UB-mc-105","UB-tf-101","UB-tf-102","UB-tf-103","UD2-mc-001","UD2-mc-002","UD2-mc-003","UD2-mc-004","UD2-tf-001","UD2-tf-002"]},
    {"id":"U11-02","stage":23,"order":2,"topic":"C","grade":11,"minutes":12,"title":"Thiết kế cấu trúc bảng: trường, kiểu dữ liệu và khoá chính","intro":"Trước khi gõ dữ liệu vào máy, ta phải **thiết kế** trước cái khung để chứa dữ liệu. Bài này hướng dẫn thao tác dựng cấu trúc một bảng: đặt tên **trường**, chọn **kiểu dữ liệu** phù hợp và chỉ định **khoá chính** ngay trong phần mềm.","sections":[{"t":"story","text":"Lớp 11A5 tổ chức bán nước ép gây quỹ cho chuyến đi thực tế. Bạn Minh xung phong ghi chép, mở một quyển sổ và kẻ bảng để theo dõi mỗi lần bán: ai mua, mua loại gì, mấy ly, ngày nào, đã trả tiền hay chưa.\n\nĐược vài hôm thì quyển sổ rối tung. Có dòng Minh ghi ngày là \"thứ ba\", có dòng lại ghi \"12/9\", có dòng ghi số ly là \"hai ly\" thay vì \"2\". Đến lúc cộng tiền cả tuần, Minh không tài nào lọc ra được những lần chưa thu tiền, cũng chẳng biết dòng nào trùng với dòng nào.\n\nCô giáo gợi ý Minh chuyển sổ tay sang máy tính. Nhưng cô nhấn mạnh: đừng vội gõ dữ liệu, hãy dựng trước cái \"khung\" cho gọn gàng. Cái khung đó chính là việc thiết kế cấu trúc bảng mà chúng ta học hôm nay."},{"t":"h","text":"1) Bảng là gì và vì sao phải thiết kế trước"},{"t":"text","text":"Trong phần mềm **hệ quản trị cơ sở dữ liệu**, dữ liệu được cất trong các **bảng**. Một bảng giống một tấm lưới: mỗi **cột** là một **trường** (mô tả một loại thông tin, ví dụ họ tên, số ly, ngày bán), mỗi **hàng** là một **bản ghi** (thông tin về một lần bán cụ thể).\n\nKhác với gõ đại vào bảng tính, ở đây ta phải **thiết kế cấu trúc bảng trước**: khai báo bảng có những trường nào, mỗi trường tên gì và chứa loại dữ liệu gì. Khung đã dựng chặt chẽ thì lúc nhập dữ liệu phần mềm sẽ tự canh khuôn, ngăn được kiểu ghi lộn xộn như quyển sổ của Minh."},{"t":"h","text":"2) Trường và kiểu dữ liệu"},{"t":"text","text":"Mỗi trường cần hai thứ cơ bản: một **tên trường** và một **kiểu dữ liệu**. Tên trường nên ngắn gọn, không dấu cách, gợi đúng nội dung, ví dụ `HoTen`, `SoLy`, `NgayBan`, `DaTra`. Kiểu dữ liệu quyết định trường đó được phép chứa loại giá trị nào; khi thiết kế, ở mỗi trường ta bấm chọn kiểu trong danh sách, giống như dán nhãn \"ô này chỉ đựng số\", \"ô kia chỉ đựng ngày\".\n\nChọn kiểu dữ liệu không phải chuyện hình thức. Nếu để `SoLy` là văn bản, phần mềm sẽ coi \"2\" và \"hai\" như hai xâu chữ khác nhau và **không cộng lại được** để tính tổng số ly bán ra; nếu để `NgayBan` là văn bản, thứ tự sắp xếp sẽ theo mặt chữ (\"12/9\" đứng trước \"2/9\") chứ không theo trục thời gian thật.\n\nNgược lại, chọn đúng kiểu giúp phần mềm **canh khuôn dữ liệu** và tính toán tự động: cộng doanh thu, đếm số lần chưa thu tiền, lọc các lần bán trong một ngày. Kiểu dữ liệu vừa giữ dữ liệu sạch từ lúc nhập, vừa mở đường cho việc xử lí về sau."},{"t":"list","text":"Một số kiểu dữ liệu thường dùng và ví dụ trong bảng bán nước ép:","items":["Kiểu văn bản: chứa chữ, chữ lẫn số, như `HoTen` = \"Trần Bảo Minh\", `LoaiNuoc` = \"Cam\".","Kiểu số: chứa con số để tính toán, như `SoLy` = 3, `DonGia` = 12000.","Kiểu ngày/giờ: chứa ngày tháng chuẩn, như `NgayBan` = 12/09/2025, cho phép sắp xếp và lọc theo thời gian.","Kiểu lôgic (đúng/sai): chỉ nhận một trong hai giá trị, như `DaTra` = Đúng nếu đã thu tiền, Sai nếu chưa."]},{"t":"note","text":"Bẫy thường gặp: dồn nhiều thông tin vào một trường, ví dụ trường `KhachHang` ghi cả \"Minh - 0901xxx - lớp 11A5\". Khi đó không lọc riêng theo lớp hay tìm theo số điện thoại được. Nguyên tắc là **mỗi trường chỉ chứa một loại thông tin**; cần tách thì tạo thêm trường."},{"t":"h","text":"3) Khoá chính: định danh duy nhất mỗi bản ghi"},{"t":"text","text":"Trong bảng có thể có hai bản ghi giống hệt nhau ở nhiều trường: cùng khách, cùng loại nước, cùng ngày. Để phần mềm phân biệt chắc chắn từng bản ghi, ta chỉ định một **khoá chính** — một trường (hoặc nhóm trường) mà giá trị **không trùng** và **không để trống** ở bất kì bản ghi nào.\n\nMột khoá chính tốt nên gọn, ổn định và chắc chắn duy nhất. Trường như `HoTen` không hợp làm khoá vì hai bạn có thể trùng tên. Cách phổ biến là thêm một trường **mã định danh** riêng, chẳng hạn `MaBan` đánh số 1, 2, 3… tự tăng cho mỗi lần bán. Khi thiết kế, ta chọn trường này rồi bấm đặt làm khoá chính; phần mềm thường đánh dấu nó bằng biểu tượng chiếc chìa khoá."},{"t":"h","text":"4) Chế độ thiết kế và chế độ nhập dữ liệu"},{"t":"text","text":"Phần mềm cho xem một bảng theo hai chế độ. **Chế độ thiết kế** là nơi ta dựng và sửa cấu trúc: thêm/bớt trường, đổi tên trường, chọn kiểu dữ liệu, đặt khoá chính. Ở đây ta làm việc với cái khung, chưa quan tâm nội dung.\n\n**Chế độ nhập dữ liệu** (dạng bảng lưới) là nơi ta gõ và xem các bản ghi thật, mỗi hàng một bản ghi. Quy trình đúng là: vào chế độ thiết kế dựng khung xong, **lưu** lại, rồi mới chuyển sang chế độ nhập dữ liệu để điền. Muốn sửa kiểu dữ liệu hay thêm trường thì quay lại chế độ thiết kế; hai chế độ chỉ là hai cách nhìn cùng một bảng."},{"t":"bang","text":"Bản thiết kế bảng `BanNuoc` cho quầy gây quỹ của lớp 11A5. Cột đầu là tên trường, cột sau là kiểu dữ liệu đã chọn:","head":["Ten truong","Kieu du lieu","Ghi chu"],"rows":[["MaBan","So (tu tang)","<- Khoa chinh"],["HoTen","Van ban",""],["LoaiNuoc","Van ban",""],["SoLy","So",""],["NgayBan","Ngay/gio",""],["DaTra","Lo-gic (D/S)",""]]},{"t":"example","output":"Bảng có 6 trường. `MaBan` được đặt làm khoá chính nên mỗi lần bán có một mã riêng, không trùng. `SoLy` là kiểu số nên cộng được tổng số ly; `NgayBan` là kiểu ngày nên lọc/sắp xếp theo thời gian; `DaTra` là lôgic nên đếm nhanh số lần chưa thu tiền."}],"keypoints":["Bảng gồm các **trường** (cột) và **bản ghi** (hàng); phải **thiết kế cấu trúc** trước rồi mới nhập dữ liệu.","Mỗi trường có **tên** và một **kiểu dữ liệu** (văn bản, số, ngày/giờ, lôgic); chọn đúng kiểu để dữ liệu sạch và tính toán được.","**Khoá chính** là trường định danh **duy nhất, không trống** mỗi bản ghi; nên dùng trường mã riêng thay vì họ tên.","**Chế độ thiết kế** để dựng/sửa khung, **chế độ nhập dữ liệu** để điền bản ghi — hai cách nhìn cùng một bảng."],"quiz":["UB-mc-201","UB-mc-202","UB-mc-203","UB-mc-204","UB-mc-205","UB-tf-201","UB-tf-202","UB-tf-203","UD2-mc-005","UD2-mc-006","UD2-mc-007","UD2-mc-008","UD2-tf-003","UD2-tf-004"]},
    {"id":"U11-03","stage":23,"order":3,"topic":"C","grade":11,"minutes":12,"title":"Tạo lập cơ sở dữ liệu và các bảng đầu tiên","intro":"Sau khi đã có bản thiết kế trên giấy, việc còn lại là **biến nó thành thật** trong phần mềm. Bài này đi từng bước: tạo một CSDL mới, tạo bảng theo đúng cấu trúc đã định, lưu lại, rồi nhập vài bản ghi mẫu để kiểm tra.","sections":[{"t":"story","text":"Lớp 11A5 nhận việc quản lí quầy sách cũ gây quỹ của trường. Tuần trước, nhóm Minh đã ngồi vẽ ra giấy: cần một chỗ lưu danh sách sách, một chỗ lưu danh sách bạn mượn, mỗi chỗ ghi những thông tin gì, cột nào không được trùng. Bản vẽ đã xong và khá đẹp.\n\nHôm nay tới phòng máy, Minh mở phần mềm lên và hơi lúng túng: màn hình trống trơn, không thấy chỗ nào để gõ tên sách. Cô giáo cười: \"Bản vẽ mới là ý tưởng thôi. Giờ chúng ta phải dựng cái nhà thật theo bản vẽ đó: đầu tiên tạo một cái kho rỗng, sau đó dựng từng cái ngăn tủ bên trong, rồi mới xếp sách vào.\"\n\nCả nhóm gật gù. Hoá ra từ bản thiết kế đến một CSDL chạy được vẫn còn vài bước tay chân phải làm cho đúng thứ tự."},{"t":"h","text":"1) Ba việc theo đúng thứ tự"},{"t":"text","text":"Khi làm việc với một **hệ quản trị cơ sở dữ liệu**, đừng vội gõ dữ liệu ngay. Có ba việc phải làm lần lượt, không được đảo: tạo **cơ sở dữ liệu** (cái kho tổng), tạo **bảng** bên trong kho đó (từng ngăn tủ), rồi mới **nhập bản ghi** (xếp đồ vào ngăn).\n\nHãy hình dung cơ sở dữ liệu như một cuốn sổ tổng của quầy sách. Trong cuốn sổ đó có nhiều trang, mỗi trang là một bảng: trang `SACH` ghi thông tin sách, trang `MUON` ghi các lượt mượn. Mỗi dòng trên trang là một bản ghi. Nếu chưa có cuốn sổ thì không thể có trang; chưa có trang thì không có chỗ ghi dòng nào cả."},{"t":"h","text":"2) Tạo một cơ sở dữ liệu mới"},{"t":"text","text":"Việc đầu tiên là tạo một CSDL rỗng và **đặt tên** cho nó. Tên nên gợi đúng nội dung, ví dụ `QuanLySach`, không nên để tên mặc định kiểu `Database1`. Phần mềm sẽ tạo ra một tệp (hoặc một vùng lưu trên máy chủ) để chứa tất cả các bảng sau này.\n\nKhi tạo, em chọn **nơi lưu** rõ ràng, chẳng hạn thư mục bài tập của mình, để lần sau mở lại không bị lạc. Nhiều phần mềm yêu cầu đặt tên và lưu tệp ngay từ lúc tạo, trước cả khi có bảng nào; số khác cho tạo trong bộ nhớ rồi lưu sau. Dù kiểu nào, hãy lưu sớm để tránh mất công."},{"t":"h","text":"3) Tạo bảng theo cấu trúc đã thiết kế"},{"t":"list","text":"Có kho rồi thì dựng bảng. Quy trình tạo một bảng thường gồm các bước:","items":["Chọn tạo bảng mới, thường mở ra chế độ thiết kế để khai báo cấu trúc","Gõ tên từng trường vào cột tên, ví dụ `MaSach`, `TenSach`, `TacGia`, `NamXB`","Chọn kiểu dữ liệu phù hợp cho mỗi trường: chữ, số nguyên, ngày...","Đặt khoá chính cho trường định danh, ví dụ `MaSach`, để mỗi bản ghi không trùng","Lưu bảng và đặt tên bảng, ví dụ `SACH`, khi phần mềm hỏi"]},{"t":"text","text":"Mấu chốt là bám sát bản thiết kế: bảng có bao nhiêu trường, tên trường viết thế nào, trường nào làm **khoá chính**. Tên trường nên viết liền, không dấu, không khoảng trắng để về sau viết truy vấn cho gọn, chẳng hạn dùng `NgayMuon` thay vì `Ngày mượn`.\n\nSau khi lưu, bảng `SACH` xuất hiện trong danh sách các bảng của CSDL. Lặp lại đúng quy trình đó để tạo tiếp bảng `MUON`. Lúc này kho `QuanLySach` đã có hai ngăn tủ, tuy còn rỗng nhưng cấu trúc đã sẵn sàng."},{"t":"h","text":"4) Mở lại để chỉnh cấu trúc và nhập bản ghi mẫu"},{"t":"text","text":"Không ai làm đúng ngay lần đầu. Muốn sửa cấu trúc, em mở lại bảng ở **chế độ thiết kế** để thêm trường, đổi tên hay đổi kiểu dữ liệu; còn muốn gõ dữ liệu thì mở ở **chế độ nhập liệu** (xem bảng như một lưới dòng - cột). Phân biệt hai chế độ này giúp em không loay hoay tìm chỗ gõ như bạn Minh lúc đầu.\n\nViệc nên làm ngay sau khi tạo bảng là nhập **vài bản ghi mẫu**, chừng 3 đến 5 dòng, để kiểm tra cấu trúc có ổn không. Nếu gõ được năm xuất bản là số, mã sách không cho trùng, ngày mượn nhận đúng định dạng ngày thì thiết kế đã đúng. Đây là bước thử nhỏ nhưng phát hiện sớm lỗi, đỡ phải sửa khi đã có hàng trăm dòng."},{"t":"example","text":"Minh hoạ bảng `SACH` sau khi tạo cấu trúc và nhập 3 bản ghi mẫu để kiểm tra:","code":"Bảng SACH — cấu trúc:\n  MaSach   : chữ (khoá chính)\n  TenSach  : chữ\n  TacGia   : chữ\n  NamXB    : số nguyên\n\nNhập thử 3 bản ghi:\n  S001 | Dế Mèn phiêu lưu kí | Tô Hoài     | 2019\n  S002 | Toán 11 nâng cao    | Nhiều tác giả | 2022\n  S003 | Số đỏ               | Vũ Trọng Phụng | 2018","output":"Ba dòng nhập thành công, MaSach không trùng, NamXB nhận đúng số. Kết luận: cấu trúc bảng đã đúng, sẵn sàng nhập tiếp."},{"t":"note","text":"Bẫy thường gặp: (1) quên đặt khoá chính, để mã sách bị trùng mà không báo lỗi; (2) đặt sai kiểu dữ liệu, ví dụ để `NamXB` là chữ nên không tính toán được; (3) tên trường có khoảng trắng hoặc dấu, gây rắc rối khi truy vấn; (4) tạo bảng nhưng quên lưu, đóng phần mềm là mất cấu trúc. Cứ tạo xong là **lưu ngay** và nhập vài dòng thử."}],"keypoints":["Đúng thứ tự: tạo **cơ sở dữ liệu**, rồi tạo **bảng**, rồi mới **nhập bản ghi**","Tạo CSDL cần **đặt tên** và **chọn nơi lưu** rõ ràng, nên lưu sớm","Tạo bảng ở **chế độ thiết kế**: khai báo trường, chọn kiểu dữ liệu, đặt **khoá chính**, rồi lưu và đặt tên bảng","Nhập **vài bản ghi mẫu** để kiểm tra cấu trúc, phát hiện sớm lỗi kiểu dữ liệu và khoá chính"],"quiz":["UB-mc-301","UB-mc-302","UB-mc-303","UB-mc-304","UB-mc-305","UB-tf-301","UB-tf-302","UB-tf-303","UD2-mc-009","UD2-mc-010","UD2-mc-011","UD2-mc-012","UD2-tf-005","UD2-tf-006"]},
    {"id":"U11-04","stage":23,"order":4,"topic":"C","grade":11,"minutes":12,"title":"Khoá ngoài và liên kết giữa các bảng","intro":"Ở các bài trước, em đã tạo được vài bảng riêng lẻ. Bài này em học cách **nối** các bảng lại với nhau bằng **khoá ngoài**, để một cơ sở dữ liệu thực sự làm việc như một khối thống nhất.","sections":[{"t":"story","text":"Lớp em lập một cuốn sổ theo dõi việc mượn sách ở thư viện lớp. Ban đầu, mỗi lần có bạn mượn sách, thủ thư ghi vào một dòng: họ tên bạn, ngày sinh, tổ, rồi tên sách, tác giả, nhà xuất bản. Cuốn sổ đầy rất nhanh và trông rắc rối.\n\nBạn Minh mượn sách chăm nhất lớp, tuần nào cũng ba bốn lần. Thế là trong sổ, họ tên, ngày sinh, tổ của Minh bị chép đi chép lại hàng chục lần, y hệt nhau. Một hôm Minh chuyển sang tổ khác, thủ thư phải lật lại toàn bộ cuốn sổ để sửa từng dòng có tên Minh. Sửa sót một dòng là dữ liệu \"cãi nhau\" ngay: cùng một người mà chỗ ghi tổ 1, chỗ ghi tổ 3.\n\nCả lớp nghĩ ra cách hay hơn: tách thông tin học sinh ra một cuốn riêng, thông tin sách ra một cuốn riêng, còn cuốn ghi mượn thì chỉ cần ghi \"mã của bạn nào\" mượn \"mã của cuốn sách nào\". Đó chính là ý tưởng cốt lõi của bài học hôm nay."},{"t":"h","text":"1) Vì sao không nên nhồi tất cả vào một bảng"},{"t":"text","text":"Khi em cố nhét mọi thông tin vào **một bảng lớn** duy nhất, dữ liệu của cùng một đối tượng sẽ bị lặp lại ở rất nhiều dòng. Trong câu chuyện trên, thông tin của Minh lặp lại theo đúng số lần Minh mượn sách. Lặp như vậy vừa tốn chỗ, vừa dễ sai.\n\nNguy hiểm nhất là khi cần **cập nhật**. Nếu Minh đổi tổ, em phải sửa tất cả các dòng có tên Minh; bỏ sót một dòng là cơ sở dữ liệu mâu thuẫn với chính nó. Người ta gọi đây là hiện tượng dữ liệu **trùng lặp** và **thiếu nhất quán**.\n\nGiải pháp là **tách** dữ liệu thành nhiều bảng, mỗi bảng lo một loại đối tượng: một bảng cho học sinh, một bảng cho sách, một bảng cho các lượt mượn. Mỗi thông tin gốc chỉ được ghi **đúng một chỗ**, và các bảng còn lại chỉ trỏ tới nó."},{"t":"h","text":"2) Khoá chính nhắc lại nhanh"},{"t":"text","text":"Mỗi bảng nên có một **khoá chính** — một trường (hoặc nhóm trường) mà giá trị của nó là **duy nhất** cho từng bản ghi, dùng để phân biệt bản ghi này với bản ghi khác. Ví dụ bảng học sinh dùng trường `MaHS`, bảng sách dùng trường `MaSach`.\n\nGiá trị khoá chính giống như số báo danh: không hai bạn nào trùng nhau, và nhìn vào số đó là biết chính xác đang nói tới ai. Nhờ có khoá chính, các bảng khác chỉ cần ghi lại **mã** này là đủ để tham chiếu, không phải chép lại cả họ tên, ngày sinh."},{"t":"h","text":"3) Khoá ngoài là gì"},{"t":"text","text":"**Khoá ngoài** là một trường trong bảng này dùng để **tham chiếu** tới **khoá chính** của một bảng khác. Nó chính là \"sợi dây\" nối hai bảng lại.\n\nTrong ví dụ thư viện, bảng ghi các lượt mượn có trường `MaHS`. Trường `MaHS` này không phải khoá chính của bảng mượn — nó là **khoá ngoài** trỏ sang bảng học sinh, cho biết lượt mượn đó là của bạn nào. Tương tự, trường `MaSach` trong bảng mượn là khoá ngoài trỏ sang bảng sách.\n\nĐiểm mấu chốt: giá trị của khoá ngoài phải là một giá trị **đã có thật** ở khoá chính bảng bên kia. Không thể ghi một lượt mượn với `MaHS` là một mã không tồn tại trong bảng học sinh — như vậy sẽ trỏ vào chỗ trống, dữ liệu vô nghĩa."},{"t":"list","text":"Để nhận ra khoá ngoài, em chú ý ba dấu hiệu:","items":["Là một trường nằm trong bảng đang xét (bảng \"con\", phía nhiều).","Giá trị của nó khớp với khoá chính của một bảng khác (bảng \"cha\", phía một).","Nó không nhất thiết duy nhất trong bảng con: nhiều bản ghi có thể cùng trỏ tới một bản ghi cha.","Nó dùng để thay cho việc chép lại toàn bộ thông tin của bản ghi cha."]},{"t":"h","text":"4) Liên kết một-nhiều"},{"t":"text","text":"Kiểu liên kết phổ biến nhất là **một-nhiều**. \"Một\" bản ghi ở bảng cha ứng với \"nhiều\" bản ghi ở bảng con. Ví dụ: **một** lớp có **nhiều** học sinh; **một** học sinh có **nhiều** lượt mượn sách.\n\nBên phía \"một\" là bảng chứa **khoá chính** (bảng LOP có `MaLop`). Bên phía \"nhiều\" là bảng chứa **khoá ngoài** trỏ về (bảng HOCSINH có trường `MaLop` là khoá ngoài). Cứ hình dung mũi tên đi từ nhiều học sinh chụm về một lớp.\n\nKhi thiết lập liên kết trong **hệ quản trị cơ sở dữ liệu**, em vào phần quản lí quan hệ giữa các bảng, kéo trường khoá chính của bảng cha nối tới trường khoá ngoài tương ứng của bảng con. Phần mềm sẽ vẽ một đường nối và ghi nhớ ràng buộc đó."},{"t":"bang","text":"Minh hoạ hai bảng LOP và HOCSINH liên kết qua trường `MaLop`. Bảng LOP có khoá chính là `MaLop`; bảng HOCSINH có khoá chính riêng `MaHS` và khoá ngoài `MaLop` trỏ sang bảng LOP.\n\n**Bảng LOP (phía một)**","head":["MaLop","TenLop"],"rows":[["L01","11A1"],["L02","11A2"]]},{"t":"bang","text":"**Bảng HOCSINH (phía nhiều)**","head":["MaHS","HoTen","MaLop"],"rows":[["HS01","Le Van Minh","L01"],["HS02","Tran Thu Ha","L01"],["HS03","Do Quoc Bao","L02"]]},{"t":"example","output":"Hai bạn HS01 và HS02 cùng có MaLop = L01, nghĩa là cùng thuộc lớp 11A1. Chỉ cần đổi tên lớp L01 một lần ở bảng LOP là mọi học sinh của lớp đó đều hiểu đúng, không phải sửa lại từng dòng."},{"t":"note","text":"Bẫy hay gặp: nhầm rằng khoá ngoài cũng phải **duy nhất**. Không phải vậy. Khoá chính mới bắt buộc duy nhất; khoá ngoài thì được phép **lặp lại** vì nhiều bản ghi con cùng trỏ về một bản ghi cha (nhiều học sinh cùng một lớp). Ngoài ra, tên trường khoá ngoài không nhất thiết giống hệt tên khoá chính bên kia — điều quan trọng là **kiểu dữ liệu** và **ý nghĩa** phải khớp để giá trị đối chiếu được với nhau."}],"keypoints":["Tách dữ liệu thành nhiều bảng để tránh **trùng lặp** và giữ **nhất quán**: mỗi thông tin gốc ghi đúng một chỗ.","**Khoá ngoài** là trường ở bảng con **tham chiếu** tới **khoá chính** của bảng cha; giá trị của nó phải đã tồn tại bên bảng cha.","Liên kết **một-nhiều**: phía \"một\" giữ khoá chính, phía \"nhiều\" giữ khoá ngoài trỏ về.","Khoá chính phải **duy nhất**, còn khoá ngoài được phép **lặp lại** vì nhiều bản ghi con cùng trỏ về một bản ghi cha."],"quiz":["UB-mc-401","UB-mc-402","UB-mc-403","UB-mc-404","UB-mc-405","UB-tf-401","UB-tf-402","UB-tf-403","UD2-mc-013","UD2-mc-014","UD2-mc-015","UD2-mc-016","UD2-tf-007","UD2-tf-008"]},
    {"id":"U11-05","stage":23,"order":5,"topic":"C","grade":11,"minutes":11,"title":"Cập nhật dữ liệu: thêm, sửa, xoá bản ghi","intro":"Một cơ sở dữ liệu chỉ hữu ích khi nó **luôn đúng với thực tế**. Bài này hướng dẫn bạn ba việc làm hằng ngày với dữ liệu: **thêm** bản ghi mới, **sửa** giá trị đã nhập sai, và **xoá** bản ghi không còn dùng — tất cả bằng thao tác trực quan ngay trên phần mềm quản trị CSDL.","sections":[{"t":"story","text":"Câu lạc bộ Sách của lớp 11A giao cho Minh quản lí việc mượn — trả sách. Minh đã tạo một bảng ghi lại tên bạn mượn, tên sách và ngày mượn. Mọi thứ chạy êm cho tới giờ ra chơi hôm nay.\n\nBạn Lan vừa tới mượn cuốn Dế Mèn — Minh cần ghi thêm một dòng mới. Bạn Hùng thì báo hôm qua Minh gõ nhầm ngày trả của cậu ấy, phải sửa lại. Còn cuốn sách Minh lỡ ghi hai lần cho cùng một bạn thì cần bỏ bớt một dòng đi.\n\nThêm một dòng, sửa một ô, bỏ một dòng — nghe rất đời thường, nhưng đó chính là toàn bộ công việc cập nhật một cơ sở dữ liệu. Làm đúng thì bảng dữ liệu luôn phản ánh trung thực tình hình mượn sách; làm ẩu, nhất là khi xoá, thì mất dữ liệu là mất luôn."},{"t":"h","text":"1) Ba thao tác cập nhật: thêm, sửa, xoá"},{"t":"text","text":"Sau khi bảng đã được thiết kế xong với các trường và khoá chính, phần lớn thời gian bạn không đụng tới cấu trúc nữa mà chỉ **làm việc với dữ liệu bên trong**. Ba việc thường xuyên nhất là: **thêm** một bản ghi (một dòng mới), **sửa** giá trị ở một hoặc vài ô, và **xoá** một bản ghi không còn cần.\n\nTrên phần mềm quản trị CSDL, bảng dữ liệu hiện ra giống một bảng tính: mỗi **dòng** là một **bản ghi**, mỗi **cột** là một **trường**. Bạn thao tác trực tiếp bằng chuột và bàn phím — nhấp vào ô để gõ, nhấn nút để thêm hoặc xoá dòng. Đây là điểm khác với cách viết câu lệnh: ở đây bạn **nhìn thấy ngay** kết quả từng thay đổi."},{"t":"h","text":"2) Thêm một bản ghi mới"},{"t":"text","text":"Để thêm bạn Lan vào bảng mượn sách, Minh đưa con trỏ xuống **dòng trống cuối bảng** (thường có dấu `*` ở đầu dòng để báo đây là dòng nhập mới), rồi lần lượt gõ giá trị cho từng trường: tên bạn mượn, tên sách, ngày mượn. Khi chuyển sang bản ghi khác hoặc nhấn lưu, dòng vừa nhập được **ghi vào bảng** và một dòng trống mới lại xuất hiện.\n\nCó hai điều phần mềm tự kiểm khi bạn thêm. Thứ nhất, **khoá chính** phải khác mọi bản ghi đã có — nếu mã mượn `M007` đã tồn tại, phần mềm sẽ báo lỗi và không cho lưu. Thứ hai, **kiểu dữ liệu** phải khớp — gõ chữ vào trường ngày sẽ bị từ chối. Nhờ vậy, ngay từ lúc nhập, dữ liệu sai kiểu hoặc trùng khoá đã bị chặn lại."},{"t":"h","text":"3) Sửa giá trị trong một ô"},{"t":"text","text":"Sửa còn đơn giản hơn thêm. Minh **nhấp đúp vào ô** chứa ngày trả của bạn Hùng, xoá giá trị cũ, gõ giá trị đúng rồi chuyển sang ô khác — thay đổi được lưu ngay. Bạn chỉ động vào đúng ô cần sửa, các ô còn lại của bản ghi giữ nguyên.\n\nLưu ý quan trọng: khi sửa một ô, bạn đang thay đổi **một bản ghi cụ thể**. Nếu vô tình sửa nhầm ô của bạn khác, dữ liệu của bạn đó sẽ sai mà không có cảnh báo, vì về mặt kiểu dữ liệu giá trị mới vẫn hợp lệ. Vì thế trước khi sửa, hãy chắc chắn con trỏ đang ở đúng dòng — nhìn cột khoá chính hoặc cột tên để xác nhận."},{"t":"h","text":"4) Nhập liệu bằng biểu mẫu cho đỡ nhầm"},{"t":"text","text":"Nhập thẳng trên bảng nhanh nhưng dễ lạc dòng khi bảng có nhiều cột: đang gõ ở cột thứ tám, ngẩng lên đã không rõ mình đang ở bản ghi nào. Để khắc phục, phần mềm cho tạo **biểu mẫu** (thường gọi là `form`) — một màn hình chỉ hiển thị **một bản ghi mỗi lần**, mỗi trường là một ô nhập có nhãn rõ ràng.\n\nVới biểu mẫu, người nhập điền theo từng ô có tên như Họ tên, Tên sách, Ngày mượn, rồi bấm nút để lưu và chuyển sang bản ghi tiếp theo. Cách này đặc biệt hợp với người không quen bảng dữ liệu: giao diện gọn, khó gõ nhầm sang trường khác, và có thể đặt sẵn giá trị mặc định. Dù nhập qua biểu mẫu, dữ liệu vẫn được ghi vào **cùng một bảng** như khi nhập thẳng — biểu mẫu chỉ là lớp giao diện thân thiện ở phía trước."},{"t":"h","text":"5) Tìm và lọc bản ghi trước khi sửa hay xoá"},{"t":"list","text":"Khi bảng đã dài hàng trăm dòng, cuộn tay để tìm đúng bản ghi vừa lâu vừa dễ nhầm. Phần mềm cung cấp các công cụ giúp bạn khoanh vùng nhanh:","items":["Tìm kiếm: gõ một từ khoá (ví dụ tên `Hùng`) để phần mềm nhảy tới ô chứa giá trị đó.","Lọc theo điều kiện: chỉ hiện những bản ghi thoả một tiêu chí, ví dụ chỉ các sách mượn trong tháng này.","Sắp xếp: xếp bảng theo ngày mượn tăng dần để dễ nhìn ra bản ghi cần xử lí.","Sau khi lọc còn ít dòng, việc chọn đúng bản ghi để sửa hoặc xoá trở nên an toàn hơn hẳn."]},{"t":"note","text":"Xoá là thao tác **nguy hiểm nhất**: khi bạn chọn một bản ghi và nhấn xoá, dòng đó biến mất và thường **không có nút hoàn tác** như trong soạn thảo văn bản. Xoá nhầm một bản ghi mượn sách là mất luôn thông tin ai đang giữ cuốn nào. Nguyên tắc an toàn: **sao lưu trước khi xoá**, chỉ xoá sau khi đã lọc và nhìn kỹ đúng dòng, và cân nhắc thay việc xoá bằng cách đánh dấu bản ghi là đã trả để vẫn giữ được lịch sử."}],"keypoints":["Ba thao tác cập nhật cơ bản là **thêm** bản ghi, **sửa** giá trị ô và **xoá** bản ghi — làm trực quan ngay trên bảng.","Khi thêm, phần mềm tự kiểm **khoá chính không trùng** và **kiểu dữ liệu khớp** trước khi lưu.","**Biểu mẫu** (`form`) hiển thị một bản ghi mỗi lần, giúp nhập liệu gọn và ít nhầm; dữ liệu vẫn ghi vào cùng bảng.","**Xoá là mất** và thường không hoàn tác được — hãy **lọc đúng dòng và sao lưu trước** khi xoá."],"quiz":["UB-mc-501","UB-mc-502","UB-mc-503","UB-mc-504","UB-mc-505","UB-tf-501","UB-tf-502","UB-tf-503","UD2-mc-017","UD2-mc-018","UD2-mc-019","UD2-mc-020","UD2-tf-009","UD2-tf-010"]},
    {"id":"U11-06","stage":23,"order":6,"topic":"C","grade":11,"minutes":12,"title":"Ràng buộc toàn vẹn và dữ liệu tham chiếu","intro":"Khi nhiều bảng nối với nhau qua khoá ngoài, một thao tác cập nhật bất cẩn có thể để lại **dữ liệu mồ côi**. Bài này bạn học cách để phần mềm tự canh giữ tính hợp lệ của dữ liệu qua các **ràng buộc toàn vẹn**.","sections":[{"t":"story","text":"Lớp 11A5 lập một sổ điểm danh câu lạc bộ bằng máy tính. Bạn Minh nhập danh sách thành viên vào một bảng, mỗi thành viên có một mã riêng. Bảng thứ hai ghi từng buổi sinh hoạt: buổi nào, thành viên nào có mặt, chỉ chép lại mã thành viên cho gọn.\n\nMột hôm, Minh thấy bạn Hùng đã nghỉ hẳn câu lạc bộ nên xoá luôn Hùng khỏi bảng thành viên. Vài tuần sau, khi tổng kết chuyên cần, cả nhóm hoảng hồn: bảng điểm danh vẫn còn hàng chục dòng ghi mã của Hùng, nhưng tra sang bảng thành viên thì chẳng còn ai mang mã đó. Những dòng ấy trỏ tới một người không còn tồn tại.\n\nCó bạn lại lỡ tay nhập hai thành viên trùng y hệt một mã. Đến lúc cộng điểm chuyên cần, máy không biết dòng điểm danh thuộc về ai trong hai người. Cả sổ điểm danh vừa lập đã rối tung chỉ vì vài thao tác tưởng như vô hại."},{"t":"h","text":"1) Ràng buộc toàn vẹn là gì"},{"t":"text","text":"Câu chuyện trên cho thấy: dữ liệu không chỉ cần \"nhập được\" mà còn phải \"hợp lệ\" thì mới dùng được. **Ràng buộc toàn vẹn** là những quy tắc mà bạn khai báo sẵn trong cấu trúc bảng, để **hệ quản trị CSDL** tự động kiểm tra mỗi khi có ai đó thêm, sửa hay xoá dữ liệu. Nếu thao tác vi phạm quy tắc, phần mềm sẽ từ chối và báo lỗi, thay vì lặng lẽ để dữ liệu hỏng.\n\nĐiểm hay là các quy tắc này gắn vào chính bảng, không phụ thuộc người nhập nhớ hay quên. Dù ai mở CSDL, dù nhập bằng biểu mẫu hay bằng lệnh, phần mềm đều canh giữ như nhau. Nhờ đó dữ liệu luôn ở trạng thái đáng tin, không cần ai ngồi dò lại từng dòng."},{"t":"list","text":"Vài loại ràng buộc thường gặp khi thiết kế bảng:","items":["Khoá chính không được trùng và không được để trống, nhờ đó mỗi bản ghi luôn phân biệt được với nhau.","Ràng buộc kiểu dữ liệu: trường ngày sinh chỉ nhận ngày hợp lệ, trường điểm chỉ nhận số.","Ràng buộc miền giá trị: điểm phải nằm trong khoảng 0 đến 10, giới tính chỉ nhận vài giá trị cho phép.","Ràng buộc bắt buộc nhập: một số trường quan trọng như họ tên không được để trống.","Ràng buộc tham chiếu: khoá ngoài phải trỏ tới một bản ghi có thật ở bảng kia."]},{"t":"h","text":"2) Toàn vẹn tham chiếu"},{"t":"text","text":"Trong nhóm trên, quan trọng nhất với các bảng có liên kết là **toàn vẹn tham chiếu**. Quy tắc rất gọn: mỗi giá trị **khoá ngoài** ở bảng con phải khớp với một **khoá chính** đang tồn tại ở bảng cha. Nói cách khác, không được có bản ghi nào trỏ tới một bản ghi không có thật.\n\nQuay lại sổ điểm danh: bảng buổi sinh hoạt là bảng con, trường mã thành viên trong đó là khoá ngoài, còn bảng thành viên là bảng cha. Nếu bật ràng buộc toàn vẹn tham chiếu, phần mềm sẽ không cho nhập một dòng điểm danh mang mã thành viên chưa hề có trong bảng cha. Dòng \"mồ côi\" như của bạn Hùng sẽ bị chặn ngay từ đầu."},{"t":"bang","text":"Hình dung hai bảng nhỏ. Bảng cha THANHVIEN có khoá chính là MaTV; bảng con DIEMDANH có khoá ngoài cũng là MaTV, trỏ về bảng cha:\n\n**THANHVIEN (cha)**","head":["MaTV","HoTen"],"rows":[["TV01","An"],["TV02","Binh"]]},{"t":"bang","text":"**DIEMDANH (con)**","head":["Buoi","MaTV",""],"rows":[["B1","TV01","hop le (TV01 co that)"],["B1","TV02","hop le"],["B1","TV09","VI PHAM (khong co TV09)"]]},{"t":"example","output":"Khi ràng buộc tham chiếu bật, dòng cuối bị từ chối vì MaTV = TV09 không tồn tại ở bảng cha THANHVIEN. Phần mềm báo lỗi và không lưu dòng đó."},{"t":"h","text":"3) Khi xoá hoặc sửa bản ghi đang được tham chiếu"},{"t":"text","text":"Vấn đề khó hơn nảy sinh khi bạn muốn xoá hoặc sửa một bản ghi ở **bảng cha** mà nó đang được bảng con trỏ tới. Xoá thành viên TV01 trong khi bảng điểm danh còn nhiều dòng mang mã TV01 sẽ tạo ra đúng cảnh \"mồ côi\" như câu chuyện đầu bài. Vì vậy phần mềm buộc bạn chọn cách xử lí trước.\n\nThường có ba hướng. Một là **hạn chế**: phần mềm từ chối xoá bản ghi cha chừng nào còn bản ghi con trỏ tới nó, buộc bạn xử lí bảng con trước. Hai là **xoá lan truyền**: khi xoá bản ghi cha, mọi bản ghi con liên quan cũng bị xoá theo cho sạch. Ba là **đặt về rỗng**: giữ lại bản ghi con nhưng gán khoá ngoài của chúng về giá trị trống, coi như tạm chưa gắn với ai. Sửa giá trị khoá chính ở bảng cha cũng theo nguyên tắc tương tự."},{"t":"note","text":"Đừng chọn **xoá lan truyền** một cách tùy tiện. Nó tiện vì gọn tay, nhưng chỉ cần xoá nhầm một bản ghi cha là kéo theo hàng loạt bản ghi con biến mất, rất khó lấy lại. Với dữ liệu quan trọng như điểm hay lịch sử giao dịch, cách **hạn chế** thường an toàn hơn vì buộc bạn dừng lại suy nghĩ."},{"t":"h","text":"4) Vì sao ràng buộc giúp tránh dữ liệu rác"},{"t":"text","text":"**Dữ liệu rác** là những giá trị vô nghĩa, trùng lặp hoặc trỏ tới đâu không rõ, khiến báo cáo sai và không ai dám tin vào CSDL nữa. Nếu chỉ trông vào việc người nhập cẩn thận thì sớm muộn cũng có sai sót, nhất là khi nhiều người cùng dùng chung một CSDL trong thời gian dài.\n\nRàng buộc toàn vẹn biến các quy tắc đúng đắn thành một tấm lưới tự động chặn sai sót ngay tại thời điểm nhập, thay vì để lỗi tích tụ rồi mới đi dò. Nhờ đó khoá chính luôn duy nhất, khoá ngoài luôn có nơi trỏ tới, các trường luôn đúng kiểu và đúng miền giá trị. Bỏ chút công khai báo ràng buộc lúc thiết kế bảng sẽ tiết kiệm rất nhiều công sửa dữ liệu về sau."}],"keypoints":["**Ràng buộc toàn vẹn** là quy tắc khai báo trong bảng để **hệ QTCSDL** tự kiểm tra mỗi khi thêm, sửa, xoá dữ liệu.","**Toàn vẹn tham chiếu**: mọi **khoá ngoài** ở bảng con phải trỏ tới một **khoá chính** có thật ở bảng cha, không được có bản ghi mồ côi.","Xoá hoặc sửa bản ghi cha đang được tham chiếu phải theo một cách xử lí: **hạn chế**, **xoá lan truyền** hoặc **đặt khoá ngoài về rỗng**.","Ràng buộc chặn sai sót ngay lúc nhập, giúp CSDL không tích tụ **dữ liệu rác** và báo cáo luôn đáng tin."],"quiz":["UB-mc-601","UB-mc-602","UB-mc-603","UB-mc-604","UB-mc-605","UB-tf-601","UB-tf-602","UB-tf-603","UD2-mc-021","UD2-mc-022","UD2-mc-023","UD2-mc-024","UD2-tf-011","UD2-tf-012"]},
    {"id":"U11-07","stage":23,"order":7,"topic":"C","grade":11,"minutes":12,"title":"Truy vấn dữ liệu qua liên kết nhiều bảng","intro":"Khi cần trả lời một câu hỏi quản lí như **liệt kê học sinh kèm tên lớp**, dữ liệu thường nằm rải ở nhiều bảng. Bài này hướng dẫn dùng công cụ **truy vấn trực quan** của hệ QTCSDL để nối bảng, chọn trường, đặt điều kiện và sắp xếp mà không phải gõ câu lệnh.","sections":[{"t":"story","text":"Cuối học kì, cô Lan phụ trách nề nếp cần một danh sách gọn gàng: mỗi học sinh kèm theo tên lớp mà em đang học. Trong sổ điện tử của trường, tên học sinh nằm ở một bảng, còn tên lớp lại nằm ở một bảng khác. Nếu chép tay ghép lại thì vừa lâu vừa dễ sai.\n\nHôm sau, thầy phụ trách phòng máy chỉ cho cô một cách nhanh hơn nhiều: chỉ cần kéo hai bảng vào một cửa sổ, nối chúng lại bằng một sợi dây, chọn vài cột cần xem rồi bấm chạy. Trong vài giây, danh sách hiện ra đầy đủ tên học sinh và tên lớp tương ứng.\n\nCô Lan ngạc nhiên: máy đã tự động khớp đúng từng em với đúng lớp của em. Điều gì đã giúp phần mềm ghép chính xác như vậy, và làm thế nào để tự tạo được một bản danh sách như thế? Đó chính là nội dung của bài hôm nay."},{"t":"h","text":"1) Truy vấn là gì và dùng để làm gì"},{"t":"text","text":"**Truy vấn** (query) là một yêu cầu ta đặt ra cho hệ QTCSDL để **lấy đúng dữ liệu mình cần** từ một hoặc nhiều bảng. Thay vì mở từng bảng và tự dò tìm, ta mô tả yêu cầu một lần, phần mềm sẽ quét dữ liệu và trả về bảng kết quả.\n\nMột điểm quan trọng: truy vấn **không sao chép** dữ liệu ra chỗ mới. Nó chỉ là một \"ống kính\" nhìn vào dữ liệu gốc. Khi bảng gốc thay đổi, chạy lại truy vấn sẽ cho kết quả mới cập nhật. Nhờ vậy ta có thể lưu truy vấn lại và dùng đi dùng lại nhiều lần."},{"t":"h","text":"2) Vì sao cần nối nhiều bảng"},{"t":"text","text":"Một CSDL tốt tách dữ liệu thành nhiều bảng để tránh lặp lại. Ví dụ bảng `HOC_SINH` lưu họ tên, ngày sinh và **mã lớp**; còn tên lớp đầy đủ như \"11A1\" được lưu riêng ở bảng `LOP`. Mỗi học sinh chỉ ghi mã lớp, khỏi phải chép lại tên lớp dài dòng.\n\nKhi muốn xem tên lớp đi kèm tên học sinh, ta phải **nối (liên kết)** hai bảng lại. Phần mềm dựa vào cặp trường chung — **khoá ngoài** `mã lớp` ở bảng `HOC_SINH` khớp với **khoá chính** `mã lớp` ở bảng `LOP` — để ghép đúng từng dòng với nhau. Đây chính là \"sợi dây\" nối mà cô Lan nhìn thấy."},{"t":"h","text":"3) Tạo truy vấn trực quan trên phần mềm"},{"t":"list","text":"Trong hệ QTCSDL, cửa sổ thiết kế truy vấn cho phép làm mọi thứ bằng thao tác kéo thả, không cần gõ lệnh. Quy trình thường gồm:","items":["Thêm các bảng cần dùng vào vùng thiết kế (ví dụ `HOC_SINH` và `LOP`).","Kéo trường khoá ngoài của bảng này thả lên trường khoá chính của bảng kia để tạo đường nối.","Chọn những trường muốn hiển thị bằng cách kéo chúng xuống lưới, hoặc bỏ tích cột không cần.","Nhập điều kiện lọc vào ô tiêu chí để chỉ lấy những dòng thoả yêu cầu.","Chọn sắp xếp tăng hoặc giảm cho trường cần thứ tự.","Bấm nút chạy để xem bảng kết quả."]},{"t":"h","text":"4) Chọn trường, lọc điều kiện và sắp xếp"},{"t":"text","text":"**Chọn trường hiển thị** giúp kết quả gọn, chỉ hiện đúng cột cần thiết như họ tên và tên lớp, ẩn đi những cột không liên quan như số điện thoại phụ huynh. **Điều kiện lọc** đặt ở ô tiêu chí quyết định dòng nào được lấy: ví dụ chỉ lấy học sinh của khối 11, hay chỉ lấy các em sinh năm 2008.\n\n**Sắp xếp** quyết định thứ tự các dòng trong kết quả, chẳng hạn xếp theo tên lớp rồi theo họ tên để danh sách dễ đọc. Ba việc này độc lập nhau: ta có thể vừa nối bảng, vừa lọc, vừa sắp xếp trong cùng một truy vấn để có ngay danh sách đúng ý."},{"t":"example","text":"Truy vấn liệt kê học sinh khối 11 kèm tên lớp, sắp xếp theo tên lớp. Mô tả thiết kế và kết quả:","code":"Bảng dùng: HOC_SINH, LOP\nĐường nối: HOC_SINH.ma_lop  =  LOP.ma_lop\nTrường hiển thị: HOC_SINH.ho_ten , LOP.ten_lop\nĐiều kiện (ô tiêu chí ten_lop): bắt đầu bằng \"11\"\nSắp xếp: ten_lop tăng dần"},{"t":"bang","head":["ho_ten","ten_lop"],"rows":[["Tran Van An","11A1"],["Le Thi Binh","11A1"],["Pham Gia Huy","11A2"],["Nguyen Mai","11A3"]]},{"t":"note","text":"Bẫy thường gặp: nếu **quên tạo đường nối** giữa hai bảng, phần mềm sẽ ghép mỗi dòng bảng này với mọi dòng bảng kia, cho ra kết quả phình to và sai lệch. Luôn kiểm tra đã có \"sợi dây\" nối đúng cặp khoá trước khi chạy. Ngoài ra, hãy nhớ điều kiện lọc phải viết đúng trên trường mình định lọc, đặt nhầm cột sẽ ra kết quả không như mong đợi."}],"keypoints":["**Truy vấn** là yêu cầu lấy đúng dữ liệu cần từ một hoặc nhiều bảng; nó nhìn vào dữ liệu gốc, không sao chép.","Nối bảng dựa trên **cặp khoá chung**: khoá ngoài của bảng này khớp khoá chính của bảng kia để ghép đúng dòng.","Trong công cụ thiết kế trực quan, ta **kéo thả** để thêm bảng, tạo đường nối, chọn trường, lọc và sắp xếp mà không cần gõ lệnh.","Quên **đường nối** sẽ ghép chéo sai lệch; luôn kiểm tra liên kết và ô điều kiện trước khi chạy."],"quiz":["UB-mc-701","UB-mc-702","UB-mc-703","UB-mc-704","UB-mc-705","UB-tf-701","UB-tf-702","UB-tf-703","UD2-mc-025","UD2-mc-026","UD2-mc-027","UD2-mc-028","UD2-tf-013","UD2-tf-014"]},
    {"id":"U11-08","stage":23,"order":8,"topic":"C","grade":11,"minutes":12,"title":"Sao lưu và phục hồi dữ liệu","intro":"Một tệp cơ sở dữ liệu tốt đến đâu cũng có thể hỏng, mất hoặc bị xoá nhầm chỉ trong một giây. Bài này hướng dẫn em cách **sao lưu** định kỳ và **phục hồi** dữ liệu khi có sự cố, để công sức nhập liệu không tan biến.","sections":[{"t":"story","text":"Lớp em xây một cơ sở dữ liệu quản lí thư viện lớp: mấy trăm đầu sách, danh sách bạn mượn, ngày trả. Suốt hai tháng cả nhóm thay nhau nhập liệu, ai cũng tự hào vì tra cứu nhanh gọn.\n\nMột chiều, bạn phụ trách máy vô tình chọn nhầm và xoá sạch bảng danh sách mượn, rồi bấm lưu luôn. Cả nhóm ngồi thừ ra: không có cách nào bấm hoàn tác được nữa vì máy đã tắt và mở lại. Bao nhiêu buổi nhập liệu coi như mất trắng.\n\nMay thay, tuần trước cô giáo bắt cả nhóm chép tệp cơ sở dữ liệu ra một thư mục riêng và một chiếc USB. Nhờ bản chép đó, các bạn khôi phục lại được gần hết dữ liệu chỉ trong vài phút. Từ hôm ấy, không ai dám coi thường việc giữ một bản dự phòng."},{"t":"h","text":"1) Vì sao phải sao lưu định kỳ"},{"t":"text","text":"**Sao lưu** (backup) là tạo thêm một hay nhiều **bản sao** của tệp cơ sở dữ liệu, cất ở nơi an toàn để dùng lại khi bản chính gặp sự cố. Dữ liệu có thể biến mất vì rất nhiều lí do: ổ cứng hỏng, máy bị mất hoặc rơi vỡ, virus mã hoá tệp, hoặc đơn giản là ai đó thao tác nhầm rồi lưu đè lên.\n\nĐiểm mấu chốt là những sự cố này thường đến bất ngờ và **không thể hoàn tác**. Khi tệp gốc đã hỏng, không có nút nào lấy lại dữ liệu cho em. Thứ duy nhất cứu được em là một bản sao lưu đã tạo từ trước. Vì thế, sao lưu phải làm **định kỳ và đều đặn**, chứ không phải đợi đến lúc mất mới nghĩ tới."},{"t":"list","text":"Những rủi ro thường gặp khiến em cần bản sao lưu:","items":["Hỏng phần cứng: ổ cứng, thẻ nhớ hay USB đột ngột không đọc được","Thao tác nhầm: xoá bảng, xoá bản ghi hoặc sửa sai rồi lưu đè","Phần mềm độc hại làm hỏng hoặc khoá tệp cơ sở dữ liệu","Mất máy, cháy nổ, ngập nước hay sự cố ngoài ý muốn"]},{"t":"h","text":"2) Cách tạo một bản sao lưu"},{"t":"text","text":"Ở mức phổ thông, cách sao lưu đơn giản nhất là **đóng tệp cơ sở dữ liệu lại**, rồi **chép nguyên tệp** đó sang một vị trí khác. Phải đóng tệp trước vì khi đang mở, một phần dữ liệu còn nằm trong bộ nhớ chưa ghi hết xuống ổ đĩa; chép lúc đó dễ được bản dở dang, hỏng.\n\nMẹo quan trọng là **đặt tên bản sao theo ngày** để về sau biết bản nào mới, bản nào cũ. Chẳng hạn tệp gốc là `thuvien.db`, thì các bản sao có thể là `thuvien_2026-07-10.db`, `thuvien_2026-07-17.db`. Nhìn tên là biết ngay bản đó chụp lại dữ liệu ở thời điểm nào, khi cần phục hồi sẽ chọn đúng bản mong muốn."},{"t":"example","text":"Minh hoạ quy trình tạo một bản sao lưu theo ngày cho tệp thư viện lớp:","code":"1. Đóng hẳn phần mềm hệ QTCSDL đang mở tệp\n2. Vào thư mục chứa tệp gốc: thuvien.db\n3. Sao chép tệp (Ctrl+C) rồi dán vào thư mục SaoLuu (Ctrl+V)\n4. Đổi tên bản vừa dán thành: thuvien_2026-07-24.db\n5. Chép thêm một bản ra USB để cất riêng","output":"Thư mục SaoLuu có: thuvien_2026-07-10.db, thuvien_2026-07-17.db, thuvien_2026-07-24.db — mỗi tuần một bản, nhìn tên biết ngay ngày tạo."},{"t":"h","text":"3) Phục hồi dữ liệu khi có sự cố"},{"t":"text","text":"**Phục hồi** (restore) là dùng một bản sao lưu để thay cho tệp gốc đã hỏng hoặc mất. Về cơ bản, em chọn bản sao lưu **gần nhất còn tốt**, chép nó về thư mục làm việc và (nếu cần) đổi lại tên đúng như tệp gốc, rồi mở lên kiểm tra.\n\nCần nhớ rằng phục hồi chỉ đưa dữ liệu về đúng thời điểm của bản sao lưu, chứ không lấy lại được phần nhập thêm sau đó. Nếu bản sao lưu gần nhất là hôm thứ Hai, mà đến thứ Sáu mới gặp sự cố, thì dữ liệu nhập từ thứ Ba đến thứ Sáu vẫn mất. Đây chính là lí do phải sao lưu **thường xuyên**: khoảng cách giữa hai lần sao lưu càng ngắn thì phần dữ liệu có nguy cơ mất càng ít."},{"t":"note","text":"Bẫy thường gặp: chép bản sao lưu đè thẳng lên tệp gốc mà chưa kiểm tra. Nếu bản sao lưu ấy lỗi, em mất luôn cả bản còn dùng được. Cách an toàn là mở bản sao lưu ra xem dữ liệu có đủ không rồi mới thay thế, và nên giữ lại tệp gốc hỏng ở một chỗ riêng cho đến khi chắc chắn."},{"t":"h","text":"4) Nguyên tắc 3-2-1 cho người mới"},{"t":"text","text":"Để nhớ dễ, giới chuyên môn hay dùng nguyên tắc **3-2-1**: giữ **3** bản dữ liệu (1 bản đang dùng và 2 bản sao lưu), đặt trên **2** loại phương tiện khác nhau (ví dụ ổ máy tính và USB, hoặc thẻ nhớ và dịch vụ lưu trữ trên mạng), trong đó có **1** bản để ở **nơi khác** với máy tính.\n\nÝ tưởng đằng sau rất thực tế: nếu tất cả bản sao đều nằm cùng một ổ, cùng một chỗ, thì một sự cố (ổ hỏng, mất cắp, cháy nổ) có thể cuốn đi hết. Có một bản ở nơi khác giúp em vẫn còn dữ liệu ngay cả trong tình huống xấu nhất. Vài thói quen tốt nên tập ngay: chọn một lịch sao lưu cố định, luôn đặt tên bản sao kèm ngày, và thỉnh thoảng thử mở một bản sao lưu để chắc chắn nó còn đọc được."}],"keypoints":["**Sao lưu** là tạo bản sao của tệp CSDL để dùng lại khi bản chính gặp sự cố; phải làm **định kỳ** vì sự cố không thể hoàn tác","Tạo bản sao lưu bằng cách **đóng tệp** rồi chép ra vị trí khác, **đặt tên theo ngày** để biết bản nào mới","**Phục hồi** là dùng bản sao lưu gần nhất còn tốt thay cho tệp hỏng; chỉ lấy lại dữ liệu tới thời điểm của bản sao đó","Nguyên tắc **3-2-1**: 3 bản dữ liệu, 2 loại phương tiện, 1 bản để ở nơi khác"],"quiz":["UB-mc-801","UB-mc-802","UB-mc-803","UB-mc-804","UB-mc-805","UB-tf-801","UB-tf-802","UB-tf-803","UD2-mc-029","UD2-mc-030","UD2-mc-031","UD2-mc-032","UD2-tf-015","UD2-tf-016"]},
    {"id":"U11-09","stage":23,"order":9,"topic":"E","grade":11,"minutes":12,"title":"Làm quen phần mềm chỉnh sửa ảnh: lớp và vùng chọn","intro":"Bài này giúp em mở một **phần mềm chỉnh sửa ảnh** lần đầu mà không bị choáng: hiểu ảnh số được tạo từ gì, làm quen giao diện, và nắm hai ý tưởng quan trọng nhất là **lớp** (`layer`) và **vùng chọn** (`selection`).","sections":[{"t":"story","text":"Lớp 11A của Minh chuẩn bị làm tấm áp phích mừng ngày Nhà giáo Việt Nam. Minh chụp được tấm ảnh cả lớp đứng trước cổng trường rất đẹp, nhưng bạn muốn thêm một dòng chữ chúc mừng ở phía trên và dán thêm một bông hoa nhỏ vào góc ảnh.\n\nMinh mở một phần mềm chỉnh sửa ảnh trên máy tính của phòng tin học. Bạn định gõ chữ thẳng lên ảnh, rồi lỡ tay tô nhầm màu che mất khuôn mặt một người bạn. Khi muốn quay lại ảnh ban đầu thì đã quá muộn: chữ, hoa và ảnh gốc dính chặt vào nhau như vẽ bằng bút lông lên một tờ giấy.\n\nCô giáo đi qua, mỉm cười và bảo: 'Em thử hình dung mỗi thứ nằm trên một tấm kính trong suốt riêng, xếp chồng lên nhau. Chữ một tấm, bông hoa một tấm, ảnh gốc một tấm. Muốn sửa tấm nào chỉ động vào tấm đó thôi.' Ý tưởng nghe lạ mà hoá ra chính là cách mọi phần mềm chỉnh sửa ảnh làm việc."},{"t":"h","text":"1) Ảnh số được tạo từ gì"},{"t":"text","text":"Một tấm ảnh số thực chất là một lưới chữ nhật gồm rất nhiều ô vuông tí hon, mỗi ô mang một màu. Mỗi ô đó gọi là một **điểm ảnh** (`pixel`). Khi các điểm ảnh xếp sát nhau và đủ nhiều, mắt ta nhìn thấy một hình liền mạch chứ không thấy từng ô.\n\nSố điểm ảnh theo chiều ngang nhân chiều dọc cho biết **độ phân giải** của ảnh, ví dụ `1920 x 1080`. Ảnh càng nhiều điểm ảnh thì càng rõ nét và in được khổ lớn, nhưng tệp cũng nặng hơn. Đây là lí do khi phóng to một tấm ảnh nhỏ quá mức, em thấy hình bị 'vỡ' thành các ô vuông màu."},{"t":"h","text":"2) Lớp là gì"},{"t":"text","text":"**Lớp** (`layer`) là một tầng nội dung riêng, giống một tấm kính trong suốt đặt chồng lên ảnh. Mỗi lớp có thể chứa một thứ: ảnh gốc, một dòng chữ, một hình dán, một mảng màu. Các lớp xếp chồng theo thứ tự trên dưới, và khi nhìn từ trên xuống ta thấy chúng hoà lại thành một hình duy nhất.\n\nChỗ nào trên một lớp không có nội dung thì trong suốt, để lộ lớp bên dưới. Nhờ vậy dòng chữ chúc mừng của Minh có thể nằm 'lơ lửng' phía trên mà vẫn thấy ảnh cả lớp ở dưới. Muốn di chuyển, đổi màu hay xoá dòng chữ, Minh chỉ chọn lớp chữ rồi thao tác, còn ảnh gốc ở lớp khác không hề bị đụng tới."},{"t":"text","text":"Cách làm việc giữ nguyên ảnh gốc và chỉ thêm bớt ở các lớp khác gọi là chỉnh sửa **không phá huỷ**. Vì mọi thay đổi nằm trên các lớp riêng, em luôn có thể tạm ẩn một lớp để so sánh trước và sau, đổi thứ tự trên dưới, giảm độ mờ của một lớp, hoặc xoá hẳn một lớp mà ảnh nền vẫn nguyên vẹn.\n\nĐiều này ngược hẳn với việc gõ chữ và tô màu trực tiếp lên một lớp duy nhất như Minh làm lúc đầu: khi đó mọi thứ trộn vào nhau, muốn sửa một chi tiết thường phải làm lại từ đầu. Vì thế thói quen tốt là mỗi nội dung mới đặt trên một lớp mới, và đặt tên lớp cho dễ nhớ như `chu-chuc-mung` hay `bong-hoa`."},{"t":"h","text":"3) Vùng chọn để giới hạn thao tác"},{"t":"text","text":"**Vùng chọn** (`selection`) là phần ảnh em khoanh lại để nói với phần mềm: 'chỉ được tác động vào đây thôi'. Khi một vùng đang được chọn, mọi thao tác như tô màu, làm sáng, xoá hay sao chép chỉ ảnh hưởng trong ranh giới đó, phần còn lại được bảo vệ. Ranh giới vùng chọn thường hiện lên bằng đường nét đứt nhấp nháy nên hay được gọi vui là 'đàn kiến bò'.\n\nVí dụ Minh muốn làm sáng riêng khuôn mặt các bạn mà không đụng tới bầu trời, bạn chỉ cần khoanh vùng quanh nhóm người rồi mới chỉnh độ sáng. Nếu quên tạo vùng chọn, thao tác sẽ áp lên toàn bộ lớp. Khi làm xong, em bỏ chọn để thao tác tiếp theo được tự do trên cả lớp."},{"t":"h","text":"4) Giao diện chung của phần mềm chỉnh sửa ảnh"},{"t":"list","text":"Dù mỗi phần mềm chỉnh sửa ảnh có màu sắc giao diện khác nhau, chúng thường có chung mấy khu vực sau:","items":["Hộp công cụ: dãy biểu tượng để chọn công cụ như di chuyển, khoanh vùng chọn, cọ vẽ, gõ chữ","Vùng làm việc: khung lớn ở giữa hiển thị ảnh đang chỉnh, có thể phóng to thu nhỏ","Bảng lớp: liệt kê các lớp theo thứ tự trên dưới, cho ẩn/hiện, đổi tên, sắp xếp lại","Thanh tuỳ chọn: các thiết lập của công cụ đang dùng, ví dụ kích thước cọ hay màu chữ","Bảng màu: nơi chọn màu vẽ và màu nền cho thao tác"]},{"t":"example","text":"Hình dung bảng lớp cho tấm áp phích của Minh, đọc từ trên xuống chính là từ ngoài vào trong khi nhìn ảnh:","code":"[hiện] Lớp 3: chu-chuc-mung   (dòng chữ)\n[hiện] Lớp 2: bong-hoa         (hình dán góc)\n[hiện] Lớp 1: anh-ca-lop       (ảnh gốc, nền)","output":"Nhìn tấm áp phích thấy dòng chữ nằm trên cùng, rồi tới bông hoa, cuối cùng là ảnh cả lớp làm nền. Ẩn Lớp 3 thì chữ biến mất nhưng ảnh và hoa vẫn còn; kéo Lớp 2 lên trên Lớp 3 thì bông hoa sẽ che một phần chữ."},{"t":"note","text":"Bẫy thường gặp: đang chọn nhầm lớp nên tô màu 'không thấy đâu' vì thực ra nó rơi vào lớp khuất bên dưới. Trước mỗi thao tác hãy liếc bảng lớp xem lớp nào đang được chọn (thường sáng màu). Một bẫy khác là quên bỏ vùng chọn, khiến thao tác sau đó vô tình chỉ tác động trong vùng cũ."}],"keypoints":["Ảnh số là lưới các **điểm ảnh** (`pixel`); số điểm ảnh quyết định độ phân giải và độ nét","**Lớp** (`layer`) là tầng nội dung trong suốt xếp chồng; mỗi nội dung một lớp giúp sửa riêng từng phần","Làm việc trên lớp là chỉnh sửa **không phá huỷ**: ảnh gốc luôn được giữ nguyên, có thể ẩn/hiện, sắp xếp, xoá lớp","**Vùng chọn** (`selection`) giới hạn thao tác vào một phần ảnh; nhớ bỏ chọn sau khi làm xong"],"quiz":["UB-mc-901","UB-mc-902","UB-mc-903","UB-mc-904","UB-mc-905","UB-tf-901","UB-tf-902","UB-tf-903","UD2-mc-033","UD2-mc-034","UD2-mc-035","UD2-mc-036","UD2-tf-017","UD2-tf-018"]},
    {"id":"U11-10","stage":23,"order":10,"topic":"E","grade":11,"minutes":12,"title":"Tinh chỉnh màu sắc, độ sáng và tương phản","intro":"Một tấm ảnh chụp xong hiếm khi đẹp ngay: chỗ thì tối, chỗ lại **cháy sáng**, màu da nhìn tái hoặc ám vàng. Bài này giúp em dùng các công cụ chỉnh **độ sáng**, **độ tương phản**, **độ bão hoà** và biết đọc **biểu đồ histogram** để sửa ảnh cho tự nhiên mà không bị bệt.","sections":[{"t":"story","text":"Cuối buổi liên hoan chia tay lớp, Mai chụp được mấy chục tấm ảnh bằng điện thoại. Về nhà mở ra xem, bạn hơi thất vọng: tấm chụp trong hội trường thì tối om, khuôn mặt các bạn chìm hết vào bóng; tấm chụp ngoài sân lúc nắng gắt lại sáng loá, cái áo trắng trắng bệch không còn thấy nếp gấp.\n\nMai định xoá bớt, nhưng cô bạn ngồi cạnh bảo: \"Đừng vội, mấy tấm này cứu được đấy. Kéo cho nó sáng lên một chút, tăng độ tương phản, chỉnh lại màu cho tươi là nhìn khác ngay.\" Mai tò mò: chỉ vài thao tác kéo thanh trượt mà một tấm ảnh tối thui lại có thể trở nên rõ ràng, sống động ư? Hoá ra sửa ảnh không phải lúc nào cũng cần vẽ vời gì cả — nhiều khi chỉ là chỉnh lại ánh sáng và màu cho đúng."},{"t":"h","text":"1) Ba đại lượng cơ bản: sáng, tương phản, bão hoà"},{"t":"text","text":"Mọi phần mềm chỉnh sửa ảnh đều cho em ba nút chỉnh quen thuộc nhất. **Độ sáng** (brightness) làm cả tấm ảnh sáng lên hay tối đi đồng loạt: kéo tăng thì mọi điểm ảnh đều được cộng thêm ánh sáng, kéo giảm thì ngược lại. Đây là thứ em chỉnh đầu tiên khi ảnh chụp thiếu sáng như tấm trong hội trường của Mai.\n\n**Độ tương phản** (contrast) là mức chênh lệch giữa vùng sáng và vùng tối. Tăng tương phản kéo chỗ sáng sáng hơn và chỗ tối tối hơn, khiến ảnh trông rõ nét, \"có chiều sâu\". Giảm tương phản làm ảnh dịu, xám đều lại. **Độ bão hoà** (saturation) quyết định màu đậm hay nhạt: bão hoà cao thì màu rực rỡ, bằng 0 thì ảnh thành đen trắng. Ba thanh này thường đứng cạnh nhau và là bộ công cụ em sẽ dùng nhiều nhất."},{"t":"list","text":"Nhớ nhanh tác dụng của từng thanh trượt:","items":["Độ sáng: cả ảnh sáng lên hoặc tối đi cùng lúc.","Độ tương phản: nới rộng khoảng cách sáng - tối, ảnh rõ và có khối.","Độ bão hoà: màu rực rỡ hơn hay nhạt dần về xám.","Ba thứ này tác động lên toàn ảnh, không phải một vùng riêng."]},{"t":"h","text":"2) Cân bằng màu và chỉnh tông cho tự nhiên"},{"t":"text","text":"Nhiều tấm ảnh bị **ám màu**: chụp dưới đèn tuýp thì ám xanh, chụp dưới đèn vàng trong nhà thì ám vàng, khiến khuôn mặt trông không thật. Công cụ **cân bằng màu** (còn gọi là cân bằng trắng) giúp em kéo tông ảnh về đúng: nếu ảnh ám vàng, em thêm chút xanh lam để trung hoà; nếu ám xanh lạnh, em thêm chút vàng ấm.\n\nMục tiêu của chỉnh tông là làm ảnh **tự nhiên**, giống điều mắt em thấy lúc chụp, chứ không phải nhuộm ảnh thành màu lạ. Một mẹo đơn giản: tìm trong ảnh một vật vốn có màu trung tính — tờ giấy trắng, chiếc áo xám, bức tường sáng — rồi chỉnh sao cho vật đó trở lại đúng màu trắng hoặc xám. Khi vật trung tính đã đúng, cả tấm ảnh thường cũng đúng theo."},{"t":"h","text":"3) Đọc biểu đồ histogram"},{"t":"text","text":"Đa số phần mềm hiển thị một **biểu đồ histogram** — đồ thị cột cho biết trong ảnh có bao nhiêu điểm ảnh ở mỗi mức sáng. Trục ngang chạy từ **tối nhất bên trái** đến **sáng nhất bên phải**; cột càng cao nghĩa là càng nhiều điểm ảnh ở mức sáng đó. Nhìn hình dạng biểu đồ, em đoán được ngay ảnh đang bị gì.\n\nNếu cột dồn hết về bên trái, ảnh đang **thiếu sáng** (tối); dồn về bên phải là **thừa sáng**. Nếu cột dồn cụm hẹp ở giữa, ảnh **thiếu tương phản**, trông xám bệt. Một tấm ảnh có tông cân đối thường trải các cột tương đối đều khắp biểu đồ, không bị cụt hẳn ở hai đầu. Histogram không quyết định thay em, nhưng nó là chiếc \"đồng hồ đo\" khách quan, tránh việc em chỉ chỉnh theo cảm giác."},{"t":"example","text":"Đọc thử hai biểu đồ của cùng tấm ảnh sân trường của Mai, trước và sau khi chỉnh:","code":"Trước:  [########........................]  cột dồn hết bên trái\nSau:    [....####.####.####.####.####....]  trải đều hơn","output":"Ảnh 'Trước' cột dồn bên trái nên tối; sau khi tăng độ sáng và tương phản, các cột trải rộng ra hai phía, ảnh sáng rõ và có chiều sâu hơn."},{"t":"h","text":"4) Chỉnh có mức độ, tránh ảnh bệt và cháy sáng"},{"t":"text","text":"Điều quan trọng nhất khi tinh chỉnh là **vừa đủ**. Kéo thanh trượt lên hết cỡ luôn cho cảm giác \"ảnh đẹp hẳn ra\" trong vài giây đầu, nhưng thường phá hỏng chi tiết. Đẩy độ sáng quá tay khiến vùng sáng bị **cháy sáng** — trắng xoá, mất hết chi tiết, không cách nào lấy lại. Đẩy tương phản quá mức làm vùng tối **bệt** thành một mảng đen. Tăng bão hoà quá đà biến màu da thành đỏ cam trông giả tạo.\n\nCách làm khôn ngoan là chỉnh từng chút một, vừa kéo vừa nhìn ảnh và liếc histogram. Nếu thấy cột chạm sát mép phải và dựng đứng thành vạch, đó là dấu hiệu cháy sáng — hãy lùi lại. Nên **giữ lại ảnh gốc** và làm việc trên bản sao, để nếu chỉnh hỏng vẫn còn đường quay lại. Chỉnh ảnh giỏi không phải là kéo mạnh tay, mà là biết dừng đúng lúc."},{"t":"note","text":"Bẫy thường gặp: nhầm **độ sáng** với **độ tương phản**. Ảnh tối đều thì tăng độ sáng; còn ảnh nhìn xám, \"đục\", không rõ khối dù không tối thì cái thiếu là độ tương phản. Chỉnh nhầm loại sẽ càng làm ảnh xấu đi."}],"keypoints":["**Độ sáng** làm cả ảnh sáng/tối đồng loạt; **độ tương phản** nới rộng chênh lệch sáng - tối; **độ bão hoà** quyết định màu rực hay nhạt.","**Cân bằng màu** khử ám vàng/ám xanh, đưa tông ảnh về tự nhiên; mẹo là chỉnh theo một vật vốn trắng hoặc xám trung tính.","**Histogram** là đồ thị phân bố sáng - tối: dồn trái là thiếu sáng, dồn phải là thừa sáng, cụm hẹp giữa là thiếu tương phản.","Chỉnh **vừa đủ**, tránh **cháy sáng** và ảnh **bệt**; nên làm trên bản sao và giữ lại ảnh gốc."],"quiz":["UB-mc-1001","UB-mc-1002","UB-mc-1003","UB-mc-1004","UB-mc-1005","UB-tf-1001","UB-tf-1002","UB-tf-1003","UD2-mc-037","UD2-mc-038","UD2-mc-039","UD2-mc-040","UD2-tf-019","UD2-tf-020"]},
    {"id":"U11-11","stage":23,"order":11,"topic":"E","grade":11,"minutes":12,"title":"Công cụ chọn và tách nền","intro":"Muốn lấy riêng một người ra khỏi tấm ảnh đông người, hay đưa món hàng sang một phông nền sạch để rao bán, em cần biết cách **khoanh vùng chọn** đúng chủ thể rồi **tách nền**. Bài này giới thiệu các kiểu công cụ chọn — **chọn hình học**, **chọn theo màu**, **chọn tự do** — và cách **làm mềm mép** để ảnh ghép trông tự nhiên.","sections":[{"t":"story","text":"Lớp 11A chuẩn bị làm cuốn kỉ yếu cuối cấp. Nhóm của Nam nhận nhiệm vụ dựng trang \"cả lớp cùng khung trời mơ ước\": ghép ảnh từng bạn lên một phông nền bầu trời xanh có mây. Vấn đề là mỗi bạn lại gửi một tấm ảnh chụp ở một chỗ khác nhau — đứa đứng trước tường vàng, đứa ngồi ở quán trà sữa, đứa chụp giữa sân trường lộn xộn người qua lại.\n\nNam loay hoay mãi: làm sao \"bóc\" được đúng bạn ấy ra khỏi cái nền lộn xộn kia rồi dán sang bầu trời chung? Cắt bằng cách xoá từng chút thì vừa lâu vừa nham nhở, viền tóc cứ bị cụt hoặc dính một mảng nền cũ. Cô phụ trách câu lạc bộ tin học chỉ cho Nam: \"Việc này có công cụ riêng. Em không xoá, mà khoanh vùng chọn quanh bạn ấy trước, rồi tách phần được chọn ra. Nền cũ sẽ bị bỏ lại, chỉ còn người được mang sang nền mới.\" Nam mới hiểu: chìa khoá của ghép ảnh là biết chọn cho khéo."},{"t":"h","text":"1) Vùng chọn là gì và để làm gì"},{"t":"text","text":"Trong phần mềm chỉnh sửa ảnh, **vùng chọn** là phần ảnh mà em khoanh lại để mọi thao tác tiếp theo chỉ tác động lên đúng phần đó, chừa phần còn lại ra. Vùng chọn thường hiển thị bằng một đường viền nhấp nháy chạy quanh, dân trong nghề hay gọi vui là \"đàn kiến bò\". Khi đã có vùng chọn, em có thể sao chép, di chuyển, đổi màu hay xoá riêng phần bên trong mà không đụng tới phần bên ngoài.\n\nĐây chính là công cụ then chốt để **tách chủ thể khỏi nền**: em khoanh đúng người hoặc vật cần lấy, rồi tách phần được chọn ra khỏi phần nền. Vì mỗi tấm ảnh có hình dạng chủ thể khác nhau — khi thì khối hình vuông vắn, khi thì đường viền uốn lượn phức tạp — nên phần mềm cung cấp nhiều **kiểu công cụ chọn** để em chọn cách phù hợp nhất."},{"t":"h","text":"2) Chọn hình học: hình chữ nhật và hình ellip"},{"t":"text","text":"Nhóm công cụ đơn giản nhất là **chọn theo hình học**: kéo chuột để tạo một khung **hình chữ nhật** hoặc một vùng **hình ellip** (bầu dục). Em bấm giữ chuột ở một góc, kéo chéo sang góc đối diện là được một vùng chọn gọn gàng, cạnh thẳng tắp.\n\nKiểu chọn này nhanh và chính xác khi chủ thể vốn có dạng vuông vắn hoặc tròn: cắt một tấm ảnh thành khung vuông để làm ảnh đại diện, khoanh một tấm bảng thông báo, lấy phần logo hình tròn. Nhưng nó bó tay với những hình dạng tự do như một con người hay một cái cây — vì thân người đâu có nằm gọn trong một hình chữ nhật."},{"t":"h","text":"3) Chọn theo màu: khi nền một màu"},{"t":"text","text":"Công cụ **chọn theo màu** (đũa thần) hoạt động theo nguyên tắc: em bấm vào một điểm, phần mềm tự động chọn tất cả những điểm ảnh có **màu gần giống** điểm đó và nằm liền kề. Nếu chủ thể đặt trên một nền **một màu đồng nhất** — chẳng hạn tấm ảnh chân dung chụp trước phông xanh hoặc phông trắng — thì chỉ cần bấm vào nền là cả nền được chọn ngay, rồi em đảo vùng chọn lại để lấy đúng chủ thể.\n\nĐộ nhạy của công cụ được điều chỉnh bằng thông số **dung sai** (tolerance): dung sai nhỏ thì chỉ chọn màu thật sát nhau, dung sai lớn thì gộp cả những sắc màu chênh nhiều hơn. Đây là lí do ảnh thẻ luôn được yêu cầu chụp trên phông nền trơn một màu — để việc tách nền sau này dễ dàng và sạch sẽ."},{"t":"h","text":"4) Chọn tự do và điều chỉnh vùng chọn"},{"t":"text","text":"Với chủ thể có đường viền phức tạp, em dùng nhóm **chọn tự do**: kiểu vẽ tay đi theo mép chủ thể như cầm bút chì tô quanh, hoặc kiểu bấm lần lượt các điểm để tạo một đường gấp khúc bám sát viền. Kiểu này đòi hỏi tay khéo và kiên nhẫn, nhưng cho phép bám theo hình dạng bất kì.\n\nHiếm khi em chọn đúng ngay lần đầu, nên mọi công cụ đều cho phép **cộng thêm** hoặc **bớt đi** khỏi vùng chọn đang có (thường bằng cách giữ phím bổ trợ trong lúc chọn tiếp). Nhờ vậy em có thể phối hợp nhiều công cụ: dùng chọn theo màu để lấy nhanh phần lớn, rồi dùng chọn tự do để dặm lại những chỗ máy chọn sót hoặc chọn lố. Chọn khéo là biết kết hợp, không nhất thiết chỉ dùng một công cụ."},{"t":"h","text":"5) Làm mềm mép để ghép tự nhiên"},{"t":"text","text":"Một vùng chọn cắt ra với mép **sắc lẹm** khi dán sang nền mới thường lộ rõ là ảnh ghép: viền cứng như dùng kéo cắt giấy, đôi khi còn dính một vệt màu của nền cũ. Để khắc phục, phần mềm cho phép **làm mềm mép** vùng chọn (feather): biến đường ranh giới đột ngột thành một dải chuyển tiếp mờ dần vài điểm ảnh, giúp chủ thể hoà vào nền mới êm hơn.\n\nMức làm mềm phải **vừa phải**: quá ít thì mép vẫn cứng, quá nhiều thì chủ thể bị mờ nhoè cả viền, nhất là ở tóc. Với ảnh sản phẩm rao bán, mép mềm nhẹ giúp món hàng nằm gọn trên phông trắng trông chuyên nghiệp; với ảnh ghép người như kỉ yếu của lớp Nam, làm mềm mép đúng mức khiến các bạn trông như thật sự cùng đứng dưới một bầu trời."},{"t":"note","text":"Bẫy thường gặp: nghĩ rằng cứ **xoá** phần nền là tách được chủ thể. Xoá trực tiếp vừa chậm vừa dễ ăn lẹm vào người, lại không thể lấy lại. Cách đúng là **khoanh vùng chọn** chủ thể trước rồi mới tách — nền tự bị bỏ lại, và nếu chọn chưa khớp em vẫn cộng/bớt vùng chọn để sửa được."}],"keypoints":["**Vùng chọn** khoanh phần ảnh cần xử lí để thao tác chỉ tác động đúng phần đó; đây là chìa khoá để **tách chủ thể khỏi nền**.","**Chọn hình học** (chữ nhật/ellip) hợp với hình vuông vắn; **chọn theo màu** hợp khi nền một màu đồng nhất, chỉnh bằng **dung sai**; **chọn tự do** bám được viền phức tạp.","Có thể **cộng thêm** hoặc **bớt đi** khỏi vùng chọn và phối hợp nhiều công cụ để chọn cho khớp.","**Làm mềm mép** vừa phải giúp ảnh ghép tự nhiên; nên khoanh chọn rồi tách chứ không xoá trực tiếp phần nền."],"quiz":["UB-mc-1101","UB-mc-1102","UB-mc-1103","UB-mc-1104","UB-mc-1105","UB-tf-1101","UB-tf-1102","UB-tf-1103","UD2-mc-041","UD2-mc-042","UD2-mc-043","UD2-mc-044","UD2-tf-021","UD2-tf-022"]},
    {"id":"U11-12","stage":23,"order":12,"topic":"E","grade":11,"minutes":12,"title":"Công cụ vẽ, tô màu và thêm chữ lên ảnh","intro":"Sau khi biết chọn vùng và tách nền, bước tiếp theo là **vẽ thêm, tô màu và ghi chữ** ngay trên ảnh. Đây là kĩ năng để biến một tấm ảnh thường thành **poster, thiệp hay ảnh bìa** có thông điệp rõ ràng.","sections":[{"t":"story","text":"Lớp 11A2 chuẩn bị làm một tấm thiệp chúc mừng để tặng cô giáo chủ nhiệm nhân ngày 20/11. Nhóm của Minh đã có sẵn một bức ảnh chụp cả lớp đứng trước sân trường, màu sắc khá đẹp, nhưng nhìn vào thì chưa ai biết đó là tấm thiệp gì.\n\nBạn nhóm trưởng bảo: cần vẽ thêm một dải màu ở mép ảnh cho nổi, khoanh tròn vào gương mặt cô giáo cho ai cũng nhận ra, và quan trọng nhất là ghi dòng chữ lớn \"Kính chúc Cô 20/11\" ngay phía trên. Nghe thì đơn giản, nhưng khi mở phần mềm lên, cả nhóm lại lúng túng: bấm vào đâu để vẽ, chọn màu ở chỗ nào, và làm sao để chữ nằm đè lên ảnh mà vẫn đọc được?\n\nHoá ra, những việc đó chỉ cần vài công cụ vẽ, một bảng chọn màu và một công cụ chữ. Bài học này sẽ giúp em làm chủ đúng ba nhóm công cụ đó."},{"t":"h","text":"1) Bảng chọn màu: màu vẽ và màu nền"},{"t":"text","text":"Trước khi vẽ bất cứ nét nào, phần mềm luôn cần biết em muốn dùng **màu gì**. Vì thế trên giao diện luôn có một khu vực chọn màu, thường hiển thị **hai ô màu**: một là **màu vẽ** (màu của nét bút, của chữ) và một là **màu nền** (màu dùng khi xoá hoặc tô vùng trống). Nhấp vào ô màu sẽ mở ra một bảng để em kéo chọn sắc màu và độ đậm nhạt.\n\nCó ba cách chọn màu thường gặp. Cách trực quan nhất là kéo con trỏ trên **vòng màu hoặc ô màu** để tìm sắc mong muốn. Cách chính xác hơn là nhập **mã màu** dạng sáu kí tự như `#E53935` (đỏ tươi) để lấy đúng một màu quy định. Cách tiện lợi nhất khi muốn lấy lại đúng màu đã có trên ảnh là dùng công cụ **hút màu** (biểu tượng ống hút): nhấp vào một điểm trên ảnh, phần mềm sẽ lấy chính màu đó làm màu vẽ."},{"t":"h","text":"2) Bộ công cụ vẽ và tô"},{"t":"list","text":"Các phần mềm chỉnh sửa ảnh thường có sẵn một nhóm công cụ vẽ với vai trò khác nhau:","items":["Bút vẽ: kéo chuột để vạch nét theo tay, dùng vẽ đường viền, khoanh tròn, gạch chân.","Tô màu (thùng sơn): nhấp một lần để đổ màu kín cả một vùng cùng màu, hợp để tô nền phẳng.","Gôm tẩy: xoá phần đã vẽ, biến vùng đó về màu nền hoặc thành trong suốt.","Hình khối: vẽ nhanh hình chữ nhật, hình tròn, đường thẳng có kích thước đều đặn.","Cỡ nét (brush size): số càng lớn nét càng dày; luôn chọn cỡ nét trước khi vẽ."]},{"t":"text","text":"Điểm mấu chốt khi vẽ là **cỡ nét** và **độ mờ**. Cỡ nét quyết định nét mảnh hay dày; độ mờ (opacity) quyết định nét đè lên ảnh đậm đặc hay chỉ phủ nhẹ như một lớp màu trong. Khi muốn tô một mảng màu nhấn nhá mà vẫn nhìn thấy ảnh bên dưới, em giảm độ mờ xuống, ví dụ còn khoảng một nửa.\n\nMột thói quen tốt là **vẽ trên một lớp mới** thay vì vẽ thẳng lên ảnh gốc. Nhờ đó, nếu nét vẽ chưa ưng ý, em chỉ cần xoá lớp đó là ảnh gốc vẫn nguyên vẹn, không phải làm lại từ đầu."},{"t":"h","text":"3) Thêm chữ lên ảnh"},{"t":"text","text":"Để ghi chữ, em chọn **công cụ văn bản** (thường có biểu tượng chữ `T`), nhấp vào vị trí muốn đặt rồi gõ nội dung. Ngay khi tạo chữ, phần mềm sẽ sinh ra một **lớp chữ riêng** — đây là điểm rất hay, vì lớp chữ tách khỏi ảnh nên em có thể sửa nội dung, đổi phông, đổi màu hay di chuyển chữ bao nhiêu lần cũng được mà không đụng đến ảnh.\n\nVới mỗi dòng chữ, em điều chỉnh được **phông chữ** (kiểu chữ), **cỡ chữ** (đo bằng điểm, cỡ lớn thì chữ to), **màu chữ** và cách canh lề trái, giữa, phải. Chữ tiêu đề thì để cỡ lớn, đậm; chữ ghi chú nhỏ thì để cỡ vừa. Muốn chữ rõ trên nền ảnh rối, em thêm **viền hoặc bóng đổ** cho chữ để nó tách khỏi nền phía sau.\n\nMột bẫy hay gặp là chọn màu chữ **trùng hoặc gần giống** màu nền phía sau khiến chữ chìm mất, đọc không ra. Nguyên tắc là nền sáng thì dùng chữ tối, nền tối thì dùng chữ sáng; khi nền nhiều màu, hãy thêm viền chữ hoặc một dải màu mờ phía sau chữ để tăng độ tương phản."},{"t":"h","text":"4) Lưu file: bản có lớp và bản xuất cuối"},{"t":"text","text":"Khi đã kết hợp hình, nét vẽ và chữ, em có **nhiều lớp** chồng lên nhau. Muốn giữ khả năng chỉnh sửa về sau, hãy lưu một bản ở **định dạng gốc của phần mềm** — định dạng này **giữ nguyên các lớp riêng biệt**, mở lại vẫn sửa từng lớp được.\n\nNhưng bản có lớp thường chỉ mở được bằng đúng phần mềm đó và dung lượng lớn. Vì vậy để gửi cho bạn bè, in ra hay đăng lên mạng, em cần **xuất** thêm một bản ở định dạng ảnh phổ thông. Lúc xuất, mọi lớp sẽ được **gộp phẳng** thành một ảnh duy nhất, không sửa từng lớp được nữa."},{"t":"example","text":"So sánh hai định dạng ảnh xuất phổ biến khi làm thiệp lớp 11A2:","code":"Định dạng PNG:\n  - Giữ được vùng trong suốt (nền đã tách)\n  - Nét, chữ sắc, không bị nhoè\n  - Dung lượng lớn hơn\n\nĐịnh dạng JPG:\n  - Không giữ được vùng trong suốt\n  - Ảnh nhiều màu, dung lượng nhẹ\n  - Nén nhiều có thể làm chữ hơi rạn","output":"Chọn PNG cho thiệp có chữ và vùng trong suốt; chọn JPG cho ảnh chụp nhiều màu cần dung lượng nhẹ để gửi nhanh."},{"t":"note","text":"Quy tắc an toàn: luôn giữ lại **bản gốc có lớp** rồi mới xuất bản PNG/JPG để chia sẻ. Nếu chỉ lưu bản JPG rồi xoá bản gốc, hôm sau muốn sửa lại dòng chữ hay đổi màu nét, em sẽ không tách được chúng ra khỏi ảnh nữa; hãy đặt tên rõ ràng để phân biệt bản gốc và bản xuất."}],"keypoints":["Chọn **màu vẽ** trước khi vẽ; dùng **mã màu** để lấy đúng màu hoặc **hút màu** để lấy lại màu có sẵn trên ảnh.","Nắm vai trò **bút vẽ, tô màu, gôm tẩy**; chỉnh **cỡ nét** và **độ mờ**, nên vẽ trên **lớp mới** để dễ sửa.","Công cụ **văn bản** tạo **lớp chữ riêng**; chỉnh phông, cỡ, màu và thêm viền để chữ tương phản, đọc rõ.","Lưu **bản gốc có lớp** để sửa về sau; **xuất PNG/JPG** (gộp phẳng) để chia sẻ, in hoặc đăng."],"quiz":["UB-mc-1201","UB-mc-1202","UB-mc-1203","UB-mc-1204","UB-mc-1205","UB-tf-1201","UB-tf-1202","UB-tf-1203","UD2-mc-045","UD2-mc-046","UD2-mc-047","UD2-mc-048","UD2-tf-023","UD2-tf-024"]},
    {"id":"U11-13","stage":23,"order":13,"topic":"E","grade":11,"minutes":12,"title":"Tạo ảnh động từ nhiều khung hình","intro":"Bài này giúp em tự làm một **ảnh động** đơn giản như quả bóng nảy hay dòng chữ nhấp nháy. Em sẽ hiểu ảnh động thực chất là một chuỗi **khung hình** (`frame`) chiếu nối tiếp thật nhanh, và biết chỉnh **thời gian hiển thị** cùng **số khung mỗi giây** để chuyển động mượt hay giật theo ý mình.","sections":[{"t":"story","text":"Nhóm của Lan nhận nhiệm vụ làm một tấm ảnh nhỏ nhấp nháy để dán vào bài giới thiệu câu lạc bộ trên trang tin của trường. Ý tưởng đơn giản thôi: một quả bóng rổ nảy lên rồi rơi xuống, lặp đi lặp lại cho vui mắt.\n\nLan lục lại kỉ niệm hồi bé xem 'phim' tự chế: bạn vẽ một người chạy vào từng góc quyển vở, mỗi trang nhích một chút, rồi lật thật nhanh cho hình như đang cử động. Cả nhóm reo lên vì nhận ra ảnh động cần làm y hệt vậy, chỉ khác là lật bằng máy tính.\n\nVấn đề là quả bóng phải nhích bao nhiêu mỗi lần, cần bao nhiêu tấm, mỗi tấm hiện bao lâu thì mắt mới thấy 'nảy' mượt chứ không giật cục. Đó chính là mấy điều bài học hôm nay sẽ trả lời."},{"t":"h","text":"1) Ảnh động là gì"},{"t":"text","text":"**Ảnh động** là một tệp ảnh chứa nhiều hình tĩnh xếp theo thứ tự, được máy chiếu nối tiếp thật nhanh nên mắt ta thấy như đang chuyển động. Mỗi hình tĩnh trong chuỗi đó gọi là một **khung hình** (`frame`). Khi các khung hình chỉ khác nhau một chút và thay nhau đủ nhanh, bộ não tự 'nối' chúng lại thành một cử động liền mạch.\n\nĐây chính là nguyên lí của cuốn vở lật hình mà Lan từng chơi: mỗi trang là một khung hình, lật nhanh thì nhân vật như biết chạy. Định dạng ảnh động phổ biến trên web thường lặp lại chuỗi khung hình mãi mãi, nên quả bóng của Lan sẽ nảy đi nảy lại không dừng mà không cần bấm nút phát."},{"t":"h","text":"2) Mỗi khung hình là một tấm ảnh riêng"},{"t":"text","text":"Trong phần mềm chỉnh sửa ảnh, cách làm quen thuộc là để **mỗi khung hình trên một lớp riêng**. Em vẽ tư thế đầu tiên của quả bóng trên một lớp, rồi tạo lớp mới cho tư thế tiếp theo với quả bóng nhích lên một chút, cứ thế cho hết một vòng chuyển động. Khi bật chế độ xem ảnh động, phần mềm sẽ hiện lần lượt từng lớp thay vì chồng tất cả lên nhau như ảnh tĩnh.\n\nĐặt mỗi khung một lớp có cái lợi lớn: muốn sửa dáng bóng ở giữa chừng, em chỉ chỉnh đúng lớp đó mà không phải vẽ lại cả chuỗi. Em cũng nên đặt tên lớp theo thứ tự như `khung-1`, `khung-2` để không bị lẫn, vì thứ tự các khung quyết định chuyển động diễn ra đúng chiều."},{"t":"h","text":"3) Thời gian hiển thị mỗi khung"},{"t":"text","text":"Mỗi khung hình có một **thời gian hiển thị**, tức là nó nằm trên màn hình bao lâu trước khi nhường chỗ cho khung sau. Thời gian này thường tính bằng phần trăm giây hay mili giây. Khung để lâu thì chuyển động chậm và giật; khung để ngắn thì chuyển động nhanh và mượt hơn.\n\nĐiều hay là em có thể cho các khung thời gian **khác nhau**. Chẳng hạn dòng chữ nhấp nháy: khung 'chữ sáng' để `500` mili giây, khung 'chữ mờ' cũng `500` mili giây thì nhấp nháy đều đặn; nhưng nếu muốn chữ sáng lâu hơn thì cho khung sáng `800` và khung mờ `200`. Với quả bóng nảy, Lan có thể để khung lúc bóng chạm đất dừng lâu hơn một chút cho có cảm giác 'nặng'."},{"t":"h","text":"4) Số khung mỗi giây và độ mượt"},{"t":"text","text":"**Số khung mỗi giây** (`fps`, viết tắt của frames per second) cho biết trong một giây có bao nhiêu khung được chiếu. Số này càng lớn thì trong cùng một khoảng thời gian càng nhiều khung, mỗi bước nhích càng nhỏ, nên chuyển động càng mượt. Ảnh động vui vui trên web thường dùng khoảng `10` đến `15` khung mỗi giây là đủ đẹp; phim chiếu rạp thì cỡ `24` khung mỗi giây trở lên.\n\nCó một sự đánh đổi cần nhớ: nhiều khung hơn thì mượt hơn nhưng tệp cũng nặng hơn và làm lâu hơn vì phải vẽ nhiều tấm. Vì vậy khi làm ảnh động đơn giản, em chọn số khung vừa đủ để chuyển động trông tự nhiên chứ không nhất thiết phải thật nhiều. Quả bóng nảy chỉ cần chừng tám đến mười hai khung cho một vòng lên xuống là đã khá mượt."},{"t":"list","text":"Các bước chung để Lan làm quả bóng nảy trong phần mềm chỉnh sửa ảnh:","items":["Vẽ khung đầu tiên trên một lớp, ví dụ quả bóng ở đỉnh cao nhất","Nhân đôi lớp và dịch quả bóng xuống một chút để thành khung tiếp theo","Lặp lại cho tới khi có đủ chuỗi khung của một vòng nảy hoàn chỉnh","Đặt thời gian hiển thị cho từng khung và chọn số khung mỗi giây","Bật xem thử ảnh động, chỉnh lại khung nào bị giật cho mượt","Xuất ra tệp ảnh động có lặp để dán vào bài viết"]},{"t":"example","text":"Hình dung chuỗi khung của một vòng bóng nảy, đọc từ trên xuống đúng theo thứ tự chiếu:","code":"khung-1: bóng ở đỉnh        (thời gian 120 ms)\nkhung-2: bóng xuống giữa     (thời gian 100 ms)\nkhung-3: bóng gần đất        (thời gian 100 ms)\nkhung-4: bóng chạm đất, dẹt  (thời gian 150 ms)\nkhung-5: bóng bật lên giữa   (thời gian 100 ms)\nkhung-6: bóng gần đỉnh       (thời gian 120 ms)\n[lặp lại từ khung-1]","output":"Chiếu nối tiếp sáu khung rồi lặp lại tạo cảm giác quả bóng nảy đều. Khung chạm đất để lâu hơn (150 ms) nên trông bóng như dừng một nhịp trước khi bật lên. Nếu giảm mọi thời gian xuống một nửa, cả chuỗi chạy nhanh gấp đôi và bóng nảy dồn dập hơn."},{"t":"note","text":"Bẫy thường gặp: sắp xếp thứ tự khung bị ngược nên bóng 'nảy giật lùi', hoặc quên bật chế độ lặp khiến ảnh chỉ chạy một lần rồi đứng im. Ngoài ra nhiều bạn nhồi quá nhiều khung cho một cử động ngắn làm tệp nặng mà mắt gần như không thấy mượt thêm; hãy tăng số khung vừa phải và xem thử trước khi xuất."}],"keypoints":["**Ảnh động** là chuỗi **khung hình** (`frame`) chiếu nối tiếp thật nhanh khiến mắt thấy chuyển động","Mỗi khung hình thường đặt trên một **lớp riêng**; thứ tự các khung quyết định chiều chuyển động","**Thời gian hiển thị** của từng khung có thể khác nhau, điều chỉnh nhịp nhanh chậm của cử động","**Số khung mỗi giây** (`fps`) càng lớn càng mượt nhưng tệp càng nặng; chọn vừa đủ tự nhiên"],"quiz":["UB-mc-1301","UB-mc-1302","UB-mc-1303","UB-mc-1304","UB-mc-1305","UB-tf-1301","UB-tf-1302","UB-tf-1303","UD2-mc-049","UD2-mc-050","UD2-mc-051","UD2-mc-052","UD2-tf-025","UD2-tf-026"]},
    {"id":"U11-14","stage":23,"order":14,"topic":"E","grade":11,"minutes":12,"title":"Làm quen phần mềm làm phim: dòng thời gian và clip","intro":"Sau khi đã biết chỉnh ảnh và tạo ảnh động, bước tiếp theo là ghép nhiều đoạn quay và ảnh thành một **đoạn phim**. Bài này giúp em làm quen giao diện phần mềm dựng phim, hiểu **dòng thời gian** (`timeline`) và cách sắp các `clip` lên đó.","sections":[{"t":"story","text":"Lớp em vừa đi trải nghiệm ở làng gốm về. Trong máy điện thoại có mấy chục đoạn quay ngắn: cảnh xe khởi hành, bạn Lan nặn đất, cô hướng dẫn nung gốm, rồi cả lớp chụp ảnh tập thể. Ngoài ra còn vài tấm ảnh đẹp và một bản nhạc không lời tải sẵn.\n\nCô giáo giao nhiệm vụ: gộp tất cả thành một đoạn phim kỷ niệm dài khoảng hai phút để chiếu trong buổi tổng kết. Nếu chỉ mở từng đoạn quay cho cả lớp xem lần lượt thì vừa rời rạc vừa lộn xộn, lúc to lúc nhỏ, chẳng có nhạc nền.\n\nEm cần một công cụ để xếp các đoạn quay theo thứ tự em muốn, cắt bớt chỗ thừa, chèn ảnh vào giữa và thêm nhạc chạy suốt phim. Công cụ đó chính là phần mềm làm phim, và không gian làm việc cốt lõi của nó là một dải nằm ngang gọi là dòng thời gian."},{"t":"h","text":"1) Phần mềm làm phim dùng để làm gì"},{"t":"text","text":"**Phần mềm làm phim** (còn gọi là phần mềm dựng phim, biên tập video) là công cụ giúp em ghép nhiều tư liệu rời rạc thành một đoạn phim hoàn chỉnh. Tư liệu ở đây gồm các đoạn quay (video), ảnh tĩnh và các tệp âm thanh.\n\nKhác với việc chỉ phát lần lượt từng đoạn, phần mềm làm phim cho phép em **sắp xếp thứ tự**, **cắt bỏ** phần thừa, **chèn** thêm cảnh vào giữa và điều khiển đoạn nào xuất hiện lúc nào. Toàn bộ công việc đó diễn ra trên một khu vực gọi là dòng thời gian."},{"t":"h","text":"2) Dòng thời gian (timeline)"},{"t":"text","text":"**Dòng thời gian** (`timeline`) là dải nằm ngang biểu diễn thời gian trôi của phim, thường tính từ trái sang phải. Vị trí càng về bên phải thì càng ứng với thời điểm muộn hơn trong phim. Một vạch dọc gọi là **con trỏ thời gian** (đầu phát) chỉ ra khoảng khắc đang được xem.\n\nMỗi đoạn tư liệu em đưa vào phim sẽ hiện ra như một khối hình chữ nhật đặt trên dòng thời gian, gọi là **clip**. Chiều dài của khối phản ánh **thời lượng**: clip càng dài thì phần đó phát càng lâu. Em kéo các clip xích lại gần nhau để chúng phát nối tiếp, hoặc kéo tách ra để tạo khoảng trống."},{"t":"h","text":"3) Clip và các rãnh (track)"},{"t":"text","text":"**Clip** là một mẩu tư liệu đã được đặt lên dòng thời gian: có thể là một đoạn video, một ảnh, hoặc một đoạn âm thanh. Cùng một tệp gốc có thể tạo ra nhiều clip, và việc cắt ngắn một clip **không làm hỏng** tệp gốc trong máy.\n\nDòng thời gian được chia thành nhiều **rãnh** (`track`) xếp chồng nhau. Thông thường có rãnh dành cho hình (video, ảnh) và rãnh dành cho âm thanh (lời thoại, nhạc nền). Nhờ nhiều rãnh, tại cùng một thời điểm em có thể vừa cho hiện hình ảnh chuyến đi vừa cho chạy nhạc nền bên dưới."},{"t":"h","text":"4) Khung hình mỗi giây và độ phân giải"},{"t":"text","text":"Phim thực chất là nhiều ảnh tĩnh phát rất nhanh liên tiếp để mắt thấy chuyển động mượt. Số ảnh phát trong một giây gọi là **khung hình mỗi giây** (`fps`, frames per second). Giá trị phổ biến là khoảng 24 đến 30 fps; fps càng cao thì chuyển động trông càng mượt nhưng tệp phim càng nặng.\n\n**Độ phân giải** cho biết mỗi khung hình có bao nhiêu điểm ảnh theo chiều ngang và chiều dọc, ví dụ `1280x720` hay `1920x1080`. Độ phân giải càng cao thì hình càng nét, chi tiết càng rõ, nhưng tệp cũng lớn hơn và máy yếu có thể xử lí chậm. Khi bắt đầu dự án, em thường chọn trước fps và độ phân giải cho cả phim."},{"t":"h","text":"5) Nhập tư liệu và xem trước"},{"t":"text","text":"Trước khi dựng, em phải **nhập tư liệu** (`import`): đưa các tệp video, ảnh, âm thanh từ máy vào phần mềm. Chúng hiện ra trong một khu chứa (thường gọi là thư viện hoặc kho tư liệu). Nhập tư liệu chỉ **liên kết** phần mềm tới tệp gốc, nên em không nên xoá hay đổi tên tệp gốc giữa chừng, kẻo phần mềm báo mất tư liệu.\n\nTừ kho, em kéo tư liệu xuống dòng thời gian để tạo clip. Cửa sổ **xem trước** (`preview`) cho phép em bấm phát để kiểm tra kết quả tại vị trí con trỏ thời gian, mà chưa cần kết xuất phim. Nhờ xem trước, em phát hiện chỗ ghép chưa khớp, nhạc to quá hay cảnh còn thừa để sửa ngay."},{"t":"example","text":"Phác bố trí dòng thời gian cho đoạn phim làng gốm (mỗi ô là một clip, đọc từ trái sang phải theo thời gian):","code":"Rãnh hình :  [Xe khởi hành] [Ảnh cổng làng] [Nặn gốm] [Cả lớp chụp]\nRãnh nhạc :  [========== Nhạc nền chạy suốt phim ==========]\nCon trỏ   :        ^ đang xem tại đây","output":"Khi bấm phát ở cửa sổ xem trước, phim chạy nối tiếp bốn cảnh trên rãnh hình, trong khi bản nhạc ở rãnh dưới phát liền mạch từ đầu đến cuối làm nền."}],"keypoints":["**Phần mềm làm phim** ghép video, ảnh, âm thanh thành một đoạn phim hoàn chỉnh trên **dòng thời gian** (`timeline`).","Mỗi tư liệu đặt lên dòng thời gian là một **clip**; chiều dài clip là thời lượng, và các clip nằm trên các **rãnh** (`track`) khác nhau.","**Khung hình mỗi giây** (`fps`) quyết định độ mượt, **độ phân giải** quyết định độ nét; cả hai càng cao thì tệp càng nặng.","Phải **nhập tư liệu** (`import`) trước khi dựng và dùng cửa sổ **xem trước** (`preview`) để kiểm tra; tệp gốc không được xoá giữa chừng."],"quiz":["UB-mc-1401","UB-mc-1402","UB-mc-1403","UB-mc-1404","UB-mc-1405","UB-tf-1401","UB-tf-1402","UB-tf-1403","UD2-mc-053","UD2-mc-054","UD2-mc-055","UD2-mc-056","UD2-tf-027","UD2-tf-028"]},
    {"id":"U11-15","stage":23,"order":15,"topic":"E","grade":11,"minutes":12,"title":"Biên tập phim: cắt ghép, chuyển cảnh, âm thanh và xuất phim","intro":"Bài này đưa em đi trọn một vòng biên tập một đoạn phim ngắn: **cắt** bớt phần thừa của từng clip, **ghép** các đoạn theo mạch kể chuyện, thêm **chuyển cảnh** (`transition`) và **âm thanh**, rồi cuối cùng **xuất phim** (`export`) ra một tệp video chia sẻ được.","sections":[{"t":"story","text":"Câu lạc bộ nhiếp ảnh trường của Hà vừa đi dã ngoại về, trong máy có gần hai chục đoạn quay: cảnh cả nhóm lên xe, con đường quê, bữa trưa bên suối, trò chơi tập thể và tấm hình chụp chung cuối ngày. Cô chủ nhiệm giao cho Hà làm một video ba phút chiếu trong buổi sinh hoạt cuối tuần.\n\nHà đưa hết các đoạn quay vào phần mềm làm phim, xếp nối đuôi nhau rồi bấm phát thử. Kết quả dài tới mười hai phút, nhiều đoạn quay hụt còn rung máy, chỗ chuyển từ cảnh này sang cảnh kia thì giật cục, và tiếng gió ù ù át cả lời các bạn nói. Xem xong ai cũng thấy 'nó chưa ra một cái phim'.\n\nCô giáo ngồi xuống cạnh Hà và nói: 'Quay được cảnh mới chỉ là nguyên liệu thôi. Giờ mới tới phần làm bếp: cắt bỏ chỗ thừa, sắp lại cho có đầu có cuối, nối các cảnh cho mượt, thêm chút nhạc rồi mới bưng ra mời mọi người.' Đó chính là công việc biên tập mà chúng ta học hôm nay."},{"t":"h","text":"1) Dòng thời gian, cắt và ghép clip"},{"t":"text","text":"Trong phần mềm làm phim, khu vực quan trọng nhất là **dòng thời gian** (`timeline`): một dải nằm ngang chạy từ trái sang phải theo thời gian, trái là lúc phim bắt đầu, phải là lúc phim kết thúc. Mỗi đoạn video em kéo vào đây thành một **clip**, hiện lên như một khối chữ nhật; khối càng dài thì clip chiếu càng lâu.\n\nCác clip đặt nối tiếp trên dòng thời gian sẽ được chiếu lần lượt đúng theo thứ tự từ trái qua phải. Nhờ vậy, muốn kể chuyện theo trình tự 'lên xe rồi tới suối rồi chơi trò chơi', Hà chỉ cần xếp các khối clip theo đúng thứ tự đó. Một vạch thẳng đứng gọi là **con trỏ thời gian** (`playhead`) cho biết đang xem tới giây nào của phim, kéo con trỏ tới đâu thì khung hình ở màn hình xem thử hiện tới đó."},{"t":"text","text":"**Cắt** (`trim`) là thao tác bỏ bớt phần đầu hoặc phần cuối thừa của một clip mà không đụng tới tệp quay gốc. Em kéo mép trái hoặc mép phải của khối clip vào trong để 'giấu' phần không muốn dùng, hoặc đặt con trỏ thời gian tại một điểm rồi bấm lệnh cắt để tách clip thành hai đoạn, sau đó xoá đoạn hỏng. Đoạn quay rung tay lúc bắt đầu hay khoảng lặng thừa ở cuối đều được dọn theo cách này.\n\n**Ghép** là sắp các clip đã cắt gọn lại nối tiếp nhau cho liền mạch. Sau khi cắt, giữa các clip có thể còn khoảng trống, em kéo các khối sát lại để phim chạy không bị đứng hình. Thứ tự các khối trên dòng thời gian chính là mạch kể chuyện: kéo đổi vị trí hai khối là đổi luôn thứ tự cảnh trong phim. Vì cắt ghép chỉ tác động lên clip trên dòng thời gian, tệp video gốc trong máy vẫn nguyên vẹn, làm hỏng thì luôn kéo lại được."},{"t":"h","text":"2) Chuyển cảnh (transition) cho mượt mối nối"},{"t":"text","text":"Khi hai clip đặt sát nhau, mặc định phim nhảy 'cụp' từ cảnh này sang cảnh kia. Để mối nối mềm hơn, em thêm **chuyển cảnh** (`transition`) vào chỗ giáp ranh giữa hai clip. Chuyển cảnh hay dùng nhất là **mờ dần** (`fade`): cảnh trước nhạt dần rồi cảnh sau hiện lên, hoặc **hoà tan** (`dissolve`) hai cảnh chồng lên nhau trong khoảnh khắc. Ngoài ra còn kiểu **trượt** (`slide`), cảnh mới đẩy cảnh cũ ra khỏi khung.\n\nChuyển cảnh có **thời lượng** riêng, thường nửa giây tới một giây; đặt quá dài sẽ khiến phim lê thê và làm mất vài giây nội dung ở hai đầu clip. Nguyên tắc thực hành là dùng chuyển cảnh có chừng mực: một hiệu ứng nhẹ giữa hai đoạn khác hẳn nhau về bối cảnh là đủ, không cần cảnh nào cũng thêm cho 'hoành tráng', vì lạm dụng làm người xem mệt mắt và phim thiếu tự nhiên."},{"t":"h","text":"3) Âm thanh: nhạc nền, lời thoại và âm lượng"},{"t":"text","text":"Phim thường có nhiều lớp tiếng chồng lên nhau, xếp trên các **rãnh âm thanh** (`audio track`) riêng nằm dưới rãnh hình. Có ba nguồn tiếng hay gặp: tiếng thu sẵn ngay trong clip (lời các bạn nói, tiếng suối chảy), **nhạc nền** kéo thêm vào từ một tệp nhạc, và **lời thoại** thuyết minh em thu thêm rồi đặt vào đúng đoạn cần.\n\nMấu chốt của phần tiếng là chỉnh **âm lượng** (`volume`) sao cho các lớp không lấn nhau: nhạc nền phải hạ nhỏ lại để không át lời nói, còn đoạn gió ù ù có thể giảm hẳn hoặc tắt tiếng gốc của clip. Hai kĩ thuật quen thuộc là **fade in** cho tiếng to dần lên ở đầu và **fade out** cho tiếng nhỏ dần đi ở cuối, giúp nhạc vào và ra êm chứ không bật tắt đột ngột. Rãnh tiếng cũng nằm trên dòng thời gian, nên em căn cho nhạc bắt đầu đúng lúc hình bắt đầu là được."},{"t":"h","text":"4) Xuất phim (export) ra tệp video"},{"t":"text","text":"Khi xem thử thấy ổn, dòng thời gian mới chỉ là 'bản dựng' bên trong phần mềm, chưa phải một tệp phim hoàn chỉnh. Bước **xuất phim** (`export`), còn gọi là **kết xuất** (`render`), sẽ gộp tất cả clip, chuyển cảnh và các rãnh tiếng lại, tính toán từng khung hình rồi ghi thành một **tệp video** duy nhất mở được ở mọi máy, ví dụ tệp `.mp4`.\n\nKhi xuất, phần mềm hỏi vài lựa chọn: **định dạng** tệp, **độ phân giải** (như `1920 x 1080`) và **mức chất lượng**. Chất lượng càng cao thì hình càng nét nhưng tệp càng nặng và xuất càng lâu; nộp bài chiếu trên máy chiếu lớp thì mức phổ thông đã đủ, còn gửi qua mạng cho nhẹ thì hạ bớt. Quá trình xuất chạy một lúc mới xong, và nên xem lại tệp thành phẩm một lượt trước khi nộp phòng khi có đoạn nào lỗi."},{"t":"example","text":"Hình dung dòng thời gian phim ba phút của Hà sau khi biên tập xong, đọc từ trái sang phải theo thời gian chiếu:","code":"Rãnh hình:  [len-xe]--(fade)--[con-duong]----[bua-trua]--(fade)--[tro-choi]--[anh-chung]\nRãnh nhạc:  [~~~~~~~~ nhac-nen (fade in) ~~~~~~~~~~~~~~~~~~~~~~~~~~ (fade out) ~~~~~~~]\nRãnh thoại: .............[loi-thuyet-minh].......................................","output":"Phim chạy lần lượt: lên xe, mờ dần sang con đường, tới bữa trưa, mờ dần sang trò chơi, khép lại bằng tấm ảnh chung. Nhạc nền chạy suốt, to dần ở đầu và nhỏ dần ở cuối; lời thuyết minh chỉ vang lên ở đoạn con đường. Bấm xuất phim sẽ gộp cả ba rãnh này thành một tệp .mp4 duy nhất."},{"t":"note","text":"Bẫy thường gặp: quên rằng cắt trên dòng thời gian không xoá tệp quay gốc, nên nhiều bạn xoá luôn tệp trong máy rồi mở lại thì phim báo 'thiếu nguyên liệu'. Hãy giữ nguyên các tệp quay gốc cho tới khi xuất phim xong. Một bẫy khác: xem thử thấy hay nhưng quên bước xuất phim, nên chỉ có bản dựng trong phần mềm mà không có tệp video để nộp hay gửi cho bạn."}],"keypoints":["**Dòng thời gian** (`timeline`) xếp các **clip** từ trái sang phải; thứ tự các khối chính là mạch kể chuyện của phim","**Cắt** (`trim`) bỏ phần thừa và **ghép** cho liền mạch chỉ tác động trên clip, tệp quay gốc vẫn nguyên vẹn","**Chuyển cảnh** (`transition`) làm mượt mối nối và chỉnh **âm lượng** để nhạc nền không át lời nói; dùng có chừng mực","**Xuất phim** (`export`/`render`) gộp mọi rãnh thành một **tệp video** duy nhất; chất lượng càng cao thì tệp càng nặng"],"quiz":["UB-mc-1501","UB-mc-1502","UB-mc-1503","UB-mc-1504","UB-mc-1505","UB-tf-1501","UB-tf-1502","UB-tf-1503","UD2-mc-057","UD2-mc-058","UD2-mc-059","UD2-mc-060","UD2-tf-029","UD2-tf-030"]}
  );
})();
